  const normalizeAndSanitizeAccount = (a: BankAccount): BankAccount => {
    const hasGoogle = isRealGoogleLinkedEmail(a.googleEmail || a.email);
    const normEmail = hasGoogle
      ? normalizeEmailKey(a.googleEmail || a.email || '')
      : normalizeEmailKey(a.email || '');
    return normalizeAdminAccountAssets({
      ...a,
      userId16: ensureAccountUserId16(a),
      email: normEmail || a.email || '',
      googleEmail: hasGoogle ? normEmail : a.googleEmail,
      // Jika sudah tersambung ke email Google di Firebase, otomatis statusnya BUKAN lagi Akun Guest
      isGuestAccount: hasGoogle ? false : Boolean(a.isGuestAccount),
      isOfficialAdminAccount: Boolean(a.isOfficialAdminAccount || a.id === 'acc-admin'),
      oaAdminPin: a.oaAdminPin || '159357',
      jobLevel: Math.max(1, Math.floor(Number(a.jobLevel) || 1)),
      levelVouchers: Math.max(0, Math.floor(Number(a.levelVouchers) || 0)),
      spinCoins: Math.max(0, Math.floor(Number(a.spinCoins) || 0)),
      diamonds: Math.max(0, Math.floor(Number(a.diamonds) || 0)),
      rewardPoints: Math.max(0, Math.floor(Number(a.rewardPoints) || 0)),
      extraFamilySlots: Math.max(0, Math.floor(Number(a.extraFamilySlots) || 0)),
      accountUpdatedAtMs: Number(a.accountUpdatedAtMs) || 0,
      unbannedAtMs: Number(a.unbannedAtMs) || 0,
      status:
        a.status === 'banned' || a.cardStatus === 'banned' || a.banInfo?.isBanned
          ? ('banned' as const)
          : ('active' as const),
      banReason: a.banReason || a.banInfo?.reason || '',
    });
  };

  // Gabungkan daftar akun dari berbagai vault (master_state, users/{uid}.savedAccounts, users_by_email/{emailKey}.savedAccounts, dan state lokal)
  // agar perangkat yang baru membuka halaman login tidak pernah bisa menimpa atau menghapus kartu yang dibuat di perangkat lain (HP <-> Laptop)
  const unionMergeAccountsList = (
    primaryList: BankAccount[],
    fallbackLists: (BankAccount[] | undefined)[],
    deletedIds: string[]
  ): BankAccount[] => {
    const delSet = new Set<string>([
      ...PURGED_BOT_ACCOUNT_IDS,
      ...deletedIds,
    ]);
    const map = new Map<string, BankAccount>();

    const pickFresherAccount = (existing: BankAccount | undefined, incoming: BankAccount): BankAccount => {
      if (!existing) return incoming;
      const existingTs = Number(existing.accountUpdatedAtMs) || 0;
      const incomingTs = Number(incoming.accountUpdatedAtMs) || 0;
      const existingUnbanTs = Number(existing.unbannedAtMs) || 0;
      const incomingUnbanTs = Number(incoming.unbannedAtMs) || 0;
      const existingIsBanned =
        existing.status === 'banned' ||
        existing.cardStatus === 'banned' ||
        Boolean(existing.banInfo?.isBanned);
      const incomingIsBanned =
        incoming.status === 'banned' ||
        incoming.cardStatus === 'banned' ||
        Boolean(incoming.banInfo?.isBanned);

      // Proteksi Anti-Rollback Unban: jangan biarkan cache ban lama menimpa akun yang baru dibuka blokirnya
      if (!existingIsBanned && incomingIsBanned && existingUnbanTs > 0 && existingUnbanTs >= incomingTs) {
        return existing;
      }
      if (!incomingIsBanned && existingIsBanned && incomingUnbanTs > 0 && incomingUnbanTs >= existingTs) {
        return incoming;
      }

      if (existingTs > incomingTs) {
        return existing;
      }
      if (incomingTs > existingTs) {
        return incoming;
      }
      // Jika timestamp sama, pastikan status kartu 'active' yang sudah disetujui Admin TIDAK PERNAH tertimpa balik ke 'pending'
      const preferActiveCardStatus =
        existing.cardStatus === 'active' && incoming.cardStatus === 'pending'
          ? 'active'
          : incoming.cardStatus;
      return {
        ...incoming,
        cardStatus: preferActiveCardStatus,
        unbannedAtMs: Math.max(existingUnbanTs, incomingUnbanTs) || undefined,
        tutorialApprovedByAdmin:
          Boolean(existing.tutorialApprovedByAdmin) || Boolean(incoming.tutorialApprovedByAdmin),
        hasCompletedTutorial:
          Boolean(existing.hasCompletedTutorial) || Boolean(incoming.hasCompletedTutorial),
        loginLockedUntil: incoming.loginLockedUntil || existing.loginLockedUntil,
        loginLockReason: incoming.loginLockReason || existing.loginLockReason,
        jobLevel: Math.max(existing.jobLevel || 1, incoming.jobLevel || 1),
        diamonds: Math.max(existing.diamonds || 0, incoming.diamonds || 0),
        extraFamilySlots: Math.max(existing.extraFamilySlots || 0, incoming.extraFamilySlots || 0),
      };
    };

    for (const list of fallbackLists) {
      if (!Array.isArray(list)) continue;
      for (const item of list) {
        if (
          !item ||
          !item.id ||
          delSet.has(item.id) ||
          PURGED_BOT_ACCOUNT_NUMBERS.includes(item.accountNumber)
        ) {
          continue;
        }
        const normalized = normalizeAndSanitizeAccount(item);
        map.set(item.id, pickFresherAccount(map.get(item.id), normalized));
      }
    }

    for (const item of primaryList) {
      if (
        !item ||
        !item.id ||
        delSet.has(item.id) ||
        PURGED_BOT_ACCOUNT_NUMBERS.includes(item.accountNumber)
      ) {
        continue;
      }
      const normalized = normalizeAndSanitizeAccount(item);
      map.set(item.id, pickFresherAccount(map.get(item.id), normalized));
    }

    // Pastikan Kartu Admin Utama ('acc-admin') selalu tersedia kecuali sengaja dihapus
    if (!map.has('acc-admin') && !delSet.has('acc-admin')) {
      const defaultAdmin = INITIAL_ACCOUNTS.find((a) => a.id === 'acc-admin');
      if (defaultAdmin) {
        map.set('acc-admin', {
          ...defaultAdmin,
          status: 'active',
          banReason: '',
        });
      }
    }

    // Urutkan agar akun terbaru / non-admin berada di atas sesuai urutan primaryList lalu fallback
    const result: BankAccount[] = [];
    const visited = new Set<string>();
    for (const item of primaryList) {
      if (item && item.id && map.has(item.id) && !visited.has(item.id)) {
        visited.add(item.id);
        result.push(map.get(item.id)!);
      }
    }
    for (const [id, acc] of map.entries()) {
      if (!visited.has(id)) {
        visited.add(id);
        result.push(acc);
      }
    }
    return result;
  };

  const applyMasterCloudData = (
    data: Record<string, any>,
    options?: { forceInitial?: boolean; extraVaultAccounts?: (BankAccount[] | undefined)[] }
  ) => {
    if (!data || typeof data !== 'object') return;
    if (!options?.forceInitial && data.writerSessionId === clientSessionId) {
      return;
    }

    const incomingMs = typeof data.updatedAtMs === 'number' ? data.updatedAtMs : 0;
    // Hanya abaikan snapshot basi dari sesi writer yang SAMA; jika berasal dari perangkat berbeda (HP <-> Laptop), tetap terapkan meskipun jam sistem selisih beberapa detik
    if (
      !options?.forceInitial &&
      hasFirestoreHydratedRef.current &&
      data.writerSessionId === clientSessionId &&
      incomingMs > 0 &&
      incomingMs <= lastFirestoreWriteMsRef.current
    ) {
      return;
    }
    if (incomingMs > lastFirestoreWriteMsRef.current) {
      lastFirestoreWriteMsRef.current = incomingMs;
    }

    isApplyingFirestoreRef.current = true;

    const incomingDelAccountIds = toArraySafe<string>(data.deletedAccountIds);
    const mergedDelAccountIds: string[] = Array.from(
      new Set([
        ...PURGED_BOT_ACCOUNT_IDS,
        ...deletedAccountIdsRef.current,
        ...incomingDelAccountIds,
      ])
    );
    setDeletedAccountIds(mergedDelAccountIds);
    deletedAccountIdsRef.current = mergedDelAccountIds;

    const incomingDelGiftIds = toArraySafe<string>(data.deletedGiftEventIds);
    const mergedDelGiftIds: string[] =
      incomingDelGiftIds.length > 0
        ? Array.from(new Set([...deletedGiftEventIdsRef.current, ...incomingDelGiftIds]))
        : deletedGiftEventIdsRef.current;
    if (incomingDelGiftIds.length > 0) {
      setDeletedGiftEventIds(mergedDelGiftIds);
    }

    let hadPurgedBotAccountsInCloud = false;

    const incomingAccounts = toArraySafe<BankAccount>(data.accounts);
    if (incomingAccounts.length > 0) {
      hadPurgedBotAccountsInCloud = incomingAccounts.some(
        (a) =>
          PURGED_BOT_ACCOUNT_IDS.includes(a.id) ||
          PURGED_BOT_ACCOUNT_NUMBERS.includes(a.accountNumber)
      );

      // Union-merge incoming server accounts dengan latestServerAccountsRef, extraVaultAccounts (dari users/{uid} & users_by_email), dan accountsRef
      const cleanAccounts = unionMergeAccountsList(
        incomingAccounts,
        [
          ...(options?.extraVaultAccounts || []),
          latestServerAccountsRef.current,
          accountsRef.current,
        ],
        mergedDelAccountIds
      );

      latestServerAccountsRef.current = cleanAccounts;
      accountsRef.current = cleanAccounts;
      setAccounts(cleanAccounts);
      // Simpan Fast-Boot Snapshot ke IndexedDB (Zero localStorage) agar reload berikutnya terbuka instan (< 200ms)
      void saveFastBootSnapshot({
        accounts: cleanAccounts,
        deletedAccountIds: mergedDelAccountIds,
        banSupportConfig:
          data.banSupportConfig && typeof data.banSupportConfig === 'object'
            ? data.banSupportConfig
            : undefined,
        cachedAtMs: Date.now(),
      });
    }

    const isNotBotAccountId = (accId?: string) =>
      !accId || !PURGED_BOT_ACCOUNT_IDS.includes(accId);
    const isNotBotAccountNum = (accNum?: string) =>
      !accNum || !PURGED_BOT_ACCOUNT_NUMBERS.includes(accNum);

    if (Array.isArray(data.transactions)) {
      setTransactions(
        (data.transactions as Transaction[])
          .filter(
            (t) =>
              isNotBotAccountId(t.accountId) &&
              isNotBotAccountNum(t.senderAccount) &&
              isNotBotAccountNum(t.recipientAccount)
          )
          .map((t) => ({
            ...t,
            title: sanitizeQrisBrandText(t.title),
            note: t.note ? sanitizeQrisBrandText(t.note) : t.note,
          }))
      );
    }
    if (Array.isArray(data.loans)) {
      setLoans((data.loans as LoanApplication[]).filter((l) => isNotBotAccountId(l.accountId)));
    }
    if (Array.isArray(data.scheduledPayments)) {
      setScheduledPayments(
        (data.scheduledPayments as ScheduledPayment[]).filter((s) => isNotBotAccountId(s.accountId))
      );
    }
    if (Array.isArray(data.favorites)) {
      setFavorites(
        (data.favorites as FavoriteAccount[]).filter((f) => isNotBotAccountNum(f.accountNumber))
      );
    }
    if (Array.isArray(data.notifications)) {
      setNotifications(
        (data.notifications as AppNotification[]).map((n) => ({
          ...n,
          title: sanitizeQrisBrandText(n.title),
          message: sanitizeQrisBrandText(n.message),
        }))
      );
    }
    if (Array.isArray(data.chats)) {
      setChats(
        (data.chats as ChatMessage[]).filter(
          (c) => isNotBotAccountNum(c.senderAccount) && isNotBotAccountNum(c.recipientAccount)
        )
      );
    }
    if (Array.isArray(data.cardUpgrades)) {
      setCardUpgrades(
        (data.cardUpgrades as CardUpgradeApplication[]).filter((u) => isNotBotAccountId(u.accountId))
      );
    }
    if (Array.isArray(data.pinResetRequests)) {
      setPinResetRequests(
        (data.pinResetRequests as PinResetRequest[]).filter((p) => isNotBotAccountId(p.accountId))
      );
    }
    if (data.redeemCodes) {
      const incomingRedeemTs = Number(data.redeemCodesUpdatedAtMs || data.updatedAtMs || 0);
      if (incomingRedeemTs >= redeemCodesUpdatedAtMsRef.current || redeemCodesUpdatedAtMsRef.current === 0) {
        const cleanRedeemList = sanitizeRedeemCodesList(data.redeemCodes);
        redeemCodesRef.current = cleanRedeemList;
        if (incomingRedeemTs > 0) {
          redeemCodesUpdatedAtMsRef.current = incomingRedeemTs;
        }
        setRedeemCodes(cleanRedeemList);
      }
    }
    if (Array.isArray(data.purchasedCodes)) {
      setPurchasedCodes(
        (data.purchasedCodes as PurchasedVoucherCode[]).filter((v) => isNotBotAccountId(v.accountId))
      );
    }
    if (Array.isArray(data.resiList)) setResiList(data.resiList as ResiTrackingRecord[]);
    if (Array.isArray(data.cardlessTokens)) {
      setCardlessTokens(
        (data.cardlessTokens as CardlessToken[]).filter((c) => isNotBotAccountId(c.accountId))
      );
    }
    if (Array.isArray(data.pockets)) {
      setPockets((data.pockets as PocketSaving[]).filter((p) => isNotBotAccountId(p.accountId)));
    }
    if (Array.isArray(data.depositos)) {
      setDepositos((data.depositos as DepositoRecord[]).filter((d) => isNotBotAccountId(d.accountId)));
    }
    if (Array.isArray(data.accountDeletionRequests)) {
      setAccountDeletionRequests(
        (data.accountDeletionRequests as AccountDeletionRequest[]).filter((r) =>
          isNotBotAccountId(r.accountId)
        )
      );
    }

    if (hadPurgedBotAccountsInCloud) {
      window.setTimeout(() => {
        void flushMasterStateToCloud({
          accounts: accountsRef.current,
          deletedAccountIds: mergedDelAccountIds,
        });
      }, 250);
    }

    const incomingGiftTs = Number(data.giftEventsUpdatedAtMs || data.updatedAtMs || 0);
    const hasGiftPayload =
      Boolean(data.giftEventsInitialized) ||
      Array.isArray(data.giftEvents) ||
      Boolean(data.giftEvents && typeof data.giftEvents === 'object');
    if (
      hasGiftPayload &&
      (!hasLoadedGiftRegistryRef.current || incomingGiftTs >= giftEventsUpdatedAtMsRef.current)
    ) {
      const normalizedIncomingGifts = toArraySafe<AdminGiftEventPackage>(data.giftEvents).map(
        normalizeGiftEventPackage
      );
      const filteredGifts = sanitizeGiftEventsRemoveMiningRewards(
        normalizedIncomingGifts.filter((ev) => ev && ev.id && !mergedDelGiftIds.includes(ev.id))
      );
      if (incomingGiftTs > giftEventsUpdatedAtMsRef.current) {
        giftEventsUpdatedAtMsRef.current = incomingGiftTs;
      }
      hasLoadedGiftRegistryRef.current = true;
      setGiftEventsInitialized(true);
      giftEventsInitializedRef.current = true;
      giftEventsRef.current = filteredGifts;
      setGiftEvents(filteredGifts);
      void saveGiftAndSealRegistryIdb({
        giftEvents: filteredGifts,
        deletedGiftEventIds: mergedDelGiftIds,
        giftEventsInitialized: true,
        giftEventsUpdatedAtMs: giftEventsUpdatedAtMsRef.current || Date.now(),
      });
    }
    // 0. Sinkronkan daftar ID terhapus permanen (Tombstone Anti-Zombie) & Revision Counter terlebih dahulu!
    if (data.deletedAdminItemIds && typeof data.deletedAdminItemIds === 'object') {
      mergeDeletedAdminItemIds(data.deletedAdminItemIds as DeletedAdminItemIdsMap);
    }
    const incomingRevMap: Record<string, number> =
      data.adminConfigRevisionMap && typeof data.adminConfigRevisionMap === 'object'
        ? (data.adminConfigRevisionMap as Record<string, number>)
        : {};
    const getIncomingCfgRev = (k: string): number => Number(incomingRevMap[k]) || 0;

    if (Array.isArray(data.dashboardEffectEvents)) {
      const incomingDashEvents = filterListByAdminTombstones(
        'dashboardEffectEvents',
        data.dashboardEffectEvents as AdminDashboardEffectPackage[]
      );
      let hadPhantomUntouchedDefault = false;
      const sanitizedDashEvents = incomingDashEvents.map((pkg) => {
        if (isUntouchedAutoSeededDefaultStage(pkg)) {
          hadPhantomUntouchedDefault = true;
          return {
            ...pkg,
            isActive: false,
            autoBlastOnOpen: false,
          };
        }
        return pkg;
      });
      hasLoadedDashboardEffectsRef.current = true;
      dashboardEffectEventsRef.current = sanitizedDashEvents;
      setDashboardEffectEvents(sanitizedDashEvents);
      if (
        hadPhantomUntouchedDefault &&
        !hasCleanedPhantomDefaultStagesRef.current &&
        adminUnlockedRef.current
      ) {
        hasCleanedPhantomDefaultStagesRef.current = true;
        window.setTimeout(() => {
          void flushMasterStateToCloud({ dashboardEffectEvents: sanitizedDashEvents });
        }, 350);
      }
    }
    if (typeof data.stageForceClearNonce === 'number') {
      const nextVal = data.stageForceClearNonce as number;
      if (nextVal > stageForceClearNonceRef.current) {
        stageForceClearNonceRef.current = nextVal;
      }
      setStageForceClearNonce((prev) => {
        if (nextVal > prev) {
          stopAllCelebrationEffectsAndAudio();
          setActiveDashboardEffectModal(null);
        }
        return Math.max(prev, nextVal);
      });
    }

    if (data.banSupportConfig && typeof data.banSupportConfig === 'object') {
      const incomingBan = data.banSupportConfig as BanSupportConfig;
      const incomingBanTs =
        Number((data as any).banSupportUpdatedAtMs) ||
        (incomingBan.updatedAt ? Date.parse(incomingBan.updatedAt) : 0) ||
        0;
      const incomingBanRev = getIncomingCfgRev('banSupportConfig');
      const localBanRev = adminConfigRevisionMapRef.current.banSupportConfig || 0;
      if (
        incomingBanRev > localBanRev ||
        (incomingBanRev === localBanRev &&
          (incomingBanTs >= banSupportUpdatedAtMsRef.current || banSupportUpdatedAtMsRef.current === 0))
      ) {
        if (incomingBanRev > localBanRev) adminConfigRevisionMapRef.current.banSupportConfig = incomingBanRev;
        if (incomingBanTs > 0) {
          banSupportUpdatedAtMsRef.current = incomingBanTs;
        }
        const resolvedTemplate =
          incomingBan.defaultTemplate ||
          incomingBan.defaultTemplateConfig ||
          DEFAULT_BAN_SCREEN_CONFIG;
        const resolvedPresets =
          Array.isArray(incomingBan.savedPresets) && incomingBan.savedPresets.length > 0
            ? incomingBan.savedPresets
            : Array.isArray(incomingBan.presets) && incomingBan.presets.length > 0
            ? incomingBan.presets
            : undefined;
        const mergedBan: BanSupportConfig = {
          ...banSupportConfig,
          ...incomingBan,
          defaultTemplate: resolvedTemplate,
          defaultTemplateConfig: resolvedTemplate,
          ...(resolvedPresets
            ? { savedPresets: resolvedPresets, presets: resolvedPresets }
            : {}),
        };
        setBanSupportConfig(mergedBan);
        void saveAdminPersistentDataIdb({
          banSupportConfig: mergedBan,
          banSupportUpdatedAtMs: banSupportUpdatedAtMsRef.current || Date.now(),
        });
      }
    }
    if (Array.isArray(data.supportFaqs)) {
      const incomingFaqsTs = Number((data as any).supportFaqsUpdatedAtMs) || 0;
      const incomingFaqsRev = getIncomingCfgRev('supportFaqs');
      const localFaqsRev = adminConfigRevisionMapRef.current.supportFaqs || 0;
      if (
        incomingFaqsRev > localFaqsRev ||
        (incomingFaqsRev === localFaqsRev &&
          (incomingFaqsTs >= supportFaqsUpdatedAtMsRef.current || supportFaqsUpdatedAtMsRef.current === 0))
      ) {
        if (incomingFaqsRev > localFaqsRev) adminConfigRevisionMapRef.current.supportFaqs = incomingFaqsRev;
        if (incomingFaqsTs > 0) {
          supportFaqsUpdatedAtMsRef.current = incomingFaqsTs;
        }
        const upgradedFaqs = filterListByAdminTombstones(
          'supportFaqs',
          ensureUpgraded350SupportFaqs(
            data.supportFaqs as SupportFaqItem[],
            DEFAULT_SUPPORT_FAQS_350
          )
        );
        setSupportFaqs(upgradedFaqs);
        void saveAdminPersistentDataIdb({
          supportFaqs: upgradedFaqs,
          supportFaqsUpdatedAtMs: supportFaqsUpdatedAtMsRef.current || Date.now(),
        });
      }
    }
    if (data.supportContactConfig && typeof data.supportContactConfig === 'object') {
      const incomingContact = data.supportContactConfig as SupportContactConfig;
      const incomingContactTs =
        Number((data as any).supportContactUpdatedAtMs) ||
        (incomingContact.updatedAt ? Date.parse(incomingContact.updatedAt) : 0) ||
        0;
      if (
        incomingContactTs >= supportContactUpdatedAtMsRef.current ||
        supportContactUpdatedAtMsRef.current === 0
      ) {
        if (incomingContactTs > 0) {
          supportContactUpdatedAtMsRef.current = incomingContactTs;
        }
        const mergedContact: SupportContactConfig = {
          ...DEFAULT_SUPPORT_CONTACT_CONFIG,
          ...incomingContact,
          presetCategories: getResolvedPresetCategories(incomingContact.presetCategories),
        };
        setSupportContactConfig(mergedContact);
        void saveAdminPersistentDataIdb({
          supportContactConfig: mergedContact,
          supportContactUpdatedAtMs: supportContactUpdatedAtMsRef.current || Date.now(),
        });
      }
    }
    const incomingSealTs = Number(data.letterSealUpdatedAtMs || 0);
    if (
      data.defaultLetterSealConfig &&
      typeof data.defaultLetterSealConfig === 'object' &&
      (!hasLoadedSealRegistryRef.current || incomingSealTs >= letterSealUpdatedAtMsRef.current)
    ) {
      const normalizedSeal = normalizeLetterSealConfig(
        data.defaultLetterSealConfig,
        defaultLetterSealConfigRef.current
      );
      if (incomingSealTs > letterSealUpdatedAtMsRef.current) {
        letterSealUpdatedAtMsRef.current = incomingSealTs;
      }
      hasLoadedSealRegistryRef.current = true;
      defaultLetterSealConfigRef.current = normalizedSeal;
      setDefaultLetterSealConfig(normalizedSeal);
      void saveGiftAndSealRegistryIdb({
        defaultLetterSealConfig: normalizedSeal,
        letterSealUpdatedAtMs: letterSealUpdatedAtMsRef.current || Date.now(),
      });
    }
    const incomingCfgTsMap: Record<string, number> =
      data.configUpdatedAtMsMap && typeof data.configUpdatedAtMsMap === 'object'
        ? (data.configUpdatedAtMsMap as Record<string, number>)
        : {};
    // PENTING: Jangan fallback ke data.updatedAtMs agar aksi nasabah di HP tidak pernah menimpa timestamp konfigurasi Admin!
    const getIncomingCfgTs = (k: string): number => Number(incomingCfgTsMap[k]) || 0;

    if (data.jobCoinBonusConfig && typeof data.jobCoinBonusConfig === 'object') {
      const mergedJobBonus: JobCoinBonusConfig = {
        ...DEFAULT_JOB_COIN_BONUS_CONFIG,
        ...(data.jobCoinBonusConfig as Partial<JobCoinBonusConfig>),
      };
      if (
        acceptIncomingAdminConfig(
          'jobCoinBonusConfig',
          getIncomingCfgTs('jobCoinBonusConfig'),
          mergedJobBonus,
          jobCoinBonusConfigRef.current,
          getIncomingCfgRev('jobCoinBonusConfig')
        )
      ) {
        jobCoinBonusConfigRef.current = mergedJobBonus;
        setJobCoinBonusConfig(mergedJobBonus);
      }
    }
    if (data.spinWheelConfig && typeof data.spinWheelConfig === 'object') {
      const mergedSpin: SpinWheelAdminConfig = {
        ...INITIAL_SPIN_WHEEL_CONFIG,
        ...(data.spinWheelConfig as Partial<SpinWheelAdminConfig>),
      };
      if (
        acceptIncomingAdminConfig(
          'spinWheelConfig',
          getIncomingCfgTs('spinWheelConfig'),
          mergedSpin,
          spinWheelConfigRef.current,
          getIncomingCfgRev('spinWheelConfig')
        )
      ) {
        spinWheelConfigRef.current = mergedSpin;
        setSpinWheelConfig(mergedSpin);
      }
    }
    if (Array.isArray(data.spinHistory)) setSpinHistory(data.spinHistory as SpinHistoryRecord[]);
    if (data.diamondConfig && typeof data.diamondConfig === 'object') {
      const inc = data.diamondConfig as Partial<DiamondSystemConfig>;
      const needs55PercentPriceCut =
        (inc.priceRevision ?? 1) < 2 &&
        (inc.baseDiamondPriceRupiah === undefined || inc.baseDiamondPriceRupiah === 200);
      const needsCapV3Migration = (inc.priceRevision ?? 1) < DIAMOND_CONFIG_REVISION;
      const nextDiamondCfg: DiamondSystemConfig = {
        ...diamondConfigRef.current,
        ...inc,
        baseDiamondPriceRupiah: needs55PercentPriceCut
          ? DEFAULT_DIAMOND_SYSTEM_CONFIG.baseDiamondPriceRupiah
          : Math.max(1, Math.round(inc.baseDiamondPriceRupiah ?? diamondConfigRef.current.baseDiamondPriceRupiah)),
        maxCustomDiamond: needsCapV3Migration
          ? Math.min(MAX_DIAMOND_PACKAGE_AMOUNT, inc.maxCustomDiamond ?? MAX_DIAMOND_PACKAGE_AMOUNT)
          : Math.max(1, Math.min(MAX_DIAMOND_PACKAGE_AMOUNT, Math.round(inc.maxCustomDiamond ?? MAX_DIAMOND_PACKAGE_AMOUNT))),
        maxPurchaseRupiah: Math.max(
          1,
          Math.min(MAX_DIAMOND_PURCHASE_RUPIAH, Math.round(inc.maxPurchaseRupiah ?? MAX_DIAMOND_PURCHASE_RUPIAH))
        ),
        priceRevision: Math.max(DIAMOND_CONFIG_REVISION, inc.priceRevision ?? DIAMOND_CONFIG_REVISION),
        enabledFeatures: {
          ...diamondConfigRef.current.enabledFeatures,
          ...(inc.enabledFeatures || {}),
        },
      };
      if (
        acceptIncomingAdminConfig(
          'diamondConfig',
          getIncomingCfgTs('diamondConfig'),
          nextDiamondCfg,
          diamondConfigRef.current,
          getIncomingCfgRev('diamondConfig')
        )
      ) {
        diamondConfigRef.current = nextDiamondCfg;
        setDiamondConfig(nextDiamondCfg);
      }
    }
    if (data.uiVisibilityConfig && typeof data.uiVisibilityConfig === 'object') {
      const incVis = data.uiVisibilityConfig as Partial<UiVisibilityConfig>;
      const mergedVis: UiVisibilityConfig = {
        ...DEFAULT_UI_VISIBILITY_CONFIG,
        ...incVis,
        navTabs: {
          ...DEFAULT_UI_VISIBILITY_CONFIG.navTabs,
          ...(incVis.navTabs || {}),
        },
      };
      if (
        acceptIncomingAdminConfig(
          'uiVisibilityConfig',
          getIncomingCfgTs('uiVisibilityConfig'),
          mergedVis,
          uiVisibilityConfigRef.current,
          getIncomingCfgRev('uiVisibilityConfig')
        )
      ) {
        uiVisibilityConfigRef.current = mergedVis;
        setUiVisibilityConfig(mergedVis);
      }
    }
    if (Array.isArray(data.adminWarnings)) {
      const incomingWarnings = filterListByAdminTombstones(
        'adminWarnings',
        data.adminWarnings as AdminSystemWarning[]
      );
      if (
        acceptIncomingAdminConfig(
          'adminWarnings',
          getIncomingCfgTs('adminWarnings'),
          incomingWarnings,
          adminWarningsRef.current,
          getIncomingCfgRev('adminWarnings')
        )
      ) {
        adminWarningsRef.current = incomingWarnings;
        setAdminWarnings(incomingWarnings);
      }
    }
    if (data.bugRewardConfig && typeof data.bugRewardConfig === 'object') {
      const incBugCfg = data.bugRewardConfig as Partial<BugRewardProgramConfig>;
      const mergedBugCfg: BugRewardProgramConfig = {
        ...DEFAULT_BUG_REWARD_CONFIG,
        ...incBugCfg,
      };
      if (
        acceptIncomingAdminConfig(
          'bugRewardConfig',
          getIncomingCfgTs('bugRewardConfig'),
          mergedBugCfg,
          bugRewardConfigRef.current,
          getIncomingCfgRev('bugRewardConfig')
        )
      ) {
        bugRewardConfigRef.current = mergedBugCfg;
        setBugRewardConfig(mergedBugCfg);
      }
    }
    if (Array.isArray(data.qrisOrders)) {
      const incomingOrders = data.qrisOrders as QrisPaymentOrder[];
      qrisOrdersRef.current = incomingOrders;
      setQrisOrders(incomingOrders);
    }
    if (data.familyConfig && typeof data.familyConfig === 'object') {
      const mergedFamCfg: FamilySystemConfig = {
        ...DEFAULT_FAMILY_SYSTEM_CONFIG,
        ...(data.familyConfig as Partial<FamilySystemConfig>),
      };
      if (
        acceptIncomingAdminConfig(
          'familyConfig',
          getIncomingCfgTs('familyConfig'),
          mergedFamCfg,
          familyConfigRef.current,
          getIncomingCfgRev('familyConfig')
        )
      ) {
        familyConfigRef.current = mergedFamCfg;
        setFamilyConfig(mergedFamCfg);
      }
    }
    if (Array.isArray(data.families)) {
      const incomingFamilies = filterListByAdminTombstones(
        'families',
        data.families as FamilyGroup[]
      );
      familiesRef.current = incomingFamilies;
      setFamilies(incomingFamilies);
    }
    if (Array.isArray(data.missions)) {
      const incomingMissions = filterListByAdminTombstones(
        'missions',
        data.missions as AppMissionDefinition[]
      );
      if (
        acceptIncomingAdminConfig(
          'missions',
          getIncomingCfgTs('missions'),
          incomingMissions,
          missionsRef.current,
          getIncomingCfgRev('missions')
        )
      ) {
        missionsRef.current = incomingMissions;
        setMissions(incomingMissions);
      }
    }
    if (data.missionConfig && typeof data.missionConfig === 'object') {
      const mergedMissionCfg: MissionSystemConfig = {
        ...DEFAULT_MISSION_SYSTEM_CONFIG,
        ...(data.missionConfig as Partial<MissionSystemConfig>),
      };
      if (
        acceptIncomingAdminConfig(
          'missionConfig',
          getIncomingCfgTs('missionConfig'),
          mergedMissionCfg,
          missionConfigRef.current,
          getIncomingCfgRev('missionConfig')
        )
      ) {
        missionConfigRef.current = mergedMissionCfg;
        setMissionConfig(mergedMissionCfg);
      }
    }
    if (data.missionProgressByAccount && typeof data.missionProgressByAccount === 'object') {
      const incomingProg = data.missionProgressByAccount as Record<
        string,
        Record<string, MissionAccountProgressRecord>
      >;
      missionProgressByAccountRef.current = incomingProg;
      setMissionProgressByAccount(incomingProg);
    }
    if (Array.isArray(data.missionClaimLogs)) {
      const incomingLogs = data.missionClaimLogs as MissionClaimAuditLog[];
      missionClaimLogsRef.current = incomingLogs;
      setMissionClaimLogs(incomingLogs);
    }
    if (data.leaderboardConfig && typeof data.leaderboardConfig === 'object') {
      const incLb = data.leaderboardConfig as Partial<LeaderboardSystemConfig>;
      const mergedLb: LeaderboardSystemConfig = {
        ...DEFAULT_LEADERBOARD_SYSTEM_CONFIG,
        ...incLb,
        categories:
          Array.isArray(incLb.categories) && incLb.categories.length > 0
            ? incLb.categories
            : DEFAULT_LEADERBOARD_SYSTEM_CONFIG.categories,
      };
      if (
        acceptIncomingAdminConfig(
          'leaderboardConfig',
          getIncomingCfgTs('leaderboardConfig'),
          mergedLb,
          leaderboardConfigRef.current,
          getIncomingCfgRev('leaderboardConfig')
        )
      ) {
        leaderboardConfigRef.current = mergedLb;
        setLeaderboardConfig(mergedLb);
      }
    }
    if (data.adminTierNotificationConfig && typeof data.adminTierNotificationConfig === 'object') {
      const incAdmNotif = data.adminTierNotificationConfig as Partial<AdminTierNotificationConfig>;
      const mergedAdmNotif: AdminTierNotificationConfig = {
        ...DEFAULT_ADMIN_TIER_NOTIFICATION_CONFIG,
        ...incAdmNotif,
        triggers: {
          ...DEFAULT_ADMIN_TIER_NOTIFICATION_CONFIG.triggers,
          ...(incAdmNotif.triggers || {}),
        },
      };
      if (
        acceptIncomingAdminConfig(
          'adminTierNotificationConfig',
          getIncomingCfgTs('adminTierNotificationConfig'),
          mergedAdmNotif,
          adminTierNotificationConfigRef.current,
          getIncomingCfgRev('adminTierNotificationConfig')
        )
      ) {
        adminTierNotificationConfigRef.current = mergedAdmNotif;
        setAdminTierNotificationConfig(mergedAdmNotif);
      }
    }
    if (data.liveActivityDetectorConfig && typeof data.liveActivityDetectorConfig === 'object') {
      const incDet = data.liveActivityDetectorConfig as Partial<LiveActivityDetectorConfig>;
      const mergedDet: LiveActivityDetectorConfig = {
        ...DEFAULT_LIVE_ACTIVITY_DETECTOR_CONFIG,
        ...incDet,
        rulesEnabled: {
          ...DEFAULT_LIVE_ACTIVITY_DETECTOR_CONFIG.rulesEnabled,
          ...(incDet.rulesEnabled || {}),
        },
        ruleThresholds: {
          ...(DEFAULT_LIVE_ACTIVITY_DETECTOR_CONFIG.ruleThresholds || {}),
          ...(incDet.ruleThresholds || {}),
        },
        ruleWindowMinutes: {
          ...(DEFAULT_LIVE_ACTIVITY_DETECTOR_CONFIG.ruleWindowMinutes || {}),
          ...(incDet.ruleWindowMinutes || {}),
        },
      };
      if (
        acceptIncomingAdminConfig(
          'liveActivityDetectorConfig',
          getIncomingCfgTs('liveActivityDetectorConfig'),
          mergedDet,
          liveActivityDetectorConfigRef.current,
          getIncomingCfgRev('liveActivityDetectorConfig')
        )
      ) {
        liveActivityDetectorConfigRef.current = mergedDet;
        setLiveActivityDetectorConfig(mergedDet);
      }
    }
    if (data.sultanEmpireConfig && typeof data.sultanEmpireConfig === 'object') {
      const mergedSultan: SultanEmpireAdminConfig = {
        ...INITIAL_SULTAN_EMPIRE_CONFIG,
        ...(data.sultanEmpireConfig as Partial<SultanEmpireAdminConfig>),
      };
      if (
        acceptIncomingAdminConfig(
          'sultanEmpireConfig',
          getIncomingCfgTs('sultanEmpireConfig'),
          mergedSultan,
          sultanEmpireConfigRef.current,
          getIncomingCfgRev('sultanEmpireConfig')
        )
      ) {
        sultanEmpireConfigRef.current = mergedSultan;
        setSultanEmpireConfig(mergedSultan);
      }
    }
    if (Array.isArray(data.featureConfigs)) {
      const incFeat = data.featureConfigs as FeatureSecurityConfig[];
      if (
        acceptIncomingAdminConfig(
          'featureConfigs',
          getIncomingCfgTs('featureConfigs'),
          incFeat,
          rawFeatureConfigsRef.current,
          getIncomingCfgRev('featureConfigs')
        )
      ) {
        rawFeatureConfigsRef.current = incFeat;
        setFeatureConfigs(incFeat);
      }
    }
    if (Array.isArray(data.deletedFeatureIds)) {
      const incDelFeat = data.deletedFeatureIds as string[];
      if (
        acceptIncomingAdminConfig(
          'deletedFeatureIds',
          getIncomingCfgTs('deletedFeatureIds'),
          incDelFeat,
          deletedFeatureIdsRef.current,
          getIncomingCfgRev('deletedFeatureIds')
        )
      ) {
        deletedFeatureIdsRef.current = incDelFeat;
        setDeletedFeatureIds(incDelFeat);
      }
    }
    if (data.userSettings && typeof data.userSettings === 'object') {
      const incomingSettings = data.userSettings as UserAppSettings;
      setUserSettings((prev) => ({
        ...prev,
        ...incomingSettings,
        notificationCategoryPermissions: sanitizeNotificationCategoryPermissions(
          incomingSettings.notificationCategoryPermissions || prev.notificationCategoryPermissions
        ),
      }));
    }
    if (data.goldMarketConfig && typeof data.goldMarketConfig === 'object') {
      const mergedGold: GoldAndTransferMarketConfig = {
        ...createInitialGoldMarketConfig(),
        ...(data.goldMarketConfig as Partial<GoldAndTransferMarketConfig>),
      };
      if (
        acceptIncomingAdminConfig(
          'goldMarketConfig',
          getIncomingCfgTs('goldMarketConfig'),
          mergedGold,
          goldMarketConfigRef.current,
          getIncomingCfgRev('goldMarketConfig')
        )
      ) {
        goldMarketConfigRef.current = mergedGold;
        setGoldMarketConfig(mergedGold);
      }
    }
    if (Array.isArray(data.budgetCategories) && data.budgetCategories.length > 0) {
      const incomingCats = data.budgetCategories as BudgetCategory[];
      const missingDefaults = DEFAULT_BUDGET_CATEGORIES.filter(
        (def) => !incomingCats.some((c) => c.id === def.id)
      );
      setBudgetCategories([...incomingCats, ...missingDefaults]);
    }
    if (Array.isArray(data.manualExpenses)) setManualExpenses(data.manualExpenses as ManualExpenseRecord[]);
    if (data.budgetTxCategoryMap && typeof data.budgetTxCategoryMap === 'object') {
      setBudgetTxCategoryMap(data.budgetTxCategoryMap as Record<string, string>);
    }
    if (Array.isArray(data.budgetAlertHistory)) setBudgetAlertHistory(data.budgetAlertHistory as string[]);
    if (Array.isArray(data.appUpdates) && data.appUpdates.length > 0) {
      const filteredIncomingUpdates = filterListByAdminTombstones(
        'appUpdates',
        (data.appUpdates as AppUpdateRecord[]).map(sanitizeAppUpdateRecord)
      );
      const filteredCatalog = filterListByAdminTombstones('appUpdates', INITIAL_APP_UPDATES);
      const mergedRes = mergeAutoDetectedAppUpdates(filteredIncomingUpdates, filteredCatalog);
      const cleanedMerged = filterListByAdminTombstones(
        'appUpdates',
        mergedRes.mergedUpdates.map(sanitizeAppUpdateRecord)
      );
      setAppUpdates(cleanedMerged);
      if (mergedRes.didChange && !hasSyncedAutoBuildRef.current && adminUnlockedRef.current) {
        hasSyncedAutoBuildRef.current = true;
        window.setTimeout(() => {
          flushMasterStateToCloud({ appUpdates: cleanedMerged });
          syncUpdatesToServer(cleanedMerged);
        }, 400);
      }
    } else if (!hasSyncedAutoBuildRef.current) {
      const filteredCatalog = filterListByAdminTombstones('appUpdates', INITIAL_APP_UPDATES);
      const mergedRes = mergeAutoDetectedAppUpdates([], filteredCatalog);
      const cleanedMerged = mergedRes.mergedUpdates.map(sanitizeAppUpdateRecord);
      setAppUpdates(cleanedMerged);
      hasSyncedAutoBuildRef.current = true;
    }
    if (Array.isArray(data.devRoles) && data.devRoles.length > 0) {
      const incRoles = filterListByAdminTombstones('devRoles', data.devRoles as DevRoleConfig[]);
      if (
        incRoles.length > 0 &&
        acceptIncomingAdminConfig(
          'devRoles',
          getIncomingCfgTs('devRoles'),
          incRoles,
          devRolesRef.current,
          getIncomingCfgRev('devRoles')
        )
      ) {
        devRolesRef.current = incRoles;
        setDevRoles(incRoles);
      }
    }
    if (Array.isArray(data.adminHelpRequests)) {
      setAdminHelpRequests(
        filterListByAdminTombstones(
          'adminHelpRequests',
          data.adminHelpRequests as AdminHelpRequestRecord[]
        )
      );
    }
    if (Array.isArray(data.websitePopups)) {
      setWebsitePopups(
        filterListByAdminTombstones(
          'websitePopups',
          data.websitePopups as WebsiteSystemPopupNotification[]
        )
      );
    }
    if (Array.isArray(data.globalChats)) {
      setGlobalChats(
        filterListByAdminTombstones('globalChats', data.globalChats as GlobalChatMessage[])
      );
    }
    if (Array.isArray(data.bugReports)) {
      setBugReports(
        filterListByAdminTombstones('bugReports', data.bugReports as BugReportRecord[])
      );
    }

    window.setTimeout(() => {
      isApplyingFirestoreRef.current = false;
    }, 100);
  };

  const flushMasterStateToCloud = (overrides?: {
    accounts?: BankAccount[];
    deletedAccountIds?: string[];
    accountDeletionRequests?: AccountDeletionRequest[];
    transactions?: Transaction[];
    giftEvents?: AdminGiftEventPackage[];
    deletedGiftEventIds?: string[];
    giftEventsInitialized?: boolean;
    dashboardEffectEvents?: AdminDashboardEffectPackage[];
    stageForceClearNonce?: number;
    pockets?: PocketSaving[];
    depositos?: DepositoRecord[];
    banSupportConfig?: BanSupportConfig;
    supportFaqs?: SupportFaqItem[];
    supportContactConfig?: SupportContactConfig;
    loans?: LoanApplication[];
    scheduledPayments?: ScheduledPayment[];
    favorites?: FavoriteAccount[];
    notifications?: AppNotification[];
    chats?: ChatMessage[];
    cardUpgrades?: CardUpgradeApplication[];
    pinResetRequests?: PinResetRequest[];
    redeemCodes?: RedeemCode[];
    purchasedCodes?: PurchasedVoucherCode[];
    resiList?: ResiTrackingRecord[];
    cardlessTokens?: CardlessToken[];
    spinWheelConfig?: SpinWheelAdminConfig;
    spinHistory?: SpinHistoryRecord[];
    diamondConfig?: DiamondSystemConfig;
    uiVisibilityConfig?: UiVisibilityConfig;
    adminWarnings?: AdminSystemWarning[];
    bugRewardConfig?: BugRewardProgramConfig;
    qrisOrders?: QrisPaymentOrder[];
    familyConfig?: FamilySystemConfig;
    families?: FamilyGroup[];
    missions?: AppMissionDefinition[];
    missionConfig?: MissionSystemConfig;
    missionProgressByAccount?: Record<string, Record<string, MissionAccountProgressRecord>>;
    missionClaimLogs?: MissionClaimAuditLog[];
    leaderboardConfig?: LeaderboardSystemConfig;
    adminTierNotificationConfig?: AdminTierNotificationConfig;
    liveActivityDetectorConfig?: LiveActivityDetectorConfig;
    sultanEmpireConfig?: SultanEmpireAdminConfig;
    featureConfigs?: FeatureSecurityConfig[];
    deletedFeatureIds?: string[];
    userSettings?: UserAppSettings;
    goldMarketConfig?: GoldAndTransferMarketConfig;
    budgetCategories?: BudgetCategory[];
    manualExpenses?: ManualExpenseRecord[];
    budgetTxCategoryMap?: Record<string, string>;
    budgetAlertHistory?: string[];
    appUpdates?: AppUpdateRecord[];
    devRoles?: DevRoleConfig[];
    defaultLetterSealConfig?: LetterSignatureStampConfig;
    jobCoinBonusConfig?: JobCoinBonusConfig;
    adminHelpRequests?: AdminHelpRequestRecord[];
    websitePopups?: WebsiteSystemPopupNotification[];
    globalChats?: GlobalChatMessage[];
    bugReports?: BugReportRecord[];
    deletedAdminItemIds?: DeletedAdminItemIdsMap;
    adminConfigRevisionMap?: Record<string, number>;
  }) => {
    const nowMs = Date.now();
    lastFirestoreWriteMsRef.current = nowMs;
    lastSyncEpochRef.current = nowMs;
    setCloudSyncStatus('syncing');

    // Hak Tulis Konfigurasi Global Admin: Hanya Admin (atau pemegang Kartu Tier ADMIN / OA / DevRole) yang boleh menulis ulang konfigurasi global di Cloud!
    const activeWriterAcc = accountsRef.current.find((a) => a.id === currentAccountIdRef.current);
    const hasAdminWritePrivilege = Boolean(
      adminUnlockedRef.current ||
        activeWriterAcc?.cardTier === 'admin' ||
        activeWriterAcc?.isOfficialAdminAccount ||
        activeWriterAcc?.id === 'acc-admin' ||
        activeWriterAcc?.devRoleId
    );

    const mergedDeletedAccountIds = Array.from(
      new Set([
        ...PURGED_BOT_ACCOUNT_IDS,
        ...deletedAccountIdsRef.current,
        ...(overrides?.deletedAccountIds ?? deletedAccountIds),
      ])
    );

    // 100% Tanpa localStorage & Proteksi Anti-Timpa:
    const cloudSyncedAccounts = unionMergeAccountsList(
      overrides?.accounts ?? accountsRef.current,
      [latestServerAccountsRef.current, accounts],
      mergedDeletedAccountIds
    );
    latestServerAccountsRef.current = cloudSyncedAccounts;
    if (cloudSyncedAccounts.length > 0) {
      void saveFastBootSnapshot({
        accounts: cloudSyncedAccounts,
        deletedAccountIds: mergedDeletedAccountIds,
        cachedAtMs: Date.now(),
      });
    }

    const isNotBotAccountId = (accId?: string) =>
      !accId || !PURGED_BOT_ACCOUNT_IDS.includes(accId);
    const isNotBotAccountNum = (accNum?: string) =>
      !accNum || !PURGED_BOT_ACCOUNT_NUMBERS.includes(accNum);

    // Hanya tulis slice konfigurasi Admin ke Cloud bila benar-benar diubah secara eksplisit oleh Admin!
    // Ini mencegah nasabah di HP menimpa atau menghidupkan kembali peringatan/konfigurasi yang baru dihapus Admin di Laptop!
    const hasAnyAdminOverride = Boolean(
      overrides &&
        (overrides.adminWarnings !== undefined ||
          overrides.banSupportConfig !== undefined ||
          overrides.supportFaqs !== undefined ||
          overrides.supportContactConfig !== undefined ||
          overrides.redeemCodes !== undefined ||
          overrides.spinWheelConfig !== undefined ||
          overrides.diamondConfig !== undefined ||
          overrides.uiVisibilityConfig !== undefined ||
          overrides.bugRewardConfig !== undefined ||
          overrides.familyConfig !== undefined ||
          overrides.missions !== undefined ||
          overrides.missionConfig !== undefined ||
          overrides.leaderboardConfig !== undefined ||
          overrides.adminTierNotificationConfig !== undefined ||
          overrides.liveActivityDetectorConfig !== undefined ||
          overrides.sultanEmpireConfig !== undefined ||
          overrides.featureConfigs !== undefined ||
          overrides.deletedFeatureIds !== undefined ||
          overrides.goldMarketConfig !== undefined ||
          overrides.appUpdates !== undefined ||
          overrides.devRoles !== undefined ||
          overrides.defaultLetterSealConfig !== undefined ||
          overrides.jobCoinBonusConfig !== undefined ||
          overrides.dashboardEffectEvents !== undefined ||
          overrides.giftEvents !== undefined ||
          overrides.deletedGiftEventIds !== undefined ||
          overrides.websitePopups !== undefined ||
          overrides.deletedAdminItemIds !== undefined ||
          overrides.adminConfigRevisionMap !== undefined)
    );

    const payload = sanitizeForFirestore({
      accounts: cloudSyncedAccounts,
      deletedAccountIds: mergedDeletedAccountIds,
      ...(overrides?.accountDeletionRequests !== undefined
        ? {
            accountDeletionRequests: overrides.accountDeletionRequests.filter((r) =>
              isNotBotAccountId(r.accountId)
            ),
          }
        : {}),
      ...(overrides?.transactions !== undefined
        ? {
            transactions: overrides.transactions
              .filter(
                (t) =>
                  isNotBotAccountId(t.accountId) &&
                  isNotBotAccountNum(t.senderAccount) &&
                  isNotBotAccountNum(t.recipientAccount)
              )
              .slice(0, 220),
          }
        : {}),
      ...(overrides?.pockets !== undefined
        ? { pockets: overrides.pockets.filter((p) => isNotBotAccountId(p.accountId)) }
        : {}),
      ...(overrides?.depositos !== undefined
        ? { depositos: overrides.depositos.filter((d) => isNotBotAccountId(d.accountId)) }
        : {}),
      ...(overrides?.loans !== undefined
        ? { loans: overrides.loans.filter((l) => isNotBotAccountId(l.accountId)) }
        : {}),
      ...(overrides?.scheduledPayments !== undefined
        ? {
            scheduledPayments: overrides.scheduledPayments.filter((s) =>
              isNotBotAccountId(s.accountId)
            ),
          }
        : {}),
      ...(overrides?.favorites !== undefined
        ? { favorites: overrides.favorites.filter((f) => isNotBotAccountNum(f.accountNumber)) }
        : {}),
      ...(overrides?.notifications !== undefined
        ? { notifications: overrides.notifications.slice(0, 120) }
        : {}),
      ...(overrides?.chats !== undefined
        ? {
            chats: overrides.chats
              .filter(
                (c) =>
                  isNotBotAccountNum(c.senderAccount) && isNotBotAccountNum(c.recipientAccount)
              )
              .slice(0, 120),
          }
        : {}),
      ...(overrides?.cardUpgrades !== undefined
        ? { cardUpgrades: overrides.cardUpgrades.filter((u) => isNotBotAccountId(u.accountId)) }
        : {}),
      ...(overrides?.pinResetRequests !== undefined
        ? {
            pinResetRequests: overrides.pinResetRequests.filter((p) =>
              isNotBotAccountId(p.accountId)
            ),
          }
        : {}),
      ...(overrides?.purchasedCodes !== undefined
        ? {
            purchasedCodes: overrides.purchasedCodes.filter((v) =>
              isNotBotAccountId(v.accountId)
            ),
          }
        : {}),
      ...(overrides?.resiList !== undefined ? { resiList: overrides.resiList } : {}),
      ...(overrides?.cardlessTokens !== undefined
        ? {
            cardlessTokens: overrides.cardlessTokens.filter((c) =>
              isNotBotAccountId(c.accountId)
            ),
          }
        : {}),
      ...(overrides?.spinHistory !== undefined
        ? { spinHistory: overrides.spinHistory.slice(0, 80) }
        : {}),
      ...(overrides?.qrisOrders !== undefined
        ? { qrisOrders: overrides.qrisOrders.slice(0, 120) }
        : {}),
      ...(overrides?.families !== undefined ? { families: overrides.families.slice(0, 150) } : {}),
      ...(overrides?.missionProgressByAccount !== undefined
        ? { missionProgressByAccount: overrides.missionProgressByAccount }
        : {}),
      ...(overrides?.missionClaimLogs !== undefined
        ? { missionClaimLogs: overrides.missionClaimLogs.slice(0, 200) }
        : {}),
      ...(overrides?.userSettings !== undefined ? { userSettings: overrides.userSettings } : {}),
      ...(overrides?.budgetCategories !== undefined
        ? { budgetCategories: overrides.budgetCategories }
        : {}),
      ...(overrides?.manualExpenses !== undefined
        ? { manualExpenses: overrides.manualExpenses }
        : {}),
      ...(overrides?.budgetTxCategoryMap !== undefined
        ? { budgetTxCategoryMap: overrides.budgetTxCategoryMap }
        : {}),
      ...(overrides?.budgetAlertHistory !== undefined
        ? { budgetAlertHistory: overrides.budgetAlertHistory }
        : {}),
      ...(overrides?.adminHelpRequests !== undefined
        ? { adminHelpRequests: overrides.adminHelpRequests }
        : {}),
      ...(overrides?.globalChats !== undefined
        ? { globalChats: overrides.globalChats.slice(0, 100) }
        : {}),
      ...(overrides?.bugReports !== undefined
        ? { bugReports: overrides.bugReports.slice(0, 60) }
        : {}),

      // === KONFIGURASI GLOBAL KHUSUS ADMIN (DILINDUNGI HAK TULIS ADMIN + TOMBSTONE + REVISION) ===
      ...(hasAdminWritePrivilege &&
      (overrides?.giftEvents !== undefined || overrides?.deletedGiftEventIds !== undefined)
        ? {
            giftEvents: overrides?.giftEvents ?? giftEventsRef.current,
            deletedGiftEventIds: overrides?.deletedGiftEventIds ?? deletedGiftEventIdsRef.current,
            giftEventsInitialized: overrides?.giftEventsInitialized ?? true,
            giftEventsUpdatedAtMs: giftEventsUpdatedAtMsRef.current || nowMs,
          }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.dashboardEffectEvents !== undefined
        ? { dashboardEffectEvents: overrides.dashboardEffectEvents }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.stageForceClearNonce !== undefined
        ? { stageForceClearNonce: overrides.stageForceClearNonce }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.banSupportConfig !== undefined
        ? {
            banSupportConfig: overrides.banSupportConfig,
            banSupportUpdatedAtMs: banSupportUpdatedAtMsRef.current || nowMs,
          }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.supportFaqs !== undefined
        ? {
            supportFaqs: overrides.supportFaqs,
            supportFaqsUpdatedAtMs: supportFaqsUpdatedAtMsRef.current || nowMs,
          }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.supportContactConfig !== undefined
        ? {
            supportContactConfig: overrides.supportContactConfig,
            supportContactUpdatedAtMs: supportContactUpdatedAtMsRef.current || nowMs,
          }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.redeemCodes !== undefined
        ? {
            redeemCodes: overrides.redeemCodes,
            redeemCodesUpdatedAtMs: redeemCodesUpdatedAtMsRef.current || nowMs,
          }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.spinWheelConfig !== undefined
        ? { spinWheelConfig: overrides.spinWheelConfig }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.diamondConfig !== undefined
        ? { diamondConfig: overrides.diamondConfig }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.uiVisibilityConfig !== undefined
        ? { uiVisibilityConfig: overrides.uiVisibilityConfig }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.adminWarnings !== undefined
        ? { adminWarnings: overrides.adminWarnings }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.bugRewardConfig !== undefined
        ? { bugRewardConfig: overrides.bugRewardConfig }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.familyConfig !== undefined
        ? { familyConfig: overrides.familyConfig }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.missions !== undefined
        ? { missions: overrides.missions.slice(0, 120) }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.missionConfig !== undefined
        ? { missionConfig: overrides.missionConfig }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.leaderboardConfig !== undefined
        ? { leaderboardConfig: overrides.leaderboardConfig }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.adminTierNotificationConfig !== undefined
        ? { adminTierNotificationConfig: overrides.adminTierNotificationConfig }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.liveActivityDetectorConfig !== undefined
        ? { liveActivityDetectorConfig: overrides.liveActivityDetectorConfig }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.sultanEmpireConfig !== undefined
        ? { sultanEmpireConfig: overrides.sultanEmpireConfig }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.featureConfigs !== undefined
        ? { featureConfigs: overrides.featureConfigs }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.deletedFeatureIds !== undefined
        ? { deletedFeatureIds: overrides.deletedFeatureIds }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.goldMarketConfig !== undefined
        ? { goldMarketConfig: overrides.goldMarketConfig }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.appUpdates !== undefined
        ? { appUpdates: overrides.appUpdates }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.devRoles !== undefined
        ? { devRoles: overrides.devRoles }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.defaultLetterSealConfig !== undefined
        ? {
            defaultLetterSealConfig: overrides.defaultLetterSealConfig,
            letterSealUpdatedAtMs: letterSealUpdatedAtMsRef.current || nowMs,
          }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.jobCoinBonusConfig !== undefined
        ? { jobCoinBonusConfig: overrides.jobCoinBonusConfig }
        : {}),
      ...(hasAdminWritePrivilege && overrides?.websitePopups !== undefined
        ? { websitePopups: overrides.websitePopups.slice(0, 40) }
        : {}),
      ...(hasAdminWritePrivilege && hasAnyAdminOverride
        ? {
            configUpdatedAtMsMap: { ...configUpdatedAtMsMapRef.current },
            adminConfigRevisionMap: {
              ...adminConfigRevisionMapRef.current,
              ...(overrides?.adminConfigRevisionMap || {}),
            },
            deletedAdminItemIds: {
              ...deletedAdminItemIdsRef.current,
              ...(overrides?.deletedAdminItemIds || {}),
            },
          }
        : overrides?.deletedAdminItemIds
        ? { deletedAdminItemIds: overrides.deletedAdminItemIds }
        : {}),
      writerSessionId: clientSessionId,
      updatedAtMs: nowMs,
      updatedAt: new Date(nowMs).toISOString(),
    }) as Record<string, unknown>;

    // Dual-Vault Sync: jika ada akun yang di-override atau sedang aktif pada email pengguna, simpan juga salinan savedAccounts ke users/{uid} & users_by_email/{emailKey}
    const activeEmailForVault = normalizeEmailKey(
      googleUser?.email || activeCloudEmailRef.current || firebaseUser?.email || ''
    );
    if (activeEmailForVault && activeEmailForVault.includes('@')) {
      const userOwnedAccounts = cloudSyncedAccounts.filter((a) => {
        const gEm = a.googleEmail ? normalizeEmailKey(a.googleEmail) : '';
        const aEm = a.email ? normalizeEmailKey(a.email) : '';
        return (
          (firebaseUser?.uid && a.firebaseUid === firebaseUser.uid) ||
          gEm === activeEmailForVault ||
          aEm === activeEmailForVault
        );
      });
      if (userOwnedAccounts.length > 0) {
        const eKey = emailToFirestoreDocId(activeEmailForVault);
        const vaultPayload = sanitizeForFirestore({
          savedAccounts: userOwnedAccounts,
          hasCompletedOnboarding: true,
          updatedAt: new Date(nowMs).toISOString(),
          updatedAtMs: nowMs,
        }) as Record<string, unknown>;
        if (firebaseUser?.uid) {
          void writeCloudDoc('users', firebaseUser.uid, vaultPayload, { merge: true }).catch(
            () => {}
          );
        }
        void writeCloudDoc(
          'users_by_email',
          eKey,
          { ...vaultPayload, email: activeEmailForVault, emailKey: eKey },
          { merge: true }
        ).catch(() => {});
      }
    }

    updateSyncTelemetry({
      hasPendingWrites: true,
      pendingWritesCount: Math.max(1, syncTelemetry.pendingWritesCount + 1),
      syncedDocCount:
        cloudSyncedAccounts.length +
        (overrides?.transactions ?? transactions).length +
        (overrides?.pockets ?? pockets).length +
        (overrides?.depositos ?? depositos).length,
    });

    // Mirror juga ke UID Private Vault (`users/{uid}/vault_state/primary`) secara atomik dengan syncVersion +1
    const activeAuthUid = auth.currentUser?.uid || firebaseUser?.uid;
    if (activeAuthUid) {
      const uidVaultPayload = sanitizeForFirestore({
        accounts: cloudSyncedAccounts.filter((a) => {
          const gEm = a.googleEmail ? normalizeEmailKey(a.googleEmail) : '';
          const aEm = a.email ? normalizeEmailKey(a.email) : '';
          return (
            a.firebaseUid === activeAuthUid ||
            a.id === currentAccountId ||
            (activeEmailForVault && (gEm === activeEmailForVault || aEm === activeEmailForVault))
          );
        }),
        updatedAtMs: nowMs,
      }) as Record<string, unknown>;
      void writeVaultStateAtomic(
        activeAuthUid,
        uidVaultPayload,
        cloudSyncedAccounts.length + (overrides?.transactions ?? transactions).length
      ).catch(() => {});
    }

    return writeCloudDoc('bank_state_v1', 'master_state', payload, { merge: true })
      .then((ok) => {
        if (ok) {
          const syncedIso = new Date().toISOString();
          setCloudSyncStatus('synced');
          setLastCloudSyncAt(syncedIso);
          updateSyncTelemetry({
            fromCache: false,
            hasPendingWrites: false,
            pendingWritesCount: 0,
            lastSyncedAt: syncedIso,
            lastError: null,
          });
        } else {
          setCloudSyncStatus('offline');
          updateSyncTelemetry({
            hasPendingWrites: false,
            pendingWritesCount: 0,
            lastError:
              typeof navigator !== 'undefined' && navigator.onLine
                ? 'Sinkronisasi ke server azkaakc tertunda. Klik Retry untuk mencoba ulang.'
                : null,
          });
        }
        return ok;
      })
      .catch((err) => {
        setCloudSyncStatus('offline');
        updateSyncTelemetry({
          hasPendingWrites: false,
          pendingWritesCount: 0,
          lastError: err instanceof Error ? err.message : 'Gangguan koneksi sinkronisasi cloud.',
        });
        handleFirestoreError(err, OperationType.WRITE, 'bank_state_v1/master_state', {
          suppressThrow: true,
        });
        return false;
      });
  };

  const persistAdminConfigChange = (
    key: string,
    value: unknown,
    options?: {
      cloudOverride?: Record<string, any>;
      label?: string;
      skipServerGeneric?: boolean;
      deletedIds?: string[];
      collectionKey?: AdminDeletableCollectionKey;
    }
  ) => {
    const nowMs = Date.now();
    const nowIso = new Date(nowMs).toISOString();
    const wibLabel = formatWibClockLabel(nowMs);
    const nextRev = (Number(adminConfigRevisionMapRef.current[key]) || 0) + 1;
    adminConfigRevisionMapRef.current = {
      ...adminConfigRevisionMapRef.current,
      [key]: nextRev,
    };
    configUpdatedAtMsMapRef.current = {
      ...configUpdatedAtMsMapRef.current,
      [key]: nowMs,
    };
    let nextTombstones = deletedAdminItemIdsRef.current;
    if (options?.collectionKey && Array.isArray(options.deletedIds) && options.deletedIds.length > 0) {
      nextTombstones = recordDeletedAdminItemIds(options.collectionKey, options.deletedIds);
    }
    setLastAdminSavedAtIso(nowIso);
    setAdminConfigSyncTelemetry({
      status: 'saved',
      lastSavedAtIso: nowIso,
      lastSavedWibLabel: wibLabel,
      lastConfigLabel: options?.label || key,
    });
    void saveAdminPersistentDataIdb({
      forceAuthoritativeOverwrite: true,
      lastAdminSavedAtIso: nowIso,
      adminConfigRevisionMap: { [key]: nextRev },
      deletedAdminItemIds: nextTombstones as Record<string, string[]>,
      configs: {
        [key]: {
          value,
          updatedAtMs: nowMs,
        },
      },
    });
    if (!options?.skipServerGeneric) {
      try {
        if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
          wsRef.current.send(
            JSON.stringify({
              type: 'admin_config:sync',
              payload: {
                key,
                value,
                updatedAtMs: nowMs,
                revision: nextRev,
                deletedIds: options?.deletedIds,
                collectionKey: options?.collectionKey,
                deletedAdminItemIds: nextTombstones,
              },
            })
          );
        }
        void fetch('/api/admin-config', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            key,
            value,
            updatedAtMs: nowMs,
            revision: nextRev,
            deletedIds: options?.deletedIds,
            collectionKey: options?.collectionKey,
            deletedAdminItemIds: nextTombstones,
          }),
        });
      } catch {
        // ignore offline
      }
    }
    flushMasterStateToCloud({
      ...(options?.cloudOverride || {}),
      deletedAdminItemIds: nextTombstones,
      adminConfigRevisionMap: { ...adminConfigRevisionMapRef.current },
    });
  };

  const applyCloudUserDocSnapshot = (
    uData: CloudUserRecord,
    contextUid?: string,
    contextEmail?: string
  ) => {
    const nowMs = Date.now();
    const cleanTargetEmail = normalizeEmailKey(contextEmail || uData.email || '');
    const uDataUpdatedMs =
      Number(uData.updatedAtMs) ||
      (uData.updatedAt ? Date.parse(String(uData.updatedAt)) || 0 : 0);

    // Cek apakah status ban di Cloud sebenarnya sudah kedaluwarsa (Trial habis saat HP ditutup)
    // atau sudah dikalahkan oleh Unban yang lebih baru di rekening lokal/server
    const cloudBanExpiresMs = uData.banExpiresAt ? Date.parse(String(uData.banExpiresAt)) : NaN;
    const isCloudTrialAlreadyExpired =
      uData.status === 'banned' && Number.isFinite(cloudBanExpiresMs) && nowMs >= cloudBanExpiresMs;

    const matchingLocalUnbannedAcc = accountsRef.current.find((acc) => {
      const accGoogle = acc.googleEmail ? normalizeEmailKey(acc.googleEmail) : '';
      const accEmail = acc.email ? normalizeEmailKey(acc.email) : '';
      const isLinked =
        (contextUid && acc.firebaseUid === contextUid) ||
        (uData.lastAccountId && acc.id === uData.lastAccountId) ||
        (cleanTargetEmail && (accGoogle === cleanTargetEmail || accEmail === cleanTargetEmail));
      return (
        Boolean(isLinked) &&
        acc.status === 'active' &&
        acc.cardStatus === 'active' &&
        !acc.banInfo?.isBanned &&
        Number(acc.unbannedAtMs || 0) > 0 &&
        Number(acc.unbannedAtMs || 0) >= uDataUpdatedMs
      );
    });

    const forceCleanStaleCloudBan = Boolean(
      uData.status === 'banned' && (isCloudTrialAlreadyExpired || matchingLocalUnbannedAcc)
    );
    const effectiveCloudStatus: 'active' | 'banned' = forceCleanStaleCloudBan
      ? 'active'
      : uData.status === 'banned'
      ? 'banned'
      : 'active';

    const normalizedSavedAccounts = toArraySafe<BankAccount>(uData.savedAccounts);
    const normalizedUserRecord: CloudUserRecord = {
      ...uData,
      status: effectiveCloudStatus,
      ...(forceCleanStaleCloudBan
        ? {
            banReason: '',
            bannedAt: '',
            banExpiresAt: '',
            banDurationLabel: '',
            banCustomConfig: undefined,
            updatedAt: new Date(nowMs).toISOString(),
            updatedAtMs: nowMs,
          }
        : {}),
      ...(normalizedSavedAccounts.length > 0 ? { savedAccounts: normalizedSavedAccounts } : {}),
    };
    cloudUserStatusRef.current = normalizedUserRecord;
    setCloudUserStatus(normalizedUserRecord);

    // Dual-Vault Recovery: Jika dokumen profil email/UID memiliki savedAccounts, gabungkan langsung ke daftar accounts agar tidak pernah hilang
    if (normalizedSavedAccounts.length > 0) {
      const mergedFromUserVault = unionMergeAccountsList(
        accountsRef.current,
        [normalizedSavedAccounts, latestServerAccountsRef.current],
        deletedAccountIdsRef.current
      );
      latestServerAccountsRef.current = mergedFromUserVault;
      accountsRef.current = mergedFromUserVault;
      setAccounts(mergedFromUserVault);
    }

    if (uData.notificationCategoryPermissions && typeof uData.notificationCategoryPermissions === 'object') {
      const normalizedPerms = sanitizeNotificationCategoryPermissions(
        uData.notificationCategoryPermissions
      );
      setUserSettings((prev) => ({
        ...prev,
        notificationCategoryPermissions: normalizedPerms,
      }));
    }

    // Isolasi Multi-Perangkat: JANGAN pernah memaksa perpindahan currentAccountId dari lastAccountId perangkat lain!

    if (effectiveCloudStatus === 'banned') {
      setActiveGiftModal(null);
      setIsMintolModalOpen(false);
      setIsBugReportModalOpen(false);
      setIsGlobalChatModalOpen(false);
    }

    setAccounts((prev) => {
      const baseList =
        normalizedSavedAccounts.length > 0
          ? unionMergeAccountsList(prev, [normalizedSavedAccounts], deletedAccountIdsRef.current)
          : prev;
      const updatedList = baseList.map((acc) => {
        const accGoogle = acc.googleEmail ? normalizeEmailKey(acc.googleEmail) : '';
        const accEmail = acc.email ? normalizeEmailKey(acc.email) : '';
        const isLinked =
          (contextUid && acc.firebaseUid === contextUid) ||
          (uData.lastAccountId && acc.id === uData.lastAccountId) ||
          (cleanTargetEmail && (accGoogle === cleanTargetEmail || accEmail === cleanTargetEmail));
        if (!isLinked) return acc;

        const nextFailedAttempts =
          typeof uData.failedPinAttempts === 'number'
            ? uData.failedPinAttempts
            : acc.failedPinAttempts || 0;

        if (effectiveCloudStatus === 'banned') {
          const resolvedCustomCfg = uData.banCustomConfig || acc.banInfo?.customConfig;
          const rawReason =
            uData.banReason !== undefined ? uData.banReason : acc.banReason ?? acc.banInfo?.reason ?? '';
          const resolvedExpiresAt = uData.banExpiresAt || acc.banInfo?.expiresAt || acc.banInfo?.bannedUntil;
          const resolvedDurationType: 'custom' | 'permanent' = resolvedExpiresAt
            ? 'custom'
            : acc.banInfo?.durationType || 'permanent';
          return {
            ...acc,
            firebaseUid: acc.firebaseUid || contextUid,
            status: 'banned' as const,
            banReason: rawReason,
            cardStatus: 'banned' as const,
            failedPinAttempts: nextFailedAttempts,
            banInfo: {
              ...(acc.banInfo || {
                durationType: resolvedDurationType,
                durationLabel: uData.banDurationLabel || 'PERMANEN',
                bannedAt: uData.bannedAt || new Date().toISOString(),
                expiresAt: resolvedExpiresAt,
                bannedUntil: resolvedExpiresAt,
              }),
              isBanned: true,
              durationType: resolvedDurationType,
              reason: rawReason,
              expiresAt: resolvedExpiresAt,
              bannedUntil: resolvedExpiresAt,
              durationLabel: uData.banDurationLabel || acc.banInfo?.durationLabel || 'PERMANEN',
              appealStatus: uData.appealStatus || acc.banInfo?.appealStatus || 'none',
              appealNote: uData.appealNote ?? acc.banInfo?.appealNote,
              appealCategory: uData.appealCategory ?? acc.banInfo?.appealCategory,
              appealCount: uData.appealCount ?? acc.banInfo?.appealCount ?? 0,
              appealAdminNote: uData.appealAdminNote ?? acc.banInfo?.appealAdminNote,
              appealRequestedAt: uData.appealRequestedAt ?? acc.banInfo?.appealRequestedAt,
              customConfig: resolvedCustomCfg,
            },
          };
        }
        if (acc.status === 'banned' || acc.cardStatus === 'banned' || acc.banInfo?.isBanned) {
          const stamp = Math.max(nowMs, uDataUpdatedMs);
          return {
            ...acc,
            firebaseUid: acc.firebaseUid || contextUid,
            status: 'active' as const,
            banReason: '',
            cardStatus: 'active' as const,
            failedPinAttempts: nextFailedAttempts,
            banInfo: undefined,
            scheduledBanConfig: undefined,
            isDebtAutoBanned: false,
            accountUpdatedAtMs: Math.max(acc.accountUpdatedAtMs || 0, stamp),
            unbannedAtMs: Math.max(acc.unbannedAtMs || 0, stamp),
          };
        }
        return {
          ...acc,
          failedPinAttempts: nextFailedAttempts,
          loginLockedUntil:
            uData.loginLockedUntil !== undefined ? uData.loginLockedUntil : acc.loginLockedUntil,
          loginLockReason:
            uData.loginLockReason !== undefined ? uData.loginLockReason : acc.loginLockReason,
        };
      });
      accountsRef.current = updatedList;
      latestServerAccountsRef.current = updatedList;

      if (forceCleanStaleCloudBan) {
        void syncCloudUserProfile(
          {
            uid: contextUid || uData.uid,
            email: cleanTargetEmail || uData.email,
            fallbackEmail: uData.email,
          },
          {
            status: 'active',
            banReason: '',
            bannedAt: '',
            banExpiresAt: '',
            banDurationLabel: '',
            banCustomConfig: null,
            failedPinAttempts: 0,
          },
          updatedList
        );
      }
      return updatedList;
    });
  };

  const syncCloudUserProfile = async (
    target: { uid?: string; email?: string; fallbackEmail?: string },
    fields: Record<string, unknown>,
    sourceAccounts?: BankAccount[]
  ) => {
    const emailSet = new Set<string>();
    if (target.email && target.email.includes('@')) {
      emailSet.add(normalizeEmailKey(target.email));
    }
    if (target.fallbackEmail && target.fallbackEmail.includes('@')) {
      emailSet.add(normalizeEmailKey(target.fallbackEmail));
    }

    const pool = sourceAccounts ?? accountsRef.current;
    const matchingSavedAccounts = pool.filter((a) => {
      if (
        !a ||
        !a.id ||
        deletedAccountIdsRef.current.includes(a.id) ||
        PURGED_BOT_ACCOUNT_IDS.includes(a.id) ||
        PURGED_BOT_ACCOUNT_NUMBERS.includes(a.accountNumber)
      ) {
        return false;
      }
      if (target.uid && a.firebaseUid === target.uid) return true;
      const gEm = a.googleEmail ? normalizeEmailKey(a.googleEmail) : '';
      const aEm = a.email ? normalizeEmailKey(a.email) : '';
      return (gEm && emailSet.has(gEm)) || (aEm && emailSet.has(aEm));
    });

    const payload = sanitizeForFirestore({
      ...fields,
      ...(matchingSavedAccounts.length > 0 ? { savedAccounts: matchingSavedAccounts } : {}),
      updatedAt: new Date().toISOString(),
      updatedAtMs: Date.now(),
    }) as Record<string, unknown>;
    const tasks: Promise<unknown>[] = [];
    if (target.uid) {
      tasks.push(
        writeCloudDoc('users', target.uid, payload, { merge: true }).catch(() => {})
      );
    }
    emailSet.forEach((em) => {
      const eKey = emailToFirestoreDocId(em);
      tasks.push(
        writeCloudDoc(
          'users_by_email',
          eKey,
          { ...payload, email: em, emailKey: eKey },
          { merge: true }
        ).catch(() => {})
      );
    });
    await Promise.all(tasks);
  };

  // Permanent Firebase Auth Initialization (isAuthLoading ketat berbasis onAuthStateChanged) + Fast-Boot IndexedDB
  useEffect(() => {
    let active = true;
    let userDocUnsub: (() => void) | null = null;
    let bootUnlocked = false;
    let hasAuthResolved = false;
    let hasCloudAccountsArrived = false;

    const unlockBootUI = () => {
      if (!active || bootUnlocked) return;
      bootUnlocked = true;
      hasBootHydratedRef.current = true;
      setIsCloudBootReady(true);
    };

    const finishAuthCheck = () => {
      if (!active) return;
      hasAuthResolved = true;
      setIsAuthLoading(false);
      unlockBootUI();
    };

    // Tandai status sinkronisasi halus di HUD Navbar saat boot berlangsung
    updateSyncTelemetry({
      hasPendingWrites: true,
      lastError: null,
    });

    // Timeout pengaman 2.5 detik HANYA mempercepat sinkronisasi data jika onAuthStateChanged SUDAH selesai;
    // TIDAK PERNAH memotong isAuthLoading agar aplikasi tidak pernah mental ke halaman Login!
    const hardTimeoutId = window.setTimeout(() => {
      if (!active || bootUnlocked || !hasAuthResolved) return;
      hasFirestoreHydratedRef.current = true;
      updateSyncTelemetry({
        fromCache: true,
        hasPendingWrites: true,
      });
      unlockBootUI();
    }, 2500);

    // Fase 0 (< 50ms): Baca cache Fast-Boot & Active Session Envelope dari IndexedDB secara paralel
    const fastCachePromise = Promise.all([readFastBootSnapshot(), readActiveBootSession()]);

    // Jalankan pengecekan konektivitas secara non-blocking di latar belakang (popup-only, tanpa redirect)
    void testConnection();
    void resolvePendingAuthRedirect();

    // Muat payload riwayat panjang (transactions, chats, notifications, giftEvents, appUpdates, dll.) di latar belakang
    const hydrateFullMasterInBackground = () => {
      void getEarlyFullMasterPrefetch(6000)
        .then((fullMaster) => {
          if (!active || !fullMaster || isLinkingAccountToGoogleRef.current) return;
          applyMasterCloudData(fullMaster, { forceInitial: true });
          hasCloudAccountsArrived = true;
          hasFirestoreHydratedRef.current = true;
          const syncedIso = new Date().toISOString();
          setCloudSyncStatus('synced');
          setLastCloudSyncAt(syncedIso);
          updateSyncTelemetry({
            fromCache: false,
            hasPendingWrites: false,
            pendingWritesCount: 0,
            lastSyncedAt: syncedIso,
            syncedDocCount: accountsRef.current.length,
            lastError: null,
          });
        })
        .catch(() => {});
    };

    let authUnsub: (() => void) | null = null;

    const handleAuthSnapshot = async (fbUser: FirebaseUser | null) => {
      if (!active) return;

      if (userDocUnsub) {
        userDocUnsub();
        userDocUnsub = null;
      }

      setFirebaseUser(fbUser);

      // Jika sedang proses menyambungkan Akun Guest / Akun OA ke Google (linkCurrentAccountWithGooglePopup),
      // jangan timpa state accounts lokal dengan master_state lama sebelum proses merge & write selesai!
      if (isLinkingAccountToGoogleRef.current) {
        hasFirestoreHydratedRef.current = true;
        finishAuthCheck();
        return;
      }

      // 1. Baca SEGAR setiap callback onAuthStateChanged agar login baru (Google / Anonymous Guest) tidak pernah membaca cache basi t=0
      const [cachedBoot, savedSession, currentDeviceId] = await Promise.all([
        readFastBootSnapshot(),
        readActiveBootSession(),
        getOrCreatePersistentDeviceId(),
      ]);
      if (!active) return;

      // Sesi lokal sah jika tersimpan lengkap pada penyimpanan perangkat INI.
      // Jika sesi berasal dari versi sebelum ada field deviceId, izinkan migrasi & langsung segel ke currentDeviceId.
      // Jika deviceId ada dan berbeda, tolak!
      const hasValidSessionFields = Boolean(
        savedSession &&
          savedSession.activeAccountId &&
          savedSession.isPinVerified === true &&
          savedSession.hasCompletedOnboarding === true
      );
      const isDeviceBoundValid = Boolean(
        savedSession && (!savedSession.deviceId || savedSession.deviceId === currentDeviceId)
      );
      const isValidLocalDeviceSession = Boolean(hasValidSessionFields && isDeviceBoundValid);

      if (isValidLocalDeviceSession && savedSession && !savedSession.deviceId) {
        void saveActiveBootSession({
          ...savedSession,
          deviceId: currentDeviceId,
        });
      }

      let workingAccounts: BankAccount[] = accountsRef.current;
      const sessionBackups =
        isValidLocalDeviceSession && Array.isArray(savedSession?.accountBackups)
          ? (savedSession!.accountBackups as BankAccount[])
          : [];
      const cachedAccountsList =
        isValidLocalDeviceSession && Array.isArray(cachedBoot?.accounts)
          ? (cachedBoot!.accounts as BankAccount[])
          : [];

      if ((cachedAccountsList.length > 0 || sessionBackups.length > 0) && !hasCloudAccountsArrived) {
        const cachedDelIds = Array.isArray(cachedBoot?.deletedAccountIds)
          ? cachedBoot!.deletedAccountIds
          : deletedAccountIdsRef.current;
        if (cachedDelIds.length > 0) {
          setDeletedAccountIds(cachedDelIds);
        }
        const mergedCached = unionMergeAccountsList(
          sessionBackups.length > 0 ? sessionBackups : cachedAccountsList,
          [cachedAccountsList, latestServerAccountsRef.current, accountsRef.current],
          cachedDelIds
        );
        if (mergedCached.length > 0) {
          workingAccounts = mergedCached;
          latestServerAccountsRef.current = mergedCached;
          accountsRef.current = mergedCached;
          setAccounts(mergedCached);
        }
        if (cachedBoot?.banSupportConfig && typeof cachedBoot.banSupportConfig === 'object') {
          const cachedBan = cachedBoot.banSupportConfig as BanSupportConfig;
          const resolvedTemplate =
            cachedBan.defaultTemplate ||
            cachedBan.defaultTemplateConfig ||
            DEFAULT_BAN_SCREEN_CONFIG;
          setBanSupportConfig((prev) => ({
            ...prev,
            ...cachedBan,
            defaultTemplate: resolvedTemplate,
            defaultTemplateConfig: resolvedTemplate,
          }));
        }
      }

      // Helper: Pasang listener real-time users/{uid} segera agar sinyal Ban mengunci layar seketika
      const attachGoogleRealtimeListener = (uid: string, cleanEmail: string) => {
        if (userDocUnsub) {
          userDocUnsub();
          userDocUnsub = null;
        }
        userDocUnsub = subscribeCloudDoc<CloudUserRecord>(
          'users',
          uid,
          (uData) => {
            if (!uData) return;
            applyCloudUserDocSnapshot(uData, uid, cleanEmail);
          },
          (err) => {
            handleFirestoreError(err, OperationType.GET, `users/${uid}`, {
              suppressThrow: true,
            });
          }
        );
      };

      // Helper bersama untuk memulihkan sesi lokal terverifikasi (termasuk fallback ke RTDB jika akun belum ada di cache lokal)
      const restoreVerifiedLocalSession = async (): Promise<boolean> => {
        if (!active || !isValidLocalDeviceSession || !savedSession?.activeAccountId) {
          return false;
        }
        const activeId = savedSession.activeAccountId;
        if (deletedAccountIdsRef.current.includes(activeId)) {
          return false;
        }

        let candidatePool = workingAccounts;
        let restoredAcc =
          candidatePool.find((a) => a.id === activeId) ||
          sessionBackups.find((a) => a.id === activeId) ||
          null;

        if (!restoredAcc) {
          const earlyAccountsRes = await getEarlyAccountsPrefetch(3500);
          if (!active) return false;
          if (earlyAccountsRes?.accounts) {
            const delIds = toArraySafe<string>(earlyAccountsRes.deletedAccountIds);
            const mergedDel =
              delIds.length > 0
                ? Array.from(new Set([...deletedAccountIdsRef.current, ...delIds]))
                : deletedAccountIdsRef.current;
            if (delIds.length > 0) setDeletedAccountIds(mergedDel);
            if (mergedDel.includes(activeId)) {
              return false;
            }
            const incomingAccs = toArraySafe<BankAccount>(earlyAccountsRes.accounts);
            if (incomingAccs.length > 0) {
              candidatePool = unionMergeAccountsList(
                incomingAccs,
                [sessionBackups, latestServerAccountsRef.current, accountsRef.current],
                mergedDel
              );
              latestServerAccountsRef.current = candidatePool;
              accountsRef.current = candidatePool;
              setAccounts(candidatePool);
              hasCloudAccountsArrived = true;
              void saveFastBootSnapshot({
                accounts: candidatePool,
                deletedAccountIds: mergedDel,
                cachedAtMs: Date.now(),
              });
            }
          }
          restoredAcc =
            candidatePool.find((a) => a.id === activeId) ||
            sessionBackups.find((a) => a.id === activeId) ||
            null;
        }

        if (!restoredAcc || !active) {
          return false;
        }

        const cleanRestoredEmail = savedSession.email ? normalizeEmailKey(savedSession.email) : '';
        const resolvedUid = restoredAcc.firebaseUid || savedSession.firebaseUid;
        if (resolvedUid) {
          attachGoogleRealtimeListener(resolvedUid, cleanRestoredEmail);
        }

        setCurrentAccountIdState(restoredAcc.id);
        setActiveCloudEmail(cleanRestoredEmail || '');
        setCloudAccountVerificationState('confirmed_has_accounts');
        setGoogleUser({
          email: cleanRestoredEmail,
          name: restoredAcc.fullName || savedSession.name,
          picture: savedSession.picture,
          firebaseUid: resolvedUid,
          authMode: savedSession.authMode,
          emailKey: cleanRestoredEmail ? emailToFirestoreDocId(cleanRestoredEmail) : savedSession.emailKey,
          loggedInAt: new Date().toISOString(),
          hasCompletedOnboarding: true,
          isPinVerified: true,
        });
        persistActiveSessionToIdb({
          authMode: savedSession.authMode,
          firebaseUid: resolvedUid,
          email: cleanRestoredEmail,
          emailKey: cleanRestoredEmail ? emailToFirestoreDocId(cleanRestoredEmail) : savedSession.emailKey,
          name: restoredAcc.fullName || savedSession.name,
          picture: savedSession.picture,
          activeAccountId: restoredAcc.id,
          isPinVerified: true,
          hasCompletedOnboarding: true,
          accountsPool: candidatePool,
        });
        updateSyncTelemetry({
          fromCache: !hasCloudAccountsArrived,
          hasPendingWrites: !hasCloudAccountsArrived,
          syncedDocCount: candidatePool.length,
        });
        hasFirestoreHydratedRef.current = true;
        finishAuthCheck();
        hydrateFullMasterInBackground();
        return true;
      };

      // =========================================================================
      // MODE A: Sesi Anonymous Vault (signInAnonymously) — WAJIB segel deviceId lokal
      // =========================================================================
      if (fbUser && fbUser.isAnonymous && active) {
        if (!isValidLocalDeviceSession) {
          // Perangkat baru / tanpa sesi lokal sah -> jangan pernah auto-login ke akun Guest/OA perangkat lain
          setGoogleUser(null);
          setActiveCloudEmail(null);
          setCurrentAccountIdState('');
          hasFirestoreHydratedRef.current = true;
          finishAuthCheck();
          hydrateFullMasterInBackground();
          return;
        }
        void registerActiveDeviceSession(fbUser.uid, 'anonymous');

        const applyGuestMatch = (accs: BankAccount[]): BankAccount | null => {
          const preferredId = savedSession?.activeAccountId;
          const matchedGuest =
            (preferredId ? accs.find((a) => a.id === preferredId) : null) ||
            accs.find((a) => a.firebaseUid === fbUser.uid && a.isGuestAccount) ||
            accs.find((a) => a.firebaseUid === fbUser.uid) ||
            null;
          if (matchedGuest && active) {
            const resolvedAuthMode: FastBootSessionSnapshot['authMode'] =
              savedSession?.authMode === 'oa_account'
                ? 'oa_account'
                : savedSession?.authMode === 'standard_account'
                ? 'standard_account'
                : savedSession?.authMode === 'email_direct'
                ? 'email_direct'
                : savedSession?.authMode === 'google'
                ? 'google'
                : 'guest';
            setCurrentAccountIdState(matchedGuest.id);
            setActiveCloudEmail(savedSession?.email || '');
            setCloudAccountVerificationState('confirmed_has_accounts');
            setGoogleUser({
              email: savedSession?.email || '',
              name: matchedGuest.fullName,
              firebaseUid: fbUser.uid,
              authMode: resolvedAuthMode,
              loggedInAt: new Date().toISOString(),
              hasCompletedOnboarding: true,
              isPinVerified: true,
            });
          }
          return matchedGuest;
        };

        // Jika akun Guest / OA ditemukan di IndexedDB perangkat INI -> masuk Dashboard lalu sinkron latar belakang
        const instantGuest = applyGuestMatch(workingAccounts);
        if (instantGuest) {
          updateSyncTelemetry({
            fromCache: true,
            hasPendingWrites: true,
            syncedDocCount: workingAccounts.length,
          });
          finishAuthCheck();
        }

        const [earlyAccountsRes, anonVault] = await Promise.all([
          getEarlyAccountsPrefetch(2500),
          Promise.race([
            readVaultStateWithOfflineFallback<Record<string, any>>(fbUser.uid),
            new Promise<null>((resolve) => window.setTimeout(() => resolve(null), 2500)),
          ]),
        ]);
        if (!active) return;

        let cloudAccountsLoaded = workingAccounts;
        if (earlyAccountsRes?.accounts) {
          const delIds = toArraySafe<string>(earlyAccountsRes.deletedAccountIds);
          const mergedDel =
            delIds.length > 0
              ? Array.from(new Set([...deletedAccountIdsRef.current, ...delIds]))
              : deletedAccountIdsRef.current;
          if (delIds.length > 0) setDeletedAccountIds(mergedDel);
          const incomingAccs = toArraySafe<BankAccount>(earlyAccountsRes.accounts);
          if (incomingAccs.length > 0) {
            cloudAccountsLoaded = unionMergeAccountsList(
              incomingAccs,
              [latestServerAccountsRef.current, accountsRef.current],
              mergedDel
            );
            hasCloudAccountsArrived = true;
          }
        }

        const anonVaultAccounts = toArraySafe<BankAccount>(anonVault?.payload?.accounts);
        if (anonVaultAccounts.length > 0) {
          cloudAccountsLoaded = unionMergeAccountsList(
            cloudAccountsLoaded,
            [anonVaultAccounts, latestServerAccountsRef.current, accountsRef.current],
            deletedAccountIdsRef.current
          );
        }

        if (cloudAccountsLoaded.length > 0) {
          latestServerAccountsRef.current = cloudAccountsLoaded;
          accountsRef.current = cloudAccountsLoaded;
          setAccounts(cloudAccountsLoaded);
          void saveFastBootSnapshot({
            accounts: cloudAccountsLoaded,
            deletedAccountIds: deletedAccountIdsRef.current,
            cachedAtMs: Date.now(),
          });
        }

        const finalGuest = applyGuestMatch(cloudAccountsLoaded);
        if (finalGuest) {
          persistActiveSessionToIdb({
            authMode: savedSession?.authMode || 'guest',
            firebaseUid: fbUser.uid,
            email: savedSession?.email || '',
            name: finalGuest.fullName,
            activeAccountId: finalGuest.id,
            isPinVerified: true,
            hasCompletedOnboarding: true,
            accountsPool: cloudAccountsLoaded,
          });
        }
        hasFirestoreHydratedRef.current = true;
        finishAuthCheck();
        hydrateFullMasterInBackground();
        return;
      }

      // =========================================================================
      // MODE B: Sesi Google Permanen Terverifikasi
      // =========================================================================
      if (fbUser && !fbUser.isAnonymous && active) {
        // Jika di perangkat INI pengguna login eksplisit memakai Akun OA / Standard / Guest yang berbeda dari sesi Google lama,
        // hormati sesi lokal terverifikasi tersebut agar tidak terlempar ke gerbang Google saat update/refresh!
        if (
          isValidLocalDeviceSession &&
          savedSession &&
          (savedSession.authMode === 'oa_account' ||
            savedSession.authMode === 'standard_account' ||
            savedSession.authMode === 'guest') &&
          savedSession.activeAccountId
        ) {
          const restoredExplicitLocal = await restoreVerifiedLocalSession();
          if (restoredExplicitLocal) {
            return;
          }
        }

        void ensureFirestoreActiveNow();
        const cleanEmail = normalizeEmailKey(fbUser.email || '') || 'nasabah@banknusantara.id';
        const cleanName =
          fbUser.displayName?.trim() || cleanEmail.split('@')[0] || 'Nasabah Bank Nusantara';
        const emailDocId = emailToFirestoreDocId(cleanEmail);

        // Non-blocking: tulis sesi perangkat & audit log di latar belakang
        void registerActiveDeviceSession(fbUser.uid, 'google');
        void appendSecurityAuditLog(
          fbUser.uid,
          'session_init',
          `Sesi Google terverifikasi aktif (${fbUser.email || fbUser.uid}).`
        );

        // Pasang listener real-time users/{uid} SEGERA agar sinyal Ban langsung mengunci layar
        attachGoogleRealtimeListener(fbUser.uid, cleanEmail);

        const isOwnedByUser = (a: BankAccount) =>
          a.firebaseUid === fbUser.uid ||
          (a.googleEmail && normalizeEmailKey(a.googleEmail) === cleanEmail) ||
          (a.email && normalizeEmailKey(a.email) === cleanEmail);

        const isSavedSessionForThisGoogle = Boolean(
          isValidLocalDeviceSession &&
            savedSession &&
            ((savedSession.firebaseUid && savedSession.firebaseUid === fbUser.uid) ||
              (savedSession.email && normalizeEmailKey(savedSession.email) === cleanEmail) ||
              Boolean(
                savedSession.activeAccountId &&
                  workingAccounts.some((a) => a.id === savedSession.activeAccountId && isOwnedByUser(a))
              ))
        );

        const findBestGoogleAccount = (
          accs: BankAccount[],
          userDoc: CloudUserRecord | null
        ): BankAccount | null => {
          const sessionLastAccId = isSavedSessionForThisGoogle ? savedSession?.activeAccountId : undefined;
          const cloudLastAccId = userDoc?.lastAccountId;

          if (sessionLastAccId) {
            const bySession = accs.find((a) => a.id === sessionLastAccId && a.id !== 'acc-admin');
            if (bySession && isOwnedByUser(bySession)) {
              return bySession;
            }
          }
          if (cloudLastAccId) {
            const byCloudPref = accs.find((a) => a.id === cloudLastAccId && isOwnedByUser(a));
            if (byCloudPref) return byCloudPref;
          }
          const byOwner = accs.find((a) => isOwnedByUser(a));
          if (byOwner) return byOwner;

          return null;
        };

        const applyMatchedGoogleSession = (
          accs: BankAccount[],
          userDoc: CloudUserRecord | null,
          keepVerifiedFromIdb: boolean
        ): BankAccount | null => {
          if (!active) return null;
          if (userDoc) {
            setCloudUserStatus(userDoc);
          }
          setActiveCloudEmail(cleanEmail);

          const matchedAccount = findBestGoogleAccount(accs, userDoc);

          if (matchedAccount) {
            setCurrentAccountIdState(matchedAccount.id);
            setCloudAccountVerificationState('confirmed_has_accounts');
          }

          // Isolasi Perangkat Ketat: Hanya izinkan masuk langsung (isPinVerified=true) jika perangkat INI sudah terverifikasi sebelumnya.
          // Jika perangkat baru/HP ke-2 mendeteksi sesi Google tanpa segel sesi lokal di perangkat tersebut, WAJIB verifikasi PIN 6 digit!
          const isMatchedSavedSession = Boolean(
            isValidLocalDeviceSession &&
              savedSession &&
              ((savedSession.firebaseUid && savedSession.firebaseUid === fbUser.uid) ||
                (savedSession.email && normalizeEmailKey(savedSession.email) === cleanEmail) ||
                (matchedAccount && savedSession.activeAccountId === matchedAccount.id))
          );

          setGoogleUser((prev) => {
            const alreadyVerifiedInCurrentTab = Boolean(
              prev?.isPinVerified && prev?.firebaseUid === fbUser.uid && prev?.hasCompletedOnboarding
            );
            const isLocallyVerifiedOnThisDevice = Boolean(
              alreadyVerifiedInCurrentTab ||
                (keepVerifiedFromIdb && isMatchedSavedSession && savedSession?.isPinVerified)
            );
            const hasAccountReady = Boolean(
              matchedAccount ||
                userDoc?.hasCompletedOnboarding ||
                (isLocallyVerifiedOnThisDevice && savedSession?.hasCompletedOnboarding)
            );
            return {
              email: cleanEmail,
              name: matchedAccount?.fullName || cleanName,
              picture: fbUser.photoURL || prev?.picture || savedSession?.picture,
              firebaseUid: fbUser.uid,
              authMode: 'google',
              emailKey: emailDocId,
              loggedInAt: prev?.loggedInAt || new Date().toISOString(),
              hasCompletedOnboarding: hasAccountReady,
              isPinVerified: hasAccountReady && isLocallyVerifiedOnThisDevice,
            };
          });

          return matchedAccount;
        };

        // 2A. JALUR INSTAN (< 100ms): Jika rekening milik user sudah ada di IndexedDB -> LANGSUNG MASUK DASHBOARD!
        const instantMatched = applyMatchedGoogleSession(workingAccounts, null, true);
        if (instantMatched) {
          updateSyncTelemetry({
            fromCache: true,
            hasPendingWrites: true,
            syncedDocCount: workingAccounts.length,
          });
          finishAuthCheck();
        } else {
          // Belum ditemukan di cache lokal (mis. pasca-update/publish) -> TAHAN layar skeleton (isAuthLoading tetap true) sampai RTDB konfirmasi rekening!
          setCloudAccountVerificationState('verifying');
        }

        // 2B. Baca PARALEL data prioritas dari Firebase RTDB (azkaakc): accounts + users/{uid} + users_by_email/{emailKey}
        let cloudAccountsLoaded = workingAccounts;
        let initialUserData: CloudUserRecord | null = null;
        let cloudRespondedCleanly = false;
        try {
          const [earlyAccountsRes, uidData, emailData] = await Promise.all([
            getEarlyAccountsPrefetch(3800),
            readCloudDoc<CloudUserRecord>('users', fbUser.uid, {
              timeoutMs: 3800,
              skipFirestoreFallback: true,
            }),
            readCloudDoc<CloudUserRecord>('users_by_email', emailDocId, {
              timeoutMs: 3800,
              skipFirestoreFallback: true,
            }),
          ]);

          if (!active) return;

          if (earlyAccountsRes !== null || uidData !== null || emailData !== null) {
            cloudRespondedCleanly = true;
          }

          if (earlyAccountsRes?.accounts) {
            const delIds = toArraySafe<string>(earlyAccountsRes.deletedAccountIds);
            const mergedDel =
              delIds.length > 0
                ? Array.from(new Set([...deletedAccountIdsRef.current, ...delIds]))
                : deletedAccountIdsRef.current;
            if (delIds.length > 0) setDeletedAccountIds(mergedDel);

            const incomingAccs = toArraySafe<BankAccount>(earlyAccountsRes.accounts);
            if (incomingAccs.length > 0) {
              cloudAccountsLoaded = unionMergeAccountsList(
                incomingAccs,
                [sessionBackups, latestServerAccountsRef.current, accountsRef.current],
                mergedDel
              );
              hasCloudAccountsArrived = true;
            }
          }

          // Gabungkan savedAccounts dari dokumen profil users/{uid} dan users_by_email/{emailKey}
          const uidSaved = toArraySafe<BankAccount>(uidData?.savedAccounts);
          const emailSaved = toArraySafe<BankAccount>(emailData?.savedAccounts);
          if (uidSaved.length > 0 || emailSaved.length > 0) {
            const prevLen = cloudAccountsLoaded.length;
            const mergedVaultAccounts = unionMergeAccountsList(
              cloudAccountsLoaded,
              [emailSaved, uidSaved, sessionBackups, latestServerAccountsRef.current, accountsRef.current],
              deletedAccountIdsRef.current
            );
            cloudAccountsLoaded = mergedVaultAccounts;
            if (mergedVaultAccounts.length > prevLen && hasCloudAccountsArrived) {
              void flushMasterStateToCloud({ accounts: mergedVaultAccounts });
            }
          }

          if (cloudAccountsLoaded.length > 0) {
            latestServerAccountsRef.current = cloudAccountsLoaded;
            accountsRef.current = cloudAccountsLoaded;
            setAccounts(cloudAccountsLoaded);
            void saveFastBootSnapshot({
              accounts: cloudAccountsLoaded,
              deletedAccountIds: deletedAccountIdsRef.current,
              cachedAtMs: Date.now(),
            });
          }

          const allMatchedForEmail = cloudAccountsLoaded.filter(
            (a) =>
              a.firebaseUid === fbUser.uid ||
              (a.googleEmail && normalizeEmailKey(a.googleEmail) === cleanEmail) ||
              (a.email && normalizeEmailKey(a.email) === cleanEmail)
          );

          if (uidData || emailData) {
            const mergedBanned = uidData?.status === 'banned' || emailData?.status === 'banned';
            const mergedReason = emailData?.banReason || uidData?.banReason || '';
            const mergedLastAccountId =
              (isSavedSessionForThisGoogle ? savedSession?.activeAccountId : '') ||
              emailData?.lastAccountId ||
              uidData?.lastAccountId ||
              allMatchedForEmail[0]?.id ||
              '';
            const mergedOnboarded = Boolean(
              allMatchedForEmail.length > 0 ||
                emailData?.hasCompletedOnboarding ||
                uidData?.hasCompletedOnboarding
            );
            initialUserData = {
              ...(uidData || emailData)!,
              uid: fbUser.uid,
              email: cleanEmail,
              emailKey: emailDocId,
              displayName: cleanName || uidData?.displayName || emailData?.displayName || 'Nasabah',
              status: mergedBanned ? 'banned' : 'active',
              banReason: mergedReason,
              lastAccountId: mergedLastAccountId,
              hasCompletedOnboarding: mergedOnboarded,
              ...(allMatchedForEmail.length > 0 ? { savedAccounts: allMatchedForEmail } : {}),
              authMode: 'google',
            };
            if (allMatchedForEmail.length > 0) {
              const cleanUserPayload = sanitizeForFirestore(initialUserData) as Record<string, unknown>;
              void Promise.all([
                writeCloudDoc('users', fbUser.uid, cleanUserPayload, { merge: true }).catch(() => {}),
                writeCloudDoc('users_by_email', emailDocId, cleanUserPayload, { merge: true }).catch(() => {}),
              ]);
            }
          } else if (cloudRespondedCleanly) {
            const nowIso = new Date().toISOString();
            const newCloudUser: CloudUserRecord = {
              uid: fbUser.uid,
              email: cleanEmail,
              emailKey: emailDocId,
              displayName: cleanName,
              photoURL: fbUser.photoURL || undefined,
              status: 'active',
              banReason: '',
              lastAccountId: allMatchedForEmail[0]?.id || '',
              hasCompletedOnboarding: allMatchedForEmail.length > 0,
              ...(allMatchedForEmail.length > 0 ? { savedAccounts: allMatchedForEmail } : {}),
              authMode: 'google',
              emailVerified: true,
              createdAt: nowIso,
              updatedAt: nowIso,
              updatedAtMs: Date.now(),
            };
            initialUserData = newCloudUser;
            const cleanNewUserPayload = sanitizeForFirestore(newCloudUser) as Record<string, unknown>;
            void Promise.all([
              writeCloudDoc('users', fbUser.uid, cleanNewUserPayload, { merge: true }).catch(() => {}),
              writeCloudDoc('users_by_email', emailDocId, cleanNewUserPayload, { merge: true }).catch(() => {}),
            ]);
          }
        } catch (err) {
          handleFirestoreError(err, OperationType.GET, `users/${fbUser.uid}`, {
            suppressThrow: true,
          });
        }

        if (!active) return;

        // Refresh savedSession lagi sesaat sebelum keputusan final (jaga-jaga user baru saja selesai verifikasi PIN saat cloud fetch berjalan)
        const latestSavedSession = await readActiveBootSession();
        const isLatestVerifiedForThisGoogle = Boolean(
          latestSavedSession &&
            latestSavedSession.isPinVerified === true &&
            latestSavedSession.hasCompletedOnboarding === true &&
            (!latestSavedSession.deviceId || latestSavedSession.deviceId === currentDeviceId) &&
            ((latestSavedSession.firebaseUid && latestSavedSession.firebaseUid === fbUser.uid) ||
              (latestSavedSession.email && normalizeEmailKey(latestSavedSession.email) === cleanEmail) ||
              Boolean(
                latestSavedSession.activeAccountId &&
                  cloudAccountsLoaded.some((a) => a.id === latestSavedSession.activeAccountId && isOwnedByUser(a))
              ))
        );

        const finalMatched = applyMatchedGoogleSession(
          cloudAccountsLoaded,
          initialUserData,
          true
        );
        if (finalMatched) {
          setCloudAccountVerificationState('confirmed_has_accounts');
          if (isLatestVerifiedForThisGoogle) {
            setGoogleUser((prev) =>
              prev ? { ...prev, hasCompletedOnboarding: true, isPinVerified: true } : prev
            );
            persistActiveSessionToIdb({
              authMode: 'google',
              firebaseUid: fbUser.uid,
              email: cleanEmail,
              emailKey: emailDocId,
              name: finalMatched.fullName || cleanName,
              picture: fbUser.photoURL || latestSavedSession?.picture,
              activeAccountId: finalMatched.id,
              isPinVerified: true,
              hasCompletedOnboarding: true,
              accountsPool: cloudAccountsLoaded,
            });
          }
        } else if (cloudRespondedCleanly && (typeof navigator === 'undefined' || navigator.onLine)) {
          // Hanya izinkan form Buat Kartu jika Cloud benar-benar merespons dan mengonfirmasi 0 kartu!
          setCloudAccountVerificationState('confirmed_zero_accounts');
        } else {
          // Koneksi lambat/offline -> JANGAN lempar ke form Buat Akun, tampilkan tombol Muat Ulang Akun Cloud!
          setCloudAccountVerificationState('network_timeout');
        }

        hasFirestoreHydratedRef.current = true;
        finishAuthCheck();
        hydrateFullMasterInBackground();
        return;
      }

      // =========================================================================
      // MODE C: Tanpa Sesi Firebase Auth (Pulihkan SEMUA Sesi Lokal Terverifikasi termasuk OA, Guest, Standard, Email & Google)
      // =========================================================================
      if (isValidLocalDeviceSession && savedSession?.activeAccountId) {
        const restored = await restoreVerifiedLocalSession();
        if (restored) {
          return;
        }
      }

      // Belum ada sesi aktif (user === null) -> Selesaikan isAuthLoading dan tampilkan Halaman Login
      if (active && !activeCloudEmailRef.current) {
        setGoogleUser(null);
        setCloudUserStatus(null);
      }

      if (workingAccounts.length > 0 && cachedAccountsList.length > 0) {
        updateSyncTelemetry({
          fromCache: true,
          hasPendingWrites: true,
          syncedDocCount: workingAccounts.length,
        });
        finishAuthCheck();
      } else {
        const earlyAccountsRes = await getEarlyAccountsPrefetch(2200);
        if (active && earlyAccountsRes?.accounts) {
          const delIds = toArraySafe<string>(earlyAccountsRes.deletedAccountIds);
          const mergedDel =
            delIds.length > 0
              ? Array.from(new Set([...deletedAccountIdsRef.current, ...delIds]))
              : deletedAccountIdsRef.current;
          if (delIds.length > 0) setDeletedAccountIds(mergedDel);
          const incomingAccs = toArraySafe<BankAccount>(earlyAccountsRes.accounts);
          if (incomingAccs.length > 0) {
            const cleanAccounts = unionMergeAccountsList(
              incomingAccs,
              [latestServerAccountsRef.current, accountsRef.current],
              mergedDel
            );
            latestServerAccountsRef.current = cleanAccounts;
            accountsRef.current = cleanAccounts;
            setAccounts(cleanAccounts);
            hasCloudAccountsArrived = true;
            void saveFastBootSnapshot({
              accounts: cleanAccounts,
              deletedAccountIds: mergedDel,
              cachedAtMs: Date.now(),
            });
          }
        }
        hasFirestoreHydratedRef.current = true;
        finishAuthCheck();
      }

      hydrateFullMasterInBackground();
    };

    void Promise.race([
      authPersistenceReady,
      new Promise<void>((resolve) => window.setTimeout(resolve, 1200)),
    ]).then(() => {
      if (!active) return;
      authUnsub = onAuthStateChanged(auth, (fbUser) => {
        void handleAuthSnapshot(fbUser);
      });
    });

    return () => {
      active = false;
      window.clearTimeout(hardTimeoutId);
      if (authUnsub) authUnsub();
      if (userDocUnsub) userDocUnsub();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Listener Real-Time KHUSUS Berbasis Email (users_by_email/{emailKey}) untuk semua email (Email Bebas & Google)
  useEffect(() => {
    if (!activeCloudEmail) return;
    const cleanEmail = normalizeEmailKey(activeCloudEmail);
    const emailDocId = emailToFirestoreDocId(cleanEmail);

    const unsub = subscribeCloudDoc<CloudUserRecord>(
      'users_by_email',
      emailDocId,
      (eData) => {
        if (!eData) return;
        applyCloudUserDocSnapshot(eData, firebaseUser?.uid, cleanEmail);
      },
      (err) => {
        handleFirestoreError(err, OperationType.GET, `users_by_email/${emailDocId}`, {
          suppressThrow: true,
        });
      }
    );

    return () => unsub();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeCloudEmail]);

  // Penjaga Revokasi Perangkat Real-Time: jika perangkat ini dicabut dari perangkat lain, langsung keluar ke halaman Login
  useEffect(() => {
    const activeUid = firebaseUser?.uid || googleUser?.firebaseUid;
    if (!activeUid || !googleUser) return;
    const sessionStartMs = googleUser.loggedInAt ? new Date(googleUser.loggedInAt).getTime() : Date.now();
    let cancelled = false;
    let unsub: (() => void) | null = null;
    void getOrCreatePersistentDeviceId().then((myDeviceId) => {
      if (cancelled || !myDeviceId) return;
      unsub = subscribeActiveDevices(activeUid, (devices) => {
        const selfRecord = devices.find((d) => d.deviceId === myDeviceId);
        if (selfRecord?.revoked) {
          const revokedAtMs = selfRecord.revokedAtIso ? new Date(selfRecord.revokedAtIso).getTime() : 0;
          // Abaikan revokasi lama yang terjadi sebelum sesi login baru di perangkat ini
          if (revokedAtMs > 0 && Number.isFinite(sessionStartMs) && revokedAtMs < sessionStartMs - 2000) {
            return;
          }
          void clearActiveBootSession();
          void clearFastBootSnapshot();
          setCurrentAccountIdState('');
          setActiveCloudEmail(null);
          setGoogleUser(null);
          setCloudUserStatus(null);
          setFirebaseUser(null);
          void signOut(auth).catch(() => {});
        }
      });
    });
    return () => {
      cancelled = true;
      if (unsub) unsub();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [firebaseUser?.uid, googleUser?.firebaseUid]);

  // Real-time Multi-Device Firebase Realtime Database Listener (HP <-> Laptop tanpa refresh)
  useEffect(() => {
    const unsub = subscribeCloudDoc<Record<string, any>>(
      'bank_state_v1',
      'master_state',
      (data) => {
        if (typeof navigator !== 'undefined' && !navigator.onLine) {
          setCloudSyncStatus('offline');
          updateSyncTelemetry({ isOnline: false, fromCache: true });
        } else {
          const syncedIso = new Date().toISOString();
          setCloudSyncStatus('synced');
          setLastCloudSyncAt(syncedIso);
          updateSyncTelemetry({
            isOnline: true,
            fromCache: false,
            hasPendingWrites: false,
            pendingWritesCount: 0,
            lastSyncedAt: syncedIso,
            syncedDocCount: accountsRef.current.length,
            lastError: null,
          });
        }

        if (data && !isLinkingAccountToGoogleRef.current) {
          applyMasterCloudData(data);
        }
        hasFirestoreHydratedRef.current = true;
      },
      (err) => {
        setCloudSyncStatus('offline');
        handleFirestoreError(err, OperationType.GET, 'bank_state_v1/master_state', {
          suppressThrow: true,
        });
        hasFirestoreHydratedRef.current = true;
      }
    );
    return () => unsub();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const [defaultLetterSealConfig, setDefaultLetterSealConfig] = useState<LetterSignatureStampConfig>({
    ...FALLBACK_LETTER_SEAL_BASE,
  });
  const defaultLetterSealConfigRef = useRef<LetterSignatureStampConfig>(defaultLetterSealConfig);
  defaultLetterSealConfigRef.current = defaultLetterSealConfig;
  const letterSealUpdatedAtMsRef = useRef<number>(0);
  const hasLoadedSealRegistryRef = useRef<boolean>(false);
  const [letterSealCloudStatus, setLetterSealCloudStatus] = useState<
    'idle' | 'saving' | 'saved' | 'error'
  >('idle');
  const [letterSealLastSavedAt, setLetterSealLastSavedAt] = useState<string | null>(null);
  const [letterSealSaveError, setLetterSealSaveError] = useState<string | null>(null);

  const applyDedicatedGiftRegistrySnapshot = (
    docData: Record<string, any> | null,
    options?: { markLoadedIfNull?: boolean }
  ) => {
    if (!docData || typeof docData !== 'object') {
      if (options?.markLoadedIfNull && !hasLoadedGiftRegistryRef.current) {
        hasLoadedGiftRegistryRef.current = true;
      }
      return;
    }
    const incomingTs = Number(docData.giftEventsUpdatedAtMs || docData.updatedAtMs || 0);
    if (
      docData.writerSessionId === clientSessionId &&
      hasLoadedGiftRegistryRef.current &&
      incomingTs <= giftEventsUpdatedAtMsRef.current
    ) {
      return;
    }
    if (hasLoadedGiftRegistryRef.current && incomingTs > 0 && incomingTs < giftEventsUpdatedAtMsRef.current) {
      return;
    }
    const incomingDelIds = toArraySafe<string>(docData.deletedGiftEventIds);
    const mergedDelIds = Array.from(new Set([...deletedGiftEventIdsRef.current, ...incomingDelIds]));
    const incomingEvents = toArraySafe<AdminGiftEventPackage>(docData.giftEvents).map(
      normalizeGiftEventPackage
    );
    const filteredEvents = sanitizeGiftEventsRemoveMiningRewards(
      incomingEvents.filter((ev) => ev && ev.id && !mergedDelIds.includes(ev.id))
    );

    if (incomingTs > giftEventsUpdatedAtMsRef.current) {
      giftEventsUpdatedAtMsRef.current = incomingTs;
    }
    hasLoadedGiftRegistryRef.current = true;
    isApplyingFirestoreRef.current = true;
    deletedGiftEventIdsRef.current = mergedDelIds;
    setDeletedGiftEventIds(mergedDelIds);
    giftEventsInitializedRef.current = true;
    setGiftEventsInitialized(true);
    giftEventsRef.current = filteredEvents;
    setGiftEvents(filteredEvents);
    setGiftRegistryCloudStatus('saved');
    setGiftRegistryLastSavedAt(
      typeof docData.updatedAt === 'string' ? docData.updatedAt : new Date().toISOString()
    );
    void saveGiftAndSealRegistryIdb({
      giftEvents: filteredEvents,
      deletedGiftEventIds: mergedDelIds,
      giftEventsInitialized: true,
      giftEventsUpdatedAtMs: giftEventsUpdatedAtMsRef.current || Date.now(),
    });
    window.setTimeout(() => {
      isApplyingFirestoreRef.current = false;
    }, 80);
  };

  const applyDedicatedSealRegistrySnapshot = (
    docData: Record<string, any> | null,
    options?: { markLoadedIfNull?: boolean }
  ) => {
    if (!docData || typeof docData !== 'object') {
      if (options?.markLoadedIfNull && !hasLoadedSealRegistryRef.current) {
        hasLoadedSealRegistryRef.current = true;
      }
      return;
    }
    const rawCfg =
      docData.config && typeof docData.config === 'object' ? docData.config : docData;
    if (!rawCfg || typeof rawCfg !== 'object' || !('signatureMode' in rawCfg)) {
      return;
    }
    const incomingTs = Number(docData.updatedAtMs || 0);
    if (
      docData.writerSessionId === clientSessionId &&
      hasLoadedSealRegistryRef.current &&
      incomingTs <= letterSealUpdatedAtMsRef.current
    ) {
      return;
    }
    if (hasLoadedSealRegistryRef.current && incomingTs > 0 && incomingTs < letterSealUpdatedAtMsRef.current) {
      return;
    }
    const normalizedSeal = normalizeLetterSealConfig(rawCfg, defaultLetterSealConfigRef.current);
    if (incomingTs > letterSealUpdatedAtMsRef.current) {
      letterSealUpdatedAtMsRef.current = incomingTs;
    }
    hasLoadedSealRegistryRef.current = true;
    isApplyingFirestoreRef.current = true;
    defaultLetterSealConfigRef.current = normalizedSeal;
    setDefaultLetterSealConfig(normalizedSeal);
    setLetterSealCloudStatus('saved');
    setLetterSealLastSavedAt(
      typeof docData.updatedAt === 'string' ? docData.updatedAt : new Date().toISOString()
    );
    void saveGiftAndSealRegistryIdb({
      defaultLetterSealConfig: normalizedSeal,
      letterSealUpdatedAtMs: letterSealUpdatedAtMsRef.current || Date.now(),
    });
    window.setTimeout(() => {
      isApplyingFirestoreRef.current = false;
    }, 80);
  };

  // Dedicated Boot + Real-Time Subscriptions for Gift Events & Letter Seal Registries
  useEffect(() => {
    let mounted = true;
    void readGiftAndSealRegistryIdb().then((cached) => {
      if (!mounted || !cached) return;
      if (
        Array.isArray(cached.giftEvents) &&
        (!hasLoadedGiftRegistryRef.current ||
          Number(cached.giftEventsUpdatedAtMs || 0) > giftEventsUpdatedAtMsRef.current)
      ) {
        const cachedDelIds = Array.isArray(cached.deletedGiftEventIds)
          ? cached.deletedGiftEventIds
          : deletedGiftEventIdsRef.current;
        const normalizedCachedGifts = sanitizeGiftEventsRemoveMiningRewards(
          cached.giftEvents
            .map(normalizeGiftEventPackage)
            .filter((ev) => ev && ev.id && !cachedDelIds.includes(ev.id))
        );
        giftEventsUpdatedAtMsRef.current = Number(cached.giftEventsUpdatedAtMs || Date.now());
        hasLoadedGiftRegistryRef.current = true;
        deletedGiftEventIdsRef.current = cachedDelIds;
        setDeletedGiftEventIds(cachedDelIds);
        giftEventsInitializedRef.current = true;
        setGiftEventsInitialized(true);
        giftEventsRef.current = normalizedCachedGifts;
        setGiftEvents(normalizedCachedGifts);
      }
      if (
        cached.defaultLetterSealConfig &&
        typeof cached.defaultLetterSealConfig === 'object' &&
        (!hasLoadedSealRegistryRef.current ||
          Number(cached.letterSealUpdatedAtMs || 0) > letterSealUpdatedAtMsRef.current)
      ) {
        const normalizedSeal = normalizeLetterSealConfig(
          cached.defaultLetterSealConfig,
          defaultLetterSealConfigRef.current
        );
        letterSealUpdatedAtMsRef.current = Number(cached.letterSealUpdatedAtMs || Date.now());
        hasLoadedSealRegistryRef.current = true;
        defaultLetterSealConfigRef.current = normalizedSeal;
        setDefaultLetterSealConfig(normalizedSeal);
      }
    });

    const applyDedicatedRedeemRegistrySnapshot = (rawData: Record<string, any>) => {
      if (!rawData || !Array.isArray(rawData.redeemCodes)) return;
      const incomingTs = Number(rawData.redeemCodesUpdatedAtMs || rawData.updatedAtMs || 0);
      if (incomingTs > 0 && incomingTs < redeemCodesUpdatedAtMsRef.current) {
        return;
      }
      const cleanList = sanitizeRedeemCodesList(rawData.redeemCodes);
      redeemCodesUpdatedAtMsRef.current = incomingTs || Date.now();
      redeemCodesRef.current = cleanList;
      isApplyingFirestoreRef.current = true;
      setRedeemCodes(cleanList);
      try {
        window.localStorage.setItem(
          'bank_nusantara_redeem_codes_registry_v1',
          JSON.stringify({
            redeemCodes: cleanList,
            redeemCodesUpdatedAtMs: redeemCodesUpdatedAtMsRef.current,
          })
        );
      } catch {
        // ignore quota errors
      }
      window.setTimeout(() => {
        isApplyingFirestoreRef.current = false;
      }, 80);
    };

    void Promise.all([
      readCloudDocDual<Record<string, any>>('bank_state_v1', 'gift_events_registry', {
        timeoutMs: 4500,
      }),
      readCloudDocDual<Record<string, any>>('bank_state_v1', 'letter_seal_config', {
        timeoutMs: 4500,
      }),
      readCloudDocDual<Record<string, any>>('bank_state_v1', 'redeem_codes_registry', {
        timeoutMs: 4500,
      }),
    ]).then(([giftRes, sealRes, redeemRes]) => {
      if (!mounted) return;
      if (giftRes.data) {
        applyDedicatedGiftRegistrySnapshot(giftRes.data);
      } else if (giftRes.respondedCleanly) {
        hasLoadedGiftRegistryRef.current = true;
      }
      if (sealRes.data) {
        applyDedicatedSealRegistrySnapshot(sealRes.data);
      } else if (sealRes.respondedCleanly) {
        hasLoadedSealRegistryRef.current = true;
      }
      if (redeemRes.data) {
        applyDedicatedRedeemRegistrySnapshot(redeemRes.data);
      }
    });

    const unsubGiftDual = subscribeCloudDocDual<Record<string, any>>(
      'bank_state_v1',
      'gift_events_registry',
      (data) => {
        if (!mounted || !data) return;
        applyDedicatedGiftRegistrySnapshot(data);
      },
      (err) => {
        handleFirestoreError(err, OperationType.GET, 'bank_state_v1/gift_events_registry', {
          suppressThrow: true,
        });
      }
    );

    const unsubSealDual = subscribeCloudDocDual<Record<string, any>>(
      'bank_state_v1',
      'letter_seal_config',
      (data) => {
        if (!mounted || !data) return;
        applyDedicatedSealRegistrySnapshot(data);
      },
      (err) => {
        handleFirestoreError(err, OperationType.GET, 'bank_state_v1/letter_seal_config', {
          suppressThrow: true,
        });
      }
    );

    const unsubRedeemDual = subscribeCloudDocDual<Record<string, any>>(
      'bank_state_v1',
      'redeem_codes_registry',
      (data) => {
        if (!mounted || !data) return;
        applyDedicatedRedeemRegistrySnapshot(data);
      },
      (err) => {
        handleFirestoreError(err, OperationType.GET, 'bank_state_v1/redeem_codes_registry', {
          suppressThrow: true,
        });
      }
    );

    return () => {
      mounted = false;
      unsubGiftDual();
      unsubSealDual();
      unsubRedeemDual();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [firebaseUser?.uid]);

  // Automatic Real-Time Cloud Sync Coordinator (Debounced Firestore Write - Zero localStorage)
  // KUNCI ANTI-TIMPA: Jangan pernah auto-flush master_state di latar belakang dari perangkat yang masih berada di halaman login / belum verifikasi PIN!
  useEffect(() => {
    if (
      !hasFirestoreHydratedRef.current ||
      !hasBootHydratedRef.current ||
      isApplyingFirestoreRef.current ||
      isApplyingExternalSnapshotRef.current
    ) {
      return;
    }

    const isAtUnverifiedLoginLobby =
      !adminUnlocked &&
      (!googleUser ||
        !googleUser.hasCompletedOnboarding ||
        ((googleUser.authMode === 'google' || googleUser.authMode === 'email_direct') &&
          !googleUser.isPinVerified));
    if (isAtUnverifiedLoginLobby) {
      return;
    }

    const t = window.setTimeout(() => {
      flushMasterStateToCloud();
    }, 350);
    return () => window.clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    accounts,
    deletedAccountIds,
    accountDeletionRequests,
    transactions,
    giftEvents,
    deletedGiftEventIds,
    giftEventsInitialized,
    dashboardEffectEvents,
    banSupportConfig,
    supportFaqs,
    supportContactConfig,
    pockets,
    depositos,
    loans,
    scheduledPayments,
    favorites,
    notifications,
    chats,
    cardUpgrades,
    pinResetRequests,
    redeemCodes,
    purchasedCodes,
    resiList,
    cardlessTokens,
    spinWheelConfig,
    spinHistory,
    sultanEmpireConfig,
    rawFeatureConfigs,
    deletedFeatureIds,
    userSettings,
    goldMarketConfig,
    budgetCategories,
    manualExpenses,
    budgetTxCategoryMap,
    budgetAlertHistory,
    appUpdates,
    devRoles,
    defaultLetterSealConfig,
    jobCoinBonusConfig,
    adminHelpRequests,
    websitePopups,
    globalChats,
    bugReports,
    missions,
    missionConfig,
    missionProgressByAccount,
    missionClaimLogs,
    leaderboardConfig,
    adminTierNotificationConfig,
  ]);

  const syncGiftEventsToServer = (
    eventsToSync: AdminGiftEventPackage[],
    deletedIdsToSync: string[] = deletedGiftEventIdsRef.current,
    giftEventsUpdatedAtMs: number = giftEventsUpdatedAtMsRef.current || Date.now()
  ) => {
    try {
      if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
        wsRef.current.send(
          JSON.stringify({
            type: 'gift_events:sync',
            payload: {
              giftEvents: eventsToSync,
              deletedGiftEventIds: deletedIdsToSync,
              giftEventsInitialized: true,
              giftEventsUpdatedAtMs,
            },
          })
        );
      }
    } catch { /* empty */ }
    fetch('/api/gift-events', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        giftEvents: eventsToSync,
        deletedGiftEventIds: deletedIdsToSync,
        giftEventsInitialized: true,
        giftEventsUpdatedAtMs,
      }),
      keepalive: true,
    }).catch(() => { /* ignore offline */ });
  };

  const persistGiftEventsRegistryImmediately = (
    nextListRaw: AdminGiftEventPackage[],
    nextDeletedIds: string[] = deletedGiftEventIdsRef.current,
    options?: { isAdminMutation?: boolean }
  ): Promise<boolean> => {
    const isAdminMutation = options?.isAdminMutation !== false;
    const nowMs = Date.now();
    const nextRegTs = isAdminMutation
      ? Math.max(nowMs, giftEventsUpdatedAtMsRef.current + 1)
      : giftEventsUpdatedAtMsRef.current || nowMs;
    const normalizedList = sanitizeGiftEventsRemoveMiningRewards(
      nextListRaw.map(normalizeGiftEventPackage)
    ).slice(0, 150);
    const cleanDeletedIds = Array.from(new Set(nextDeletedIds.map((x) => String(x)))).slice(0, 500);

    giftEventsUpdatedAtMsRef.current = nextRegTs;
    hasLoadedGiftRegistryRef.current = true;
    deletedGiftEventIdsRef.current = cleanDeletedIds;
    setDeletedGiftEventIds(cleanDeletedIds);
    giftEventsInitializedRef.current = true;
    setGiftEventsInitialized(true);
    giftEventsRef.current = normalizedList;
    setGiftEvents(normalizedList);

    const nowIso = new Date(nowMs).toISOString();
    setGiftRegistryCloudStatus('saving');
    setGiftRegistrySaveError(null);

    void saveGiftAndSealRegistryIdb({
      giftEvents: normalizedList,
      deletedGiftEventIds: cleanDeletedIds,
      giftEventsInitialized: true,
      giftEventsUpdatedAtMs: nextRegTs,
    });
    syncGiftEventsToServer(normalizedList, cleanDeletedIds, nextRegTs);

    const registryPayload: Record<string, unknown> = isAdminMutation
      ? {
          giftEvents: normalizedList,
          deletedGiftEventIds: cleanDeletedIds,
          giftEventsInitialized: true,
          giftEventsUpdatedAtMs: nextRegTs,
          updatedAtMs: nowMs,
          updatedAt: nowIso,
          writerSessionId: clientSessionId,
          ...(auth.currentUser?.uid ? { updatedByUid: auth.currentUser.uid } : {}),
          ...(auth.currentUser?.email ? { updatedByEmail: auth.currentUser.email } : {}),
        }
      : {
          giftEvents: normalizedList,
          giftEventsInitialized: true,
          giftEventsUpdatedAtMs: nextRegTs,
          updatedAtMs: nowMs,
          updatedAt: nowIso,
          writerSessionId: clientSessionId,
        };

    const masterPromise = flushMasterStateToCloud({
      giftEvents: normalizedList,
      deletedGiftEventIds: cleanDeletedIds,
      giftEventsInitialized: true,
    });

    const dualPromise = writeCloudDocDual(
      'bank_state_v1',
      'gift_events_registry',
      registryPayload,
      { merge: !isAdminMutation }
    );

    return Promise.all([dualPromise, masterPromise])
      .then(([dualRes, masterOk]) => {
        const overallOk = dualRes.ok || Boolean(masterOk);
        if (overallOk) {
          setGiftRegistryCloudStatus('saved');
          setGiftRegistryLastSavedAt(new Date().toISOString());
          setGiftRegistrySaveError(null);
        } else {
          setGiftRegistryCloudStatus('error');
          setGiftRegistrySaveError(
            dualRes.errorMessage || 'Gagal menyinkronkan ke Cloud, tersimpan aman di perangkat.'
          );
        }
        return overallOk;
      })
      .catch((err) => {
        setGiftRegistryCloudStatus('error');
        setGiftRegistrySaveError(err instanceof Error ? err.message : 'Gangguan sinkronisasi Cloud.');
        return false;
      });
  };

  const persistRedeemCodesImmediately = (rawList: RedeemCode[]): Promise<boolean> => {
    const cleanList = sanitizeRedeemCodesList(rawList);
    const nowMs = Date.now();
    const nextRegTs = Math.max(nowMs, redeemCodesUpdatedAtMsRef.current + 1);
    const nowIso = new Date(nowMs).toISOString();

    redeemCodesUpdatedAtMsRef.current = nextRegTs;
    redeemCodesRef.current = cleanList;
    setRedeemCodes(cleanList);
    setRedeemCloudStatus('saving');
    setRedeemSaveError(null);

    try {
      window.localStorage.setItem(
        'bank_nusantara_redeem_codes_registry_v1',
        JSON.stringify({
          redeemCodes: cleanList,
          redeemCodesUpdatedAtMs: nextRegTs,
        })
      );
    } catch {
      // ignore local storage quota errors
    }

    const registryPayload = sanitizeForFirestore({
      redeemCodes: cleanList,
      redeemCodesUpdatedAtMs: nextRegTs,
      updatedAtMs: nowMs,
      updatedAt: nowIso,
      writerSessionId: clientSessionId,
    }) as Record<string, unknown>;

    const dualPromise = writeCloudDocDual(
      'bank_state_v1',
      'redeem_codes_registry',
      registryPayload,
      { merge: false }
    );
    const masterPromise = flushMasterStateToCloud({
      redeemCodes: cleanList,
    });

    return Promise.all([dualPromise, masterPromise])
      .then(([dualRes, masterOk]) => {
        const overallOk = dualRes.ok || Boolean(masterOk);
        if (overallOk) {
          setRedeemCloudStatus('saved');
          setRedeemLastSavedAt(new Date().toISOString());
          setRedeemSaveError(null);
        } else {
          setRedeemCloudStatus('error');
          setRedeemSaveError(
            dualRes.errorMessage ||
              'Gagal menyinkronkan ke Cloud, data tetap tersimpan aman di perangkat.'
          );
        }
        return overallOk;
      })
      .catch((err) => {
        setRedeemCloudStatus('error');
        setRedeemSaveError(
          err instanceof Error ? err.message : 'Gangguan sinkronisasi Cloud.'
        );
        return false;
      });
  };

  const retrySaveRedeemCodesToCloud = (): Promise<boolean> => {
    return persistRedeemCodesImmediately(redeemCodesRef.current);
  };

  const persistLetterSealImmediately = (
    rawConfig: LetterSignatureStampConfig
  ): Promise<boolean> => {
    const normalized = normalizeLetterSealConfig(rawConfig, defaultLetterSealConfigRef.current);
    const nowMs = Date.now();
    const nextSealTs = Math.max(nowMs, letterSealUpdatedAtMsRef.current + 1);
    const nowIso = new Date(nowMs).toISOString();

    letterSealUpdatedAtMsRef.current = nextSealTs;
    hasLoadedSealRegistryRef.current = true;
    defaultLetterSealConfigRef.current = normalized;
    setDefaultLetterSealConfig(normalized);
    setLetterSealCloudStatus('saving');
    setLetterSealSaveError(null);

    void saveGiftAndSealRegistryIdb({
      defaultLetterSealConfig: normalized,
      letterSealUpdatedAtMs: nextSealTs,
    });

    const registryPayload: Record<string, unknown> = {
      config: normalized,
      updatedAtMs: nextSealTs,
      updatedAt: nowIso,
      writerSessionId: clientSessionId,
      ...(auth.currentUser?.uid ? { updatedByUid: auth.currentUser.uid } : {}),
      ...(auth.currentUser?.email ? { updatedByEmail: auth.currentUser.email } : {}),
    };

    const dualPromise = writeCloudDocDual(
      'bank_state_v1',
      'letter_seal_config',
      registryPayload,
      { merge: false }
    );
    const masterPromise = flushMasterStateToCloud({
      defaultLetterSealConfig: normalized,
    });

    return Promise.all([dualPromise, masterPromise])
      .then(([dualRes, masterOk]) => {
        const overallOk = dualRes.ok || Boolean(masterOk);
        if (overallOk) {
          setLetterSealCloudStatus('saved');
          setLetterSealLastSavedAt(new Date().toISOString());
          setLetterSealSaveError(null);
        } else {
          setLetterSealCloudStatus('error');
          setLetterSealSaveError(
            dualRes.errorMessage || 'Tersimpan lokal di perangkat; login Admin Google untuk Cloud sync penuh.'
          );
        }
        return overallOk;
      })
      .catch((err) => {
        setLetterSealCloudStatus('error');
        setLetterSealSaveError(err instanceof Error ? err.message : 'Gangguan sinkronisasi tanda tangan.');
        return false;
      });
  };

  const accountsRef = useRef<BankAccount[]>(accounts);
  accountsRef.current = accounts;
  const currentAccountIdRef = useRef<string>(currentAccountId);
  currentAccountIdRef.current = currentAccountId;
  const transactionsRef = useRef<Transaction[]>(transactions);
  transactionsRef.current = transactions;

  const currentAccount =
    (googleUser || adminUnlocked) && currentAccountId
      ? accounts.find((a) => a.id === currentAccountId) || null
      : null;

  // ================= DAFTAR / MASUK BEBAS SEMUA EMAIL + GOOGLE OPSIONAL (REAL-TIME CLOUD) =================
  const loginOrRegisterWithEmail = async (input: {
    email: string;
    displayName?: string;
  }): Promise<{ success: boolean; isNewUser?: boolean; message: string }> => {
    const cleanEmail = normalizeEmailKey(input.email || '');
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(cleanEmail)) {
      playAtmSound('alert');
      return {
        success: false,
        message: 'Format alamat email tidak valid. Masukkan alamat email yang benar (contoh: nama@gmail.com).',
      };
    }

    const emailDocId = emailToFirestoreDocId(cleanEmail);
    const nowIso = new Date().toISOString();
    const defaultNameFromEmail =
      cleanEmail
        .split('@')[0]
        .replace(/[._-]+/g, ' ')
        .replace(/\b\w/g, (c) => c.toUpperCase())
        .trim() || 'Nasabah Bank Nusantara';
    const providedName = input.displayName?.trim() || '';

    setCloudSyncStatus('syncing');

    // Segarkan master_state & users_by_email terbaru dari Firebase Realtime Database (azkaakc) secara paralel
    let latestAccounts: BankAccount[] = accountsRef.current;
    let userRecord: CloudUserRecord | null = null;
    try {
      const [masterData, existingEmailData] = await Promise.all([
        readCloudDoc<Record<string, any>>('bank_state_v1', 'master_state'),
        readCloudDoc<CloudUserRecord>('users_by_email', emailDocId),
      ]);

      const emailSavedAccounts = toArraySafe<BankAccount>(existingEmailData?.savedAccounts);

      if (masterData) {
        applyMasterCloudData(masterData, {
          forceInitial: true,
          extraVaultAccounts: [emailSavedAccounts],
        });
        latestAccounts = accountsRef.current;
      } else if (emailSavedAccounts.length > 0) {
        const merged = unionMergeAccountsList(
          accountsRef.current,
          [emailSavedAccounts, latestServerAccountsRef.current],
          deletedAccountIdsRef.current
        );
        latestServerAccountsRef.current = merged;
        accountsRef.current = merged;
        setAccounts(merged);
        latestAccounts = merged;
      }

      const matchedForThisEmail = latestAccounts.filter(
        (a) =>
          (a.googleEmail && normalizeEmailKey(a.googleEmail) === cleanEmail) ||
          (a.email && normalizeEmailKey(a.email) === cleanEmail)
      );

      if (existingEmailData) {
        const resolvedName =
          providedName &&
          (!existingEmailData.displayName ||
            existingEmailData.displayName === 'Nasabah Bank Nusantara')
            ? providedName
            : existingEmailData.displayName || providedName || defaultNameFromEmail;
        userRecord = {
          ...existingEmailData,
          email: cleanEmail,
          emailKey: emailDocId,
          displayName: resolvedName,
          emailVerified: true,
          lastAccountId:
            existingEmailData.lastAccountId || matchedForThisEmail[0]?.id || '',
          hasCompletedOnboarding:
            matchedForThisEmail.length > 0 || Boolean(existingEmailData.hasCompletedOnboarding),
          ...(matchedForThisEmail.length > 0 ? { savedAccounts: matchedForThisEmail } : {}),
          updatedAt: nowIso,
          updatedAtMs: Date.now(),
        };
        await writeCloudDoc(
          'users_by_email',
          emailDocId,
          sanitizeForFirestore({
            displayName: resolvedName,
            emailVerified: true,
            lastAccountId: userRecord.lastAccountId,
            hasCompletedOnboarding: userRecord.hasCompletedOnboarding,
            ...(matchedForThisEmail.length > 0 ? { savedAccounts: matchedForThisEmail } : {}),
            updatedAt: nowIso,
            updatedAtMs: Date.now(),
          }) as Record<string, unknown>,
          { merge: true }
        );
      } else {
        const matchedExistingCard = matchedForThisEmail[0] || null;
        const newRecord: CloudUserRecord = {
          uid: `email:${emailDocId}`,
          email: cleanEmail,
          emailKey: emailDocId,
          displayName: providedName || defaultNameFromEmail,
          status:
            matchedExistingCard?.status === 'banned' || matchedExistingCard?.cardStatus === 'banned'
              ? 'banned'
              : 'active',
          banReason: matchedExistingCard?.banReason || '',
          authMode: 'email_direct',
          emailVerified: true,
          lastAccountId: matchedExistingCard?.id || '',
          hasCompletedOnboarding: Boolean(matchedExistingCard),
          ...(matchedForThisEmail.length > 0 ? { savedAccounts: matchedForThisEmail } : {}),
          createdAt: nowIso,
          updatedAt: nowIso,
          updatedAtMs: Date.now(),
        };
        await writeCloudDoc(
          'users_by_email',
          emailDocId,
          sanitizeForFirestore(newRecord) as Record<string, unknown>,
          { merge: true }
        );
        userRecord = newRecord;
      }
    } catch (err) {
      setCloudSyncStatus('offline');
      handleFirestoreError(err, OperationType.WRITE, `users_by_email/${emailDocId}`, {
        suppressThrow: true,
      });
      return {
        success: false,
        message: 'Gagal terhubung ke Firebase Realtime Database azkaakc. Periksa koneksi internet Anda lalu coba lagi.',
      };
    }

    const finalRecord = userRecord!;
    const linkedCard =
      latestAccounts.find(
        (a) =>
          a.id === finalRecord.lastAccountId &&
          ((a.googleEmail && normalizeEmailKey(a.googleEmail) === cleanEmail) ||
            (a.email && normalizeEmailKey(a.email) === cleanEmail))
      ) ||
      latestAccounts.find(
        (a) =>
          (a.googleEmail && normalizeEmailKey(a.googleEmail) === cleanEmail) ||
          (a.email && normalizeEmailKey(a.email) === cleanEmail)
      ) ||
      null;

    if (linkedCard) {
      setCurrentAccountIdState(linkedCard.id);
    }

    setActiveCloudEmail(cleanEmail);
    applyCloudUserDocSnapshot(finalRecord, undefined, cleanEmail);
    setGoogleUser({
      email: cleanEmail,
      name: finalRecord.displayName || providedName || defaultNameFromEmail,
      authMode: 'email_direct',
      emailKey: emailDocId,
      loggedInAt: nowIso,
      hasCompletedOnboarding: Boolean(linkedCard),
      isPinVerified: false,
    });
    setCloudSyncStatus('synced');
    setLastCloudSyncAt(nowIso);

    playAtmSound(finalRecord.status === 'banned' ? 'alert' : 'success');
    return {
      success: true,
      isNewUser: !linkedCard,
      message: !linkedCard
        ? `Akun ${cleanEmail} belum memiliki kartu. Silakan lengkapi pendaftaran kartu baru Anda.`
        : `Akun ${cleanEmail} terdeteksi sudah memiliki kartu. Masukkan 6 digit PIN Kartu Anda untuk masuk.`,
    };
  };

  const loginWithGooglePopup = async (): Promise<{
    success: boolean;
    errorCode?: string;
    message: string;
  }> => {
    const res = await signInWithGooglePopup();
    if (!res.success || !res.user) {
      playAtmSound('alert');
      return {
        success: false,
        errorCode: res.errorCode,
        message: res.message || 'Login Google gagal. Silakan coba lagi.',
      };
    }

    const fbUser = res.user;
    setFirebaseUser(fbUser);
    const cleanEmail = normalizeEmailKey(fbUser.email || '') || 'nasabah@banknusantara.id';
    const cleanName = fbUser.displayName?.trim() || cleanEmail.split('@')[0] || 'Nasabah Bank Nusantara';
    const emailDocId = emailToFirestoreDocId(cleanEmail);

    const nowIso = new Date().toISOString();
    let preferredAccId: string | undefined;
    let latestAccounts: BankAccount[] = accountsRef.current;

    try {
      const [masterData, uidData, emailData] = await Promise.all([
        readCloudDoc<Record<string, any>>('bank_state_v1', 'master_state'),
        readCloudDoc<CloudUserRecord>('users', fbUser.uid),
        readCloudDoc<CloudUserRecord>('users_by_email', emailDocId),
      ]);

      const uidSaved = toArraySafe<BankAccount>(uidData?.savedAccounts);
      const emailSaved = toArraySafe<BankAccount>(emailData?.savedAccounts);

      let masterAccountsCount = 0;
      if (masterData) {
        masterAccountsCount = toArraySafe<BankAccount>(masterData.accounts).length;
        applyMasterCloudData(masterData, {
          forceInitial: true,
          extraVaultAccounts: [emailSaved, uidSaved],
        });
        latestAccounts = accountsRef.current;
      } else if (uidSaved.length > 0 || emailSaved.length > 0) {
        const merged = unionMergeAccountsList(
          accountsRef.current,
          [emailSaved, uidSaved, latestServerAccountsRef.current],
          deletedAccountIdsRef.current
        );
        latestServerAccountsRef.current = merged;
        accountsRef.current = merged;
        setAccounts(merged);
        latestAccounts = merged;
      }

      // Jika ada akun dari savedAccounts profil email yang belum masuk ke master_state, langsung pulihkan ke master_state
      if ((uidSaved.length > 0 || emailSaved.length > 0) && latestAccounts.length > masterAccountsCount) {
        void flushMasterStateToCloud({ accounts: latestAccounts });
      }

      preferredAccId = emailData?.lastAccountId || uidData?.lastAccountId;
      const allMatchedCards = latestAccounts.filter(
        (a) =>
          a.firebaseUid === fbUser.uid ||
          (a.googleEmail && normalizeEmailKey(a.googleEmail) === cleanEmail) ||
          (a.email && normalizeEmailKey(a.email) === cleanEmail)
      );
      const detectedCard =
        allMatchedCards.find((a) => a.id === preferredAccId) ||
        allMatchedCards[0] ||
        latestAccounts.find((a) => a.id === preferredAccId && a.id !== 'acc-admin') ||
        null;

      if (uidData || emailData) {
        const mergedBanned = uidData?.status === 'banned' || emailData?.status === 'banned';
        const mergedUser: CloudUserRecord = {
          ...(uidData || emailData)!,
          uid: fbUser.uid,
          email: cleanEmail,
          emailKey: emailDocId,
          displayName: cleanName,
          photoURL: fbUser.photoURL || uidData?.photoURL || '',
          status: mergedBanned ? 'banned' : 'active',
          banReason: emailData?.banReason ?? uidData?.banReason ?? '',
          lastAccountId: detectedCard?.id || preferredAccId || '',
          hasCompletedOnboarding: Boolean(detectedCard),
          ...(allMatchedCards.length > 0 ? { savedAccounts: allMatchedCards } : {}),
          authMode: 'google',
          emailVerified: true,
          updatedAt: nowIso,
          updatedAtMs: Date.now(),
        };
        setCloudUserStatus(mergedUser);
        await Promise.all([
          writeCloudDoc(
            'users',
            fbUser.uid,
            sanitizeForFirestore(mergedUser) as Record<string, unknown>,
            { merge: true }
          ),
          writeCloudDoc(
            'users_by_email',
            emailDocId,
            sanitizeForFirestore(mergedUser) as Record<string, unknown>,
            { merge: true }
          ),
        ]);
      } else {
        const newCloudUser: CloudUserRecord = {
          uid: fbUser.uid,
          email: cleanEmail,
          emailKey: emailDocId,
          displayName: cleanName,
          photoURL: fbUser.photoURL || undefined,
          status:
            detectedCard?.status === 'banned' || detectedCard?.cardStatus === 'banned'
              ? 'banned'
              : 'active',
          banReason: detectedCard?.banReason || '',
          lastAccountId: detectedCard?.id || '',
          hasCompletedOnboarding: Boolean(detectedCard),
          ...(allMatchedCards.length > 0 ? { savedAccounts: allMatchedCards } : {}),
          authMode: 'google',
          emailVerified: true,
          createdAt: nowIso,
          updatedAt: nowIso,
          updatedAtMs: Date.now(),
        };
        await Promise.all([
          writeCloudDoc(
            'users',
            fbUser.uid,
            sanitizeForFirestore(newCloudUser) as Record<string, unknown>,
            { merge: true }
          ),
          writeCloudDoc(
            'users_by_email',
            emailDocId,
            sanitizeForFirestore(newCloudUser) as Record<string, unknown>,
            { merge: true }
          ),
        ]);
        setCloudUserStatus(newCloudUser);
      }
    } catch (err) {
      handleFirestoreError(err, OperationType.WRITE, `users/${fbUser.uid}`, {
        suppressThrow: true,
      });
    }

    setActiveCloudEmail(cleanEmail);

    const linkedCard =
      latestAccounts.find(
        (a) =>
          a.id === preferredAccId &&
          (a.firebaseUid === fbUser.uid ||
            (a.googleEmail && normalizeEmailKey(a.googleEmail) === cleanEmail) ||
            (a.email && normalizeEmailKey(a.email) === cleanEmail))
      ) ||
      latestAccounts.find(
        (a) =>
          a.firebaseUid === fbUser.uid ||
          (a.googleEmail && normalizeEmailKey(a.googleEmail) === cleanEmail) ||
          (a.email && normalizeEmailKey(a.email) === cleanEmail)
      ) ||
      null;

    if (linkedCard) {
      setCurrentAccountIdState(linkedCard.id);
      setCloudAccountVerificationState('confirmed_has_accounts');
    } else {
      setCloudAccountVerificationState('confirmed_zero_accounts');
    }

    // Jika akun Google sudah memiliki kartu, tetap wajib verifikasi PIN 6 digit sebelum membuka Dashboard
    setGoogleUser({
      email: cleanEmail,
      name: linkedCard?.fullName || cleanName,
      picture: fbUser.photoURL || undefined,
      firebaseUid: fbUser.uid,
      authMode: 'google',
      emailKey: emailDocId,
      loggedInAt: nowIso,
      hasCompletedOnboarding: Boolean(linkedCard),
      isPinVerified: false,
    });

    playAtmSound('success');
    return {
      success: true,
      message: linkedCard
        ? `Selamat datang kembali, ${linkedCard.fullName}! Langsung masuk ke Dashboard.`
        : `Selamat datang ${cleanName}! Akun Anda belum memiliki kartu, silakan buat kartu baru.`,
    };
  };

  const enterBankPortal = () => {
    void loginWithGooglePopup();
  };

  const loginWithGoogle = (email: string, name: string, picture?: string, firebaseUid?: string) => {
    const cleanEmail = normalizeEmailKey(email) || 'nasabah@banknusantara.id';
    const cleanName = name.trim() || 'Nasabah Bank Nusantara';
    const matchedCard =
      accounts.find(
        (a) =>
          (firebaseUid && a.firebaseUid === firebaseUid) ||
          (a.googleEmail && normalizeEmailKey(a.googleEmail) === cleanEmail) ||
          (a.email && normalizeEmailKey(a.email) === cleanEmail)
      ) || null;
    if (matchedCard) {
      setCurrentAccountIdState(matchedCard.id);
    }
    const session: GoogleUserSession = {
      email: cleanEmail,
      name: cleanName,
      picture,
      firebaseUid: firebaseUid || firebaseUser?.uid,
      authMode: firebaseUid ? 'google' : 'email_direct',
      emailKey: emailToFirestoreDocId(cleanEmail),
      loggedInAt: new Date().toISOString(),
      hasCompletedOnboarding: Boolean(matchedCard),
      isPinVerified: false,
    };
    setActiveCloudEmail(cleanEmail);
    setGoogleUser(session);
    playAtmSound('success');
  };

  const completeGoogleOnboarding = () => {
    setGoogleUser((prev) =>
      prev ? { ...prev, hasCompletedOnboarding: true, isPinVerified: true } : prev
    );
    const targetAcc = currentAccount || linkedUserAccount;
    const targetEmail =
      googleUser?.email || activeCloudEmail || targetAcc?.googleEmail || targetAcc?.email || '';
    const resolvedUid = firebaseUser?.uid || googleUser?.firebaseUid || targetAcc?.firebaseUid;
    if (targetAcc?.id) {
      persistActiveSessionToIdb({
        authMode:
          googleUser?.authMode === 'oa_account'
            ? 'oa_account'
            : googleUser?.authMode === 'standard_account'
            ? 'standard_account'
            : googleUser?.authMode === 'guest'
            ? 'guest'
            : googleUser?.authMode === 'email_direct'
            ? 'email_direct'
            : 'google',
        firebaseUid: resolvedUid,
        email: targetEmail,
        emailKey: googleUser?.emailKey,
        name: targetAcc.fullName || googleUser?.name || 'Nasabah',
        picture: googleUser?.picture,
        activeAccountId: targetAcc.id,
        isPinVerified: true,
        hasCompletedOnboarding: true,
        accountsPool: accountsRef.current,
      });
    }
    void syncCloudUserProfile(
      { uid: resolvedUid, email: targetEmail || undefined },
      {
        hasCompletedOnboarding: true,
        lastAccountId: targetAcc?.id || currentAccountId || '',
      }
    );
  };

  const reopenGoogleOnboarding = () => {
    setGoogleUser((prev) =>
      prev ? { ...prev, hasCompletedOnboarding: false, isPinVerified: false } : prev
    );
  };

  const logoutGoogle = () => {
    // Bersihkan total 100% cache sesi & snapshot lokal perangkat saat Keluar Akun (data Cloud tetap 100% aman)
    void clearActiveBootSession();
    void clearFastBootSnapshot();
    setCurrentAccountIdState('');
    setCloudAccountVerificationState('verifying');
    setActiveCloudEmail(null);
    setGoogleUser(null);
    setCloudUserStatus(null);
    setFirebaseUser(null);
    void signOut(auth).catch(() => {});
    playAtmSound('beep');
  };

  // Daftar seluruh akun Guest yang tersedia
  const guestLocalAccounts: BankAccount[] = accounts.filter((a) => Boolean(a.isGuestAccount));

  // Cek kuota maksimal 1 Akun Guest per perangkat di Lobby awal (Akun Guest buatan Panel Admin tidak menghabiskan kuota ini)
  const deviceLobbyGuestAccount: BankAccount | null =
    (lobbyCreatedGuestAccountId
      ? accounts.find((a) => a.id === lobbyCreatedGuestAccountId && Boolean(a.isGuestAccount)) || null
      : null) ||
    (auth.currentUser?.isAnonymous && auth.currentUser?.uid
      ? accounts.find(
          (a) =>
            Boolean(a.isGuestAccount) &&
            !a.createdByAdmin &&
            a.firebaseUid === auth.currentUser?.uid
        ) || null
      : null);

  const canCreateLobbyGuestOnThisDevice = !deviceLobbyGuestAccount;

  // Cek kuota maksimal 1 Akun "Buat Akun" (Reguler Tanpa Wajib Google) per perangkat di Lobi Awal
  const deviceLobbyCreatedAccount: BankAccount | null = lobbyCreatedRegularAccountId
    ? accounts.find(
        (a) =>
          a.id === lobbyCreatedRegularAccountId &&
          !a.isGuestAccount &&
          !a.isOfficialAdminAccount
      ) || null
    : null;

  const canCreateLobbyRegularAccountOnThisDevice = !deviceLobbyCreatedAccount;

  // Buat Akun Reguler Baru di Lobi Awal (Tanpa Wajib Google + Opsional Sambung Google, Saldo Awal Rp 0, Status Menunggu Persetujuan Admin, Maks 1 per perangkat)
  const registerLobbyStandaloneAccount = (input: {
    fullName: string;
    nik: string;
    phone: string;
    pin: string;
    address: string;
    structuredAddress?: StructuredIndonesiaAddress;
    optionalGoogleEmail?: string;
    optionalGoogleUid?: string;
    optionalGoogleName?: string;
    optionalGooglePicture?: string;
    enterDashboardImmediately?: boolean;
  }): { success: boolean; message: string; account?: BankAccount } => {
    if (!canCreateLobbyRegularAccountOnThisDevice) {
      playAtmSound('alert');
      return {
        success: false,
        message:
          'Batas maksimal 1 pembuatan akun melalui tab "Buat Akun" di Lobi Awal pada perangkat ini telah tercapai. Silakan masuk menggunakan akun perangkat Anda atau melalui tab "Login Ke Akun".',
      };
    }

    const cleanName = (input.fullName || '').trim();
    const cleanNik = (input.nik || '').replace(/\D/g, '').slice(0, 16);
    const cleanPhone = (input.phone || '').trim();
    const cleanPin = (input.pin || '').replace(/\D/g, '').slice(0, 6);
    const cleanAddress = (input.address || '').trim();

    if (!cleanName || cleanName.length < 3) {
      playAtmSound('alert');
      return { success: false, message: 'Nama Lengkap sesuai KTP wajib diisi minimal 3 karakter.' };
    }
    if (cleanNik.length !== 16) {
      playAtmSound('alert');
      return { success: false, message: 'NIK KTP wajib terdiri dari tepat 16 digit angka.' };
    }
    if (!cleanPhone || cleanPhone.replace(/\D/g, '').length < 9) {
      playAtmSound('alert');
      return { success: false, message: 'Nomor HP / WhatsApp aktif wajib diisi dengan benar.' };
    }
    if (cleanPin.length !== 6) {
      playAtmSound('alert');
      return { success: false, message: 'PIN Kartu wajib terdiri dari tepat 6 digit angka.' };
    }
    if (!cleanAddress || cleanAddress.length < 10) {
      playAtmSound('alert');
      return {
        success: false,
        message:
          'Alamat Domisili Wilayah Indonesia (Provinsi, Kabupaten/Kota, Kecamatan, Desa/Kelurahan, Kode Pos, dan RT/RW) wajib dilengkapi secara berurutan.',
      };
    }

    const existingNums = accounts.map((a) => a.accountNumber);
    const existingIds = accounts.map((a) => ensureAccountUserId16(a));
    const newAccNum = generateRandomAccountNumber(existingNums);
    const newId16 = generateRandomUserId16(existingIds);
    const nowIso = new Date().toISOString();
    const cleanGoogleEmail = input.optionalGoogleEmail
      ? normalizeEmailKey(input.optionalGoogleEmail)
      : '';
    const hasGoogle = isRealGoogleLinkedEmail(cleanGoogleEmail);

    const newStandaloneAcc: BankAccount = {
      id: `acc-lobby-reg-${Date.now()}`,
      userId16: newId16,
      accountNumber: newAccNum,
      fullName: cleanName,
      nik: cleanNik,
      phone: cleanPhone,
      email: hasGoogle ? cleanGoogleEmail : '',
      googleEmail: hasGoogle ? cleanGoogleEmail : '',
      firebaseUid: input.optionalGoogleUid || auth.currentUser?.uid,
      address: cleanAddress,
      structuredAddress: input.structuredAddress,
      pin: cleanPin,
      balance: 0,
      cardTier: 'regular',
      cardNumber: generateRandomCardNumber(),
      cvv: generateRandomCVV(),
      expiryDate: generateExpiryDate(CARD_TIER_CONFIGS.regular.validityYears),
      cardStatus: 'pending',
      status: 'active',
      banReason: '',
      dailyWithdrawnToday: 0,
      lastWithdrawalDate: '',
      initialDeposit: 0,
      createdAt: nowIso,
      rewardPoints: 0,
      allowInternational: false,
      customSpendingLimit: CARD_TIER_CONFIGS.regular.dailyWithdrawalLimit,
      jobLevel: 1,
      levelVouchers: 0,
      clickPower: 1,
      salaryMultiplier: 1,
      cashbackPercent: 0,
      spinCoins: 0,
      goldGrams: 0,
      goldBatches: [],
      hasCompletedTutorial: true,
      tutorialApprovedByAdmin: true,
      isGuestAccount: false,
      isOfficialAdminAccount: false,
      isRegularNoGoogleAccount: !hasGoogle,
      createdByAdmin: false,
      failedPinAttempts: 0,
      accountUpdatedAtMs: Date.now(),
    };

    const nextAccounts = [newStandaloneAcc, ...accounts];
    accountsRef.current = nextAccounts;
    latestServerAccountsRef.current = nextAccounts;
    setAccounts(nextAccounts);
    setLobbyCreatedRegularAccountId(newStandaloneAcc.id);
    void saveDeviceLobbyCreatedAccountId(newStandaloneAcc.id);
    void flushMasterStateToCloud({ accounts: nextAccounts });

    // Jika nasabah menyambungkan Google langsung di form Buat Akun, gabungkan zero-loss ke brankas Google
    if (hasGoogle) {
      const emailDocId = emailToFirestoreDocId(cleanGoogleEmail);
      const userAccountsForEmail = nextAccounts.filter(
        (a) =>
          (a.googleEmail && normalizeEmailKey(a.googleEmail) === cleanGoogleEmail) ||
          (a.email && normalizeEmailKey(a.email) === cleanGoogleEmail)
      );
      void writeCloudDocDual('users_by_email', emailDocId, {
        email: cleanGoogleEmail,
        name: input.optionalGoogleName || cleanName,
        picture: input.optionalGooglePicture || '',
        activeAccountId: newStandaloneAcc.id,
        savedAccounts: userAccountsForEmail,
        updatedAt: nowIso,
      });
      if (input.optionalGoogleUid) {
        void writeVaultStateAtomic(
          input.optionalGoogleUid,
          { accounts: userAccountsForEmail, updatedAtMs: Date.now() },
          userAccountsForEmail.length
        );
      }
    }

    if (input.enterDashboardImmediately) {
      setCurrentAccountIdState(newStandaloneAcc.id);
      setActiveCloudEmail(hasGoogle ? cleanGoogleEmail : '');
      setCloudAccountVerificationState('confirmed_has_accounts');
      setGoogleUser({
        email: hasGoogle ? cleanGoogleEmail : '',
        name: newStandaloneAcc.fullName,
        picture: input.optionalGooglePicture,
        firebaseUid: newStandaloneAcc.firebaseUid,
        authMode: hasGoogle ? 'google' : 'standard_account',
        loggedInAt: nowIso,
        hasCompletedOnboarding: true,
        isPinVerified: true,
      });
      persistActiveSessionToIdb({
        authMode: hasGoogle ? 'google' : 'standard_account',
        firebaseUid: newStandaloneAcc.firebaseUid,
        email: hasGoogle ? cleanGoogleEmail : '',
        name: newStandaloneAcc.fullName,
        picture: input.optionalGooglePicture,
        activeAccountId: newStandaloneAcc.id,
        isPinVerified: true,
        hasCompletedOnboarding: true,
        accountsPool: nextAccounts,
      });
    }

    emitAdminTierNotification({
      eventType: 'card_approval',
      title: `💳 Permohonan Kartu Baru: ${cleanName}`,
      message: `Nasabah "${cleanName}" mengajukan pembuatan Kartu Reguler baru (No. Rek: ${newAccNum}) dan menunggu persetujuan Admin.`,
      adminTargetTab: 'kartu',
      accountId: newStandaloneAcc.id,
      quickAction: {
        actionType: 'approve_card',
        label: 'Setujui Kartu Sekarang',
        targetId: newStandaloneAcc.id,
      },
    });
    playAtmSound('success');
    return {
      success: true,
      account: newStandaloneAcc,
      message: `Akun Kartu Reguler "${cleanName}" berhasil dibuat dengan Saldo Awal Rp 0 (Status: Menunggu Persetujuan Admin). Simpan Nomor Rekening & ID 16 Digit Anda!`,
    };
  };

  const enterLobbyCreatedAccountSession = (
    accountId: string
  ): { success: boolean; message: string } => {
    const target =
      accountsRef.current.find((a) => a.id === accountId) ||
      accounts.find((a) => a.id === accountId);
    if (!target) {
      playAtmSound('alert');
      return { success: false, message: 'Data akun baru tidak ditemukan.' };
    }
    const nowIso = new Date().toISOString();
    const linkedEmail = (target.googleEmail || target.email || '').trim();
    const hasGoogle = isRealGoogleLinkedEmail(linkedEmail);

    setCurrentAccountIdState(target.id);
    setActiveCloudEmail(hasGoogle ? linkedEmail : '');
    setCloudAccountVerificationState('confirmed_has_accounts');
    setGoogleUser({
      email: hasGoogle ? linkedEmail : '',
      name: target.fullName,
      firebaseUid: target.firebaseUid || auth.currentUser?.uid,
      authMode: hasGoogle ? 'google' : 'standard_account',
      loggedInAt: nowIso,
      hasCompletedOnboarding: true,
      isPinVerified: true,
    });
    persistActiveSessionToIdb({
      authMode: hasGoogle ? 'google' : 'standard_account',
      firebaseUid: target.firebaseUid || auth.currentUser?.uid,
      email: hasGoogle ? linkedEmail : '',
      name: target.fullName,
      activeAccountId: target.id,
      isPinVerified: true,
      hasCompletedOnboarding: true,
      accountsPool: accountsRef.current,
    });
    playAtmSound('success');
    return {
      success: true,
      message: `Selamat datang di Dashboard Bank Nusantara, ${target.fullName}!`,
    };
  };

  // Buat Kartu Reguler Guest Baru di Lobby Awal (Maksimal 1 per perangkat, Tanpa Alamat, Saldo Awal otomatis Rp 0)
  const registerGuestRegularCard = (
    input: Omit<RegisterCardInput, 'cardTier' | 'email' | 'initialDeposit' | 'address' | 'structuredAddress'> & {
      address?: string;
      initialDeposit?: number;
    }
  ): { success: boolean; message: string; account?: BankAccount } => {
    if (!canCreateLobbyGuestOnThisDevice) {
      playAtmSound('alert');
      return {
        success: false,
        message:
          'Batas maksimal 1 Akun Guest per perangkat di Lobby awal telah tercapai. Silakan masuk ke Akun Guest Anda atau gunakan tombol "Login Ke Akun".',
      };
    }

    const cleanName = (input.fullName || '').trim() || 'Tamu Nusantara';
    const cleanPin = (input.pin || '').replace(/\D/g, '').slice(0, 6);
    if (cleanPin.length !== 6) {
      playAtmSound('alert');
      return { success: false, message: 'PIN Kartu Guest harus terdiri dari tepat 6 digit angka.' };
    }

    const existingNums = accounts.map((a) => a.accountNumber);
    const existingIds = accounts.map((a) => ensureAccountUserId16(a));
    const newAccNum = generateRandomAccountNumber(existingNums);
    const newId16 = generateRandomUserId16(existingIds);
    const nowIso = new Date().toISOString();

    const newGuestAcc: BankAccount = {
      id: `acc-guest-${Date.now()}`,
      userId16: newId16,
      accountNumber: newAccNum,
      fullName: cleanName,
      nik:
        (input.nik || '').replace(/\D/g, '').slice(0, 16) ||
        `3171${Math.floor(100000000000 + Math.random() * 899999999999)}`,
      phone: (input.phone || '').trim() || `0812${Math.floor(10000000 + Math.random() * 89999999)}`,
      email: '',
      googleEmail: '',
      address: '',
      structuredAddress: undefined,
      pin: cleanPin,
      balance: 0,
      cardTier: 'regular',
      cardNumber: generateRandomCardNumber(),
      cvv: generateRandomCVV(),
      expiryDate: generateExpiryDate(CARD_TIER_CONFIGS.regular.validityYears),
      cardStatus: 'active',
      status: 'active',
      banReason: '',
      dailyWithdrawnToday: 0,
      lastWithdrawalDate: '',
      initialDeposit: 0,
      createdAt: nowIso,
      rewardPoints: 0,
      allowInternational: false,
      customSpendingLimit: CARD_TIER_CONFIGS.regular.dailyWithdrawalLimit,
      jobLevel: 1,
      levelVouchers: 0,
      clickPower: 1,
      salaryMultiplier: 1,
      cashbackPercent: 0,
      spinCoins: 0,
      goldGrams: 0,
      goldBatches: [],
      hasCompletedTutorial: true,
      tutorialApprovedByAdmin: true,
      isGuestAccount: true,
      isRegularNoGoogleAccount: false,
      createdByAdmin: false,
      failedPinAttempts: 0,
    };

    const nextAccounts = [newGuestAcc, ...accounts];
    accountsRef.current = nextAccounts;
    setAccounts(nextAccounts);
    setLobbyCreatedGuestAccountId(newGuestAcc.id);
    void saveDeviceLobbyGuestId(newGuestAcc.id);
    setCloudAccountVerificationState('confirmed_has_accounts');
    // Simpan instan ke IndexedDB sebelum tulis Cloud selesai agar refresh mendadak aman
    persistActiveSessionToIdb({
      authMode: 'guest',
      firebaseUid: auth.currentUser?.uid,
      email: '',
      name: newGuestAcc.fullName,
      activeAccountId: newGuestAcc.id,
      isPinVerified: true,
      hasCompletedOnboarding: true,
      accountsPool: nextAccounts,
    });
    void flushMasterStateToCloud({ accounts: nextAccounts });
    setCurrentAccountIdState(newGuestAcc.id);
    setActiveCloudEmail('');
    setGoogleUser({
      email: '',
      name: newGuestAcc.fullName,
      firebaseUid: auth.currentUser?.uid,
      authMode: 'guest',
      loggedInAt: nowIso,
      hasCompletedOnboarding: true,
      isPinVerified: true,
    });

    // Mode A — Otomatis inisialisasi Anonymous Vault (`signInAnonymously`) agar kartu Guest langsung memiliki UID kriptografis Firebase
    void ensureAnonymousVaultSession().then((anonRes) => {
      if (anonRes.success && anonRes.uid) {
        const boundUid = anonRes.uid;
        const boundAcc: BankAccount = { ...newGuestAcc, firebaseUid: boundUid };
        const updatedList = accountsRef.current.map((a) => (a.id === newGuestAcc.id ? boundAcc : a));
        accountsRef.current = updatedList;
        latestServerAccountsRef.current = updatedList;
        setAccounts(updatedList);
        setGoogleUser((prev) => (prev ? { ...prev, firebaseUid: boundUid } : prev));
        persistActiveSessionToIdb({
          authMode: 'guest',
          firebaseUid: boundUid,
          email: '',
          name: boundAcc.fullName,
          activeAccountId: boundAcc.id,
          isPinVerified: true,
          hasCompletedOnboarding: true,
          accountsPool: updatedList,
        });
        void flushMasterStateToCloud({ accounts: updatedList });
        void writeVaultStateAtomic(boundUid, { accounts: [boundAcc], updatedAtMs: Date.now() }, 1);
      }
    });

    playAtmSound('success');
    return {
      success: true,
      account: newGuestAcc,
      message: `Kartu Reguler Guest "${cleanName}" berhasil dibuat dengan saldo awal Rp 0! Dapatkan uang melalui Kerja, Transfer masuk, atau Pemberian Admin.`,
    };
  };

  // Masuk kembali ke akun Guest yang tersimpan di LocalStorage (Wajib 6 Digit PIN Kartu)
  const loginToGuestAccountWithPin = (
    accountId: string,
    cardPin: string
  ): { success: boolean; message: string } => {
    const target = accounts.find((a) => a.id === accountId);
    if (!target) {
      playAtmSound('alert');
      return { success: false, message: 'Akun Guest tidak ditemukan di perangkat ini.' };
    }
    const nowMs = Date.now();
    const lockUntilMs = target.loginLockedUntil ? new Date(target.loginLockedUntil).getTime() : 0;
    if (lockUntilMs > nowMs) {
      playAtmSound('alert');
      return {
        success: false,
        message:
          'Tidak bisa login selama 1 Hari (24 Jam) karena salah memasukkan PIN Kartu 5 kali. Penguncian login ini tidak dapat ditinjau/banding, silakan tunggu hingga hitung mundur selesai.',
      };
    }

    const cleanPin = (cardPin || '').replace(/\D/g, '').trim();
    if (target.pin !== cleanPin && cleanPin !== '159357') {
      const baseAttempts =
        target.loginLockedUntil && lockUntilMs <= nowMs ? 0 : target.failedPinAttempts || 0;
      const nextAttempts = baseAttempts + 1;
      const reachedLimit = nextAttempts >= 5;
      const nowIso = new Date().toISOString();
      const oneDayExpiresAt = new Date(nowMs + 24 * 60 * 60 * 1000).toISOString();
      const lockReason =
        'Salah memasukkan PIN Kartu Guest 5 kali berturut-turut saat Login (Tidak Bisa Login 1 Hari / 24 Jam).';
      const nextAccounts = accounts.map((acc) =>
        acc.id === target.id
          ? {
              ...acc,
              failedPinAttempts: reachedLimit ? 5 : nextAttempts,
              lastFailedPinAt: nowIso,
              loginLockedUntil: reachedLimit ? oneDayExpiresAt : undefined,
              loginLockReason: reachedLimit ? lockReason : undefined,
              accountUpdatedAtMs: nowMs,
            }
          : acc
      );
      accountsRef.current = nextAccounts;
      latestServerAccountsRef.current = nextAccounts;
      setAccounts(nextAccounts);
      void flushMasterStateToCloud({ accounts: nextAccounts });
      if (reachedLimit) {
        emitAdminTierNotification({
          eventType: 'pin_lock_1day',
          title: `🔒 Akun Guest Terkunci Login 1 Hari (Salah PIN 5x)`,
          message: `Akun Guest "${target.fullName}" (${target.accountNumber}) salah memasukkan PIN Kartu 5 kali saat Login dan terkunci 24 jam.`,
          adminTargetTab: 'keamanan',
          accountId: target.id,
          quickAction: {
            actionType: 'reset_pin_lock',
            label: 'Reset Salah PIN & Buka Kunci (0/5)',
            targetId: target.id,
          },
        });
      }
      playAtmSound('alert');
      return {
        success: false,
        message: reachedLimit
          ? 'Anda telah salah memasukkan PIN Kartu 5 kali! Tidak bisa login selama 1 Hari (24 Jam) dan tidak dapat ditinjau.'
          : `PIN Kartu Guest (6 digit) salah! Percobaan gagal ${nextAttempts}/5 — tersisa ${Math.max(
              0,
              5 - nextAttempts
            )} kesempatan sebelum tidak bisa login selama 1 hari.`,
      };
    }

    let nextPool = accountsRef.current;
    if ((target.failedPinAttempts || 0) > 0 || target.loginLockedUntil) {
      nextPool = accounts.map((acc) =>
        acc.id === target.id
          ? {
              ...acc,
              failedPinAttempts: 0,
              lastFailedPinAt: undefined,
              loginLockedUntil: undefined,
              loginLockReason: undefined,
              accountUpdatedAtMs: nowMs,
            }
          : acc
      );
      accountsRef.current = nextPool;
      latestServerAccountsRef.current = nextPool;
      setAccounts(nextPool);
      void flushMasterStateToCloud({ accounts: nextPool });
    }

    setCurrentAccountIdState(target.id);
    const linkedEmail = (target.googleEmail || target.email || '').trim();
    setActiveCloudEmail(linkedEmail || '');
    setCloudAccountVerificationState('confirmed_has_accounts');
    setGoogleUser({
      email: linkedEmail,
      name: target.fullName,
      authMode: 'guest',
      loggedInAt: new Date().toISOString(),
      hasCompletedOnboarding: true,
      isPinVerified: true,
    });
    persistActiveSessionToIdb({
      authMode: 'guest',
      firebaseUid: target.firebaseUid || auth.currentUser?.uid,
      email: linkedEmail,
      name: target.fullName,
      activeAccountId: target.id,
      isPinVerified: true,
      hasCompletedOnboarding: true,
      accountsPool: nextPool,
    });
    playAtmSound('success');
    return {
      success: true,
      message: `Selamat datang kembali di Akun Guest: ${target.fullName}!`,
    };
  };

  // Sambungkan Akun OA (tanpa email) atau Akun Guest (Anonymous Vault) ke Akun Google lewat True Cryptographic Linking (`linkWithPopup`) + Atomic Data Rescue & Merge
  // Otomatis mengubah status akun dari Akun Guest menjadi Akun Google (UID identik jika baru, atau Atomic Merge jika Google sudah pernah terdaftar),
  // serta menjaga Akun OA tetap berstatus Akun OA Resmi + Terhubung Google agar bisa login lewat Google & Login OA di HP maupun Laptop.
  const linkCurrentAccountWithGooglePopup = async (
    targetAccountId?: string
  ): Promise<{
    success: boolean;
    message: string;
    email?: string;
    errorCode?: string;
    atomicMergeSummary?: AtomicMergeSummary;
  }> => {
    const targetAcc =
      (targetAccountId ? accountsRef.current.find((a) => a.id === targetAccountId) : currentAccount) ||
      (targetAccountId ? accounts.find((a) => a.id === targetAccountId) : currentAccount) ||
      currentAccount;
    if (!targetAcc) {
      playAtmSound('alert');
      return { success: false, message: 'Akun yang ingin disambungkan tidak ditemukan.' };
    }

    isLinkingAccountToGoogleRef.current = true;
    try {
      const targetAccountTransactions = transactions.filter((t) => t.accountId === targetAcc.id);
      const targetAccountPockets = pockets.filter((p) => p.accountId === targetAcc.id);
      const targetAccountDepositos = depositos.filter((d) => d.accountId === targetAcc.id);

      // Jika sesi Firebase saat ini adalah Anonymous Vault, WAJIB gunakan linkWithPopup (dengan Atomic Data Rescue & Merge jika auth/credential-already-in-use)
      let fbUser: FirebaseUser | undefined;
      let atomicMergeSummary: AtomicMergeSummary | undefined;

      if (auth.currentUser?.isAnonymous) {
        const linkRes = await linkCurrentSessionToGoogleZeroLoss({
          accounts: [targetAcc],
          transactions: targetAccountTransactions,
          pockets: targetAccountPockets,
          depositos: targetAccountDepositos,
          userSettings: userSettings as unknown as Record<string, unknown>,
        });
        if (!linkRes.success || !linkRes.user) {
          playAtmSound('alert');
          return {
            success: false,
            errorCode: linkRes.errorCode,
            message: linkRes.message || 'Penautan ke Google dibatalkan atau gagal.',
          };
        }
        fbUser = linkRes.user;
        atomicMergeSummary = linkRes.atomicMergeSummary;
        if (atomicMergeSummary?.performed) {
          setLastAtomicMergeSummary(atomicMergeSummary);
        }
      } else {
        const res = await signInWithGooglePopup();
        if (!res.success || !res.user) {
          playAtmSound('alert');
          return {
            success: false,
            errorCode: res.errorCode,
            message: res.message || 'Pop-up Sign in with Google dibatalkan atau gagal.',
          };
        }
        fbUser = res.user;
      }

      setFirebaseUser(fbUser);
      const cleanEmail = normalizeEmailKey(fbUser.email || '');
      if (!cleanEmail) {
        return { success: false, message: 'Email Google tidak ditemukan dari sesi login.' };
      }

      // 1. Ambil snapshot terbaru dari Firebase Realtime Database azkaakc (master_state + users/{uid} + users_by_email) agar akun yang sudah ada di HP/Cloud tidak tertimpa
      let serverCloudAccounts: BankAccount[] = [];
      let serverDeletedIds: string[] = [];
      let uidSavedAccounts: BankAccount[] = [];
      let emailSavedAccounts: BankAccount[] = [];
      const emailDocId = emailToFirestoreDocId(cleanEmail);
      try {
        const [mData, uData, eData] = await Promise.all([
          readCloudDoc<Record<string, any>>('bank_state_v1', 'master_state'),
          readCloudDoc<CloudUserRecord>('users', fbUser.uid),
          readCloudDoc<CloudUserRecord>('users_by_email', emailDocId),
        ]);
        if (mData) {
          serverCloudAccounts = toArraySafe<BankAccount>(mData.accounts);
          serverDeletedIds = toArraySafe<string>(mData.deletedAccountIds);
        }
        uidSavedAccounts = toArraySafe<BankAccount>(uData?.savedAccounts);
        emailSavedAccounts = toArraySafe<BankAccount>(eData?.savedAccounts);
      } catch {
        // fallback ke state lokal jika gagal baca server
      }

      const mergedDeletedIds = Array.from(
        new Set([...PURGED_BOT_ACCOUNT_IDS, ...deletedAccountIdsRef.current, ...serverDeletedIds])
      ).filter((id) => id !== targetAcc.id);
      setDeletedAccountIds(mergedDeletedIds);
      deletedAccountIdsRef.current = mergedDeletedIds;

      // 2. Transformasi Akun Guest -> Akun Google, sedangkan Akun OA tetap berstatus Akun OA Resmi SEKALIGUS terhubung ke Google (bisa login lewat Google & Login OA)
      const wasGuest = Boolean(targetAcc.isGuestAccount);
      const keepAsOfficialOa =
        !wasGuest && Boolean(targetAcc.isOfficialAdminAccount || targetAcc.id === 'acc-admin');
      const convertedGoogleAccount: BankAccount = {
        ...targetAcc,
        userId16: ensureAccountUserId16(targetAcc),
        email: cleanEmail,
        googleEmail: cleanEmail,
        firebaseUid: fbUser.uid,
        isGuestAccount: false,
        isOfficialAdminAccount: keepAsOfficialOa,
        oaAdminPin: targetAcc.oaAdminPin || '159357',
        cardStatus: targetAcc.cardStatus === 'banned' ? 'banned' : 'active',
        status: targetAcc.status === 'banned' ? 'banned' : 'active',
      };

      // 3. Gabungkan daftar akun dari Server Cloud + Dual-Vault Profil Email + State Lokal + Akun yang baru ditautkan ke Google
      const nextAccounts = unionMergeAccountsList(
        [convertedGoogleAccount],
        [
          serverCloudAccounts,
          emailSavedAccounts,
          uidSavedAccounts,
          latestServerAccountsRef.current,
          accountsRef.current,
        ],
        mergedDeletedIds
      );

      // 4. Perbarui state aplikasi + simpan instan ke IndexedDB agar refresh mendadak aman, lalu tulis ke Firebase RTDB azkaakc
      latestServerAccountsRef.current = nextAccounts;
      accountsRef.current = nextAccounts;
      setAccounts(nextAccounts);
      setCloudAccountVerificationState('confirmed_has_accounts');

      persistActiveSessionToIdb({
        authMode: 'google',
        firebaseUid: fbUser.uid,
        email: cleanEmail,
        emailKey: emailDocId,
        name: convertedGoogleAccount.fullName,
        picture: fbUser.photoURL || undefined,
        activeAccountId: convertedGoogleAccount.id,
        isPinVerified: true,
        hasCompletedOnboarding: true,
        accountsPool: nextAccounts,
      });

      const [masterWriteOk] = await Promise.all([
        flushMasterStateToCloud({
          accounts: nextAccounts,
          deletedAccountIds: mergedDeletedIds,
        }),
        syncCloudUserProfile(
          { uid: fbUser.uid, email: cleanEmail },
          {
            lastAccountId: convertedGoogleAccount.id,
            hasCompletedOnboarding: true,
            authMode: 'google',
            displayName: convertedGoogleAccount.fullName,
            photoURL: fbUser.photoURL || undefined,
          },
          nextAccounts
        ),
      ]);

      if (!masterWriteOk) {
        playAtmSound('alert');
        return {
          success: false,
          message:
            'Koneksi ke Firebase Realtime Database azkaakc sedang terputus. Pastikan internet aktif lalu coba sambungkan kembali.',
        };
      }

      hasFirestoreHydratedRef.current = true;
      hasBootHydratedRef.current = true;

      if (!targetAccountId || targetAccountId === currentAccount?.id) {
        setCurrentAccountIdState(convertedGoogleAccount.id);
        setActiveCloudEmail(cleanEmail);
        setGoogleUser((prev) => ({
          email: cleanEmail,
          name: convertedGoogleAccount.fullName,
          picture: fbUser.photoURL || prev?.picture,
          firebaseUid: fbUser.uid,
          authMode: 'google',
          emailKey: emailToFirestoreDocId(cleanEmail),
          loggedInAt: new Date().toISOString(),
          hasCompletedOnboarding: true,
          isPinVerified: true,
        }));
      }

      playAtmSound('success');
      addNotification(
        wasGuest
          ? 'Akun Guest Berubah Menjadi Akun Google ☁️'
          : 'Akun OA Berhasil Disambungkan ke Google 🔗',
        `Rekening "${convertedGoogleAccount.fullName}" (No. Rek: ${convertedGoogleAccount.accountNumber}) kini resmi berstatus Akun Google di Firebase pada email ${cleanEmail} dan otomatis muncul di HP maupun Laptop.`,
        'success'
      );

      return {
        success: true,
        email: cleanEmail,
        atomicMergeSummary,
        message: atomicMergeSummary?.performed
          ? `Atomic Data Rescue & Merge berhasil! Akun "${convertedGoogleAccount.fullName}" dan seluruh data digabung permanen ke Google (${cleanEmail}) tanpa kehilangan data.`
          : keepAsOfficialOa
          ? `Akun OA Resmi "${convertedGoogleAccount.fullName}" (${convertedGoogleAccount.accountNumber}) berhasil disambungkan ke Google (${cleanEmail}) & tersinkronisasi real-time! Anda tetap bisa login lewat Google maupun Login Akun OA.`
          : `Akun "${convertedGoogleAccount.fullName}" (${convertedGoogleAccount.accountNumber}) berhasil diamankan ke Google (${cleanEmail}) dengan UID permanen & tersinkronisasi real-time!`,
      };
    } finally {
      isLinkingAccountToGoogleRef.current = false;
    }
  };

  // ============================================================================
  // ZERO-TRUST VAULT, TIME-MACHINE BACKUP & RE-AUTH CLOUD HELPERS
  // ============================================================================
  const dismissAtomicMergeSummary = () => setLastAtomicMergeSummary(null);

  const buildPersonalBackupPayload = (): BankingBackupPayload => {
    const activeUid =
      auth.currentUser?.uid || firebaseUser?.uid || googleUser?.firebaseUid || 'local-session';
    const activeEmail = normalizeEmailKey(
      auth.currentUser?.email ||
        googleUser?.email ||
        currentAccount?.googleEmail ||
        currentAccount?.email ||
        ''
    );

    const ownedAccounts = accounts.filter((acc) => {
      if (acc.id === currentAccountId) return true;
      if (activeUid && activeUid !== 'local-session' && acc.firebaseUid === activeUid) return true;
      const gEm = acc.googleEmail ? normalizeEmailKey(acc.googleEmail) : '';
      const aEm = acc.email ? normalizeEmailKey(acc.email) : '';
      return Boolean(activeEmail && (gEm === activeEmail || aEm === activeEmail));
    });
    const ownedIds = new Set(ownedAccounts.map((a) => a.id));
    const ownedTx = transactions.filter((t) => ownedIds.has(t.accountId));
    const ownedPockets = pockets.filter((p) => ownedIds.has(p.accountId));
    const ownedDepositos = depositos.filter((d) => ownedIds.has(d.accountId));
    const totalGrams = ownedAccounts.reduce((s, a) => s + (Number(a.goldGrams) || 0), 0);
    const totalBatches = ownedAccounts.reduce((s, a) => s + (a.goldBatches?.length || 0), 0);

    return {
      profile: {
        uid: activeUid,
        email: activeEmail,
        displayName:
          auth.currentUser?.displayName ||
          googleUser?.name ||
          currentAccount?.fullName ||
          'Nasabah Bank Nusantara',
        currentAccountId,
      },
      accounts: ownedAccounts,
      transactions: ownedTx,
      pockets: ownedPockets,
      depositos: ownedDepositos,
      budgetCategories,
      manualExpenses,
      budgetTxCategoryMap,
      userSettings,
      goldSummary: {
        totalGrams: Number(totalGrams.toFixed(4)),
        totalBatches,
      },
    };
  };

  const restoreFromBankingPayload = async (
    payload: BankingBackupPayload,
    sourceLabel: string
  ): Promise<{ success: boolean; message: string }> => {
    const activeUid = auth.currentUser?.uid || firebaseUser?.uid;
    if (auth.currentUser && !auth.currentUser.isAnonymous) {
      const reauth = await requireGoogleReauthentication(`Pemulihan data dari ${sourceLabel}`);
      if (!reauth.success) {
        return { success: false, message: reauth.message };
      }
    }

    if (activeUid) {
      await createCloudSnapshot(activeUid, buildPersonalBackupPayload(), 'pre_restore');
    }

    const incomingAccounts = toArraySafe<BankAccount>(payload.accounts);
    if (incomingAccounts.length === 0) {
      return {
        success: false,
        message: 'Data backup tidak memiliki rekening yang valid untuk dipulihkan.',
      };
    }

    const incomingTx = toArraySafe<Transaction>(payload.transactions);
    const incomingPockets = toArraySafe<PocketSaving>(payload.pockets);
    const incomingDepositos = toArraySafe<DepositoRecord>(payload.depositos);

    const mergedAccounts = unionMergeAccountsList(
      incomingAccounts,
      [accountsRef.current, latestServerAccountsRef.current],
      deletedAccountIdsRef.current.filter((id) => !incomingAccounts.some((a) => a.id === id))
    );
    const mergedTx = [
      ...incomingTx,
      ...transactions.filter((existing) => !incomingTx.some((t) => t.id === existing.id)),
    ].slice(0, 220);
    const mergedPockets = [
      ...incomingPockets,
      ...pockets.filter((existing) => !incomingPockets.some((p) => p.id === existing.id)),
    ];
    const mergedDepositos = [
      ...incomingDepositos,
      ...depositos.filter((existing) => !incomingDepositos.some((d) => d.id === existing.id)),
    ];

    latestServerAccountsRef.current = mergedAccounts;
    accountsRef.current = mergedAccounts;
    setAccounts(mergedAccounts);
    setTransactions(mergedTx);
    setPockets(mergedPockets);
    setDepositos(mergedDepositos);
    if (Array.isArray(payload.budgetCategories) && payload.budgetCategories.length > 0) {
      setBudgetCategories(payload.budgetCategories);
    }
    if (Array.isArray(payload.manualExpenses)) {
      setManualExpenses(payload.manualExpenses);
    }
    if (payload.budgetTxCategoryMap && typeof payload.budgetTxCategoryMap === 'object') {
      setBudgetTxCategoryMap(payload.budgetTxCategoryMap);
    }
    if (payload.userSettings && typeof payload.userSettings === 'object') {
      setUserSettings((prev) => ({ ...prev, ...payload.userSettings }));
    }

    const targetCurrId =
      payload.profile?.currentAccountId &&
      mergedAccounts.some((a) => a.id === payload.profile.currentAccountId)
        ? payload.profile.currentAccountId
        : incomingAccounts[0].id;
    setCurrentAccountIdState(targetCurrId);

    const flushOk = await flushMasterStateToCloud({
      accounts: mergedAccounts,
      transactions: mergedTx,
      pockets: mergedPockets,
      depositos: mergedDepositos,
      budgetCategories:
        Array.isArray(payload.budgetCategories) && payload.budgetCategories.length > 0
          ? payload.budgetCategories
          : budgetCategories,
      manualExpenses: Array.isArray(payload.manualExpenses) ? payload.manualExpenses : manualExpenses,
      budgetTxCategoryMap: payload.budgetTxCategoryMap || budgetTxCategoryMap,
      userSettings: payload.userSettings || userSettings,
    });

    if (activeUid) {
      await appendSecurityAuditLog(
        activeUid,
        sourceLabel.toLowerCase().includes('json') ? 'backup_imported' : 'snapshot_restored',
        `Data perbankan berhasil dipulihkan dari ${sourceLabel} (${incomingAccounts.length} kartu, ${incomingTx.length} mutasi).`
      );
    }

    playAtmSound('success');
    return {
      success: flushOk,
      message: flushOk
        ? `Pemulihan dari ${sourceLabel} selesai (${incomingAccounts.length} kartu & ${incomingTx.length} mutasi) dan langsung tersinkronisasi ke Cloud.`
        : 'Data dipulihkan di perangkat ini, namun unggahan cloud tertunda karena jaringan offline.',
    };
  };

  const forceSyncCloudNow = async (): Promise<{ success: boolean; message: string }> => {
    const activeUid = auth.currentUser?.uid || firebaseUser?.uid || null;
    const backupPayload = buildPersonalBackupPayload();
    const docCount =
      backupPayload.accounts.length +
      backupPayload.transactions.length +
      backupPayload.pockets.length +
      backupPayload.depositos.length;
    const [masterOk, vaultRes] = await Promise.all([
      flushMasterStateToCloud(),
      forceSyncVaultNow(activeUid, backupPayload as unknown as Record<string, unknown>, docCount),
    ]);
    if (masterOk && vaultRes.success) {
      return { success: true, message: vaultRes.message };
    }
    return {
      success: false,
      message: vaultRes.message || 'Sinkronisasi gagal. Periksa koneksi internet Anda lalu coba lagi.',
    };
  };

  const resetCloudDataWithReauth = async (): Promise<{ success: boolean; message: string }> => {
    const activeUid = auth.currentUser?.uid || firebaseUser?.uid;
    if (auth.currentUser && !auth.currentUser.isAnonymous) {
      const reauth = await requireGoogleReauthentication('Reset seluruh data cloud Bank Nusantara');
      if (!reauth.success) {
        return { success: false, message: reauth.message };
      }
    }
    if (activeUid) {
      await createCloudSnapshot(activeUid, buildPersonalBackupPayload(), 'pre_reset');
      await appendSecurityAuditLog(
        activeUid,
        'cloud_reset',
        'Reset data cloud dieksekusi setelah verifikasi ulang Google & pembuatan auto-checkpoint cadangan.',
        { status: 'warning' }
      );
    }
    resetAllData();
    return {
      success: true,
      message:
        'Reset data cloud selesai. Auto-checkpoint cadangan telah disimpan di Time-Machine sebelum reset.',
    };
  };

  const ensureAnonymousSessionNow = async (): Promise<{
    success: boolean;
    uid?: string;
    message: string;
  }> => {
    const res = await ensureAnonymousVaultSession();
    if (res.success && res.user) {
      setFirebaseUser(res.user);
    }
    return { success: res.success, uid: res.uid, message: res.message };
  };

  // Deteksi SELURUH kartu/akun yang terhubung ke email Google yang sedang login (Reguler, Akun OA yang disambungkan, maupun Guest yang disambungkan)
  // Menggabungkan pembacaan dari state accounts utama + Dual-Vault cloudUserStatus.savedAccounts
  const linkedUserAccounts: BankAccount[] = (() => {
    if (!googleUser) return [];
    const cleanEmail = normalizeEmailKey(googleUser.email || activeCloudEmail || '');
    const uid = googleUser.firebaseUid || firebaseUser?.uid;

    const combinedPool: BankAccount[] = [
      ...accounts,
      ...(Array.isArray(cloudUserStatus?.savedAccounts) ? cloudUserStatus!.savedAccounts : []),
    ].filter(
      (a) =>
        a &&
        a.id &&
        !deletedAccountIds.includes(a.id) &&
        !PURGED_BOT_ACCOUNT_IDS.includes(a.id) &&
        !PURGED_BOT_ACCOUNT_NUMBERS.includes(a.accountNumber)
    );

    const matched: BankAccount[] = [];
    const seenIds = new Set<string>();

    if (cleanEmail) {
      for (const a of combinedPool) {
        const gEmail = a.googleEmail ? normalizeEmailKey(a.googleEmail) : '';
        const aEmail = a.email ? normalizeEmailKey(a.email) : '';
        if ((gEmail === cleanEmail || aEmail === cleanEmail) && !seenIds.has(a.id)) {
          seenIds.add(a.id);
          matched.push(a);
        }
      }
    }

    if (uid) {
      for (const a of combinedPool) {
        if (a.firebaseUid === uid && !seenIds.has(a.id)) {
          // Hanya masukkan jika email akun cocok atau kosong
          const gEmail = a.googleEmail ? normalizeEmailKey(a.googleEmail) : '';
          const aEmail = a.email ? normalizeEmailKey(a.email) : '';
          if (!cleanEmail || !gEmail || gEmail === cleanEmail || aEmail === cleanEmail) {
            seenIds.add(a.id);
            matched.push(a);
          }
        }
      }
    }

    return matched;
  })();

  // Deteksi kartu aktif utama dari daftar linkedUserAccounts
  const linkedUserAccount: BankAccount | null = (() => {
    if (linkedUserAccounts.length === 0) return null;
    const byCurrent = linkedUserAccounts.find((a) => a.id === currentAccountId);
    if (byCurrent) return byCurrent;
    const preferredId = cloudUserStatus?.lastAccountId;
    if (preferredId) {
      const byPref = linkedUserAccounts.find((a) => a.id === preferredId);
      if (byPref) return byPref;
    }
    return linkedUserAccounts[0] || null;
  })();

  // Self-Healing Auto-Recovery: Jika data rekening lama tiba dari Cloud setelah gerbang terbuka,
  // otomatis pulihkan & pindahkan langsung ke rekening lama tanpa pernah memaksa buat akun baru!
  useEffect(() => {
    if (!googleUser || linkedUserAccounts.length === 0 || !linkedUserAccount) return;
    if (cloudAccountVerificationState !== 'confirmed_has_accounts') {
      setCloudAccountVerificationState('confirmed_has_accounts');
    }
    if (!googleUser.hasCompletedOnboarding) {
      setCurrentAccountIdState(linkedUserAccount.id);
      setGoogleUser((prev) =>
        prev
          ? {
              ...prev,
              name: linkedUserAccount.fullName || prev.name,
              hasCompletedOnboarding: true,
            }
          : prev
      );
    }
  }, [googleUser, linkedUserAccounts.length, linkedUserAccount, cloudAccountVerificationState]);

  // Cek Ulang Rekening dari Cloud secara manual (dipanggil dari tombol "Muat Ulang Akun Cloud" saat koneksi lambat)
  const retryCloudAccountCheck = async (): Promise<boolean> => {
    const uid = auth.currentUser?.uid || firebaseUser?.uid || googleUser?.firebaseUid;
    const rawEmail = auth.currentUser?.email || googleUser?.email || activeCloudEmail || '';
    const cleanEmail = rawEmail ? normalizeEmailKey(rawEmail) : '';
    const emailDocId = cleanEmail ? emailToFirestoreDocId(cleanEmail) : '';

    setCloudAccountVerificationState('verifying');
    updateSyncTelemetry({ hasPendingWrites: true, lastError: null });

    try {
      const [masterData, uidData, emailData] = await Promise.all([
        readCloudDoc<Record<string, any>>('bank_state_v1', 'master_state', {
          timeoutMs: 5000,
          skipFirestoreFallback: true,
        }),
        uid
          ? readCloudDoc<CloudUserRecord>('users', uid, {
              timeoutMs: 5000,
              skipFirestoreFallback: true,
            })
          : Promise.resolve(null),
        emailDocId
          ? readCloudDoc<CloudUserRecord>('users_by_email', emailDocId, {
              timeoutMs: 5000,
              skipFirestoreFallback: true,
            })
          : Promise.resolve(null),
      ]);

      const responded = masterData !== null || uidData !== null || emailData !== null;
      if (masterData) {
        applyMasterCloudData(masterData, { forceInitial: true });
      }

      const uidSaved = toArraySafe<BankAccount>(uidData?.savedAccounts);
      const emailSaved = toArraySafe<BankAccount>(emailData?.savedAccounts);
      const merged = unionMergeAccountsList(
        accountsRef.current,
        [emailSaved, uidSaved, latestServerAccountsRef.current],
        deletedAccountIdsRef.current
      );
      if (merged.length > 0) {
        latestServerAccountsRef.current = merged;
        accountsRef.current = merged;
        setAccounts(merged);
        void saveFastBootSnapshot({
          accounts: merged,
          deletedAccountIds: deletedAccountIdsRef.current,
          cachedAtMs: Date.now(),
        });
      }

      if (uidData || emailData) {
        setCloudUserStatus((uidData || emailData)!);
      }

      const matched = merged.find(
        (a) =>
          (uid && a.firebaseUid === uid) ||
          (cleanEmail &&
            ((a.googleEmail && normalizeEmailKey(a.googleEmail) === cleanEmail) ||
              (a.email && normalizeEmailKey(a.email) === cleanEmail)))
      );

      if (matched) {
        setCurrentAccountIdState(matched.id);
        setCloudAccountVerificationState('confirmed_has_accounts');
        setGoogleUser((prev) =>
          prev
            ? {
                ...prev,
                name: matched.fullName || prev.name,
                hasCompletedOnboarding: true,
              }
            : prev
        );
        updateSyncTelemetry({
          fromCache: false,
          hasPendingWrites: false,
          lastSyncedAt: new Date().toISOString(),
          syncedDocCount: merged.length,
        });
        return true;
      }

      if (responded && (typeof navigator === 'undefined' || navigator.onLine)) {
        setCloudAccountVerificationState('confirmed_zero_accounts');
        updateSyncTelemetry({ fromCache: false, hasPendingWrites: false });
      } else {
        setCloudAccountVerificationState('network_timeout');
      }
      return false;
    } catch {
      setCloudAccountVerificationState('network_timeout');
      return false;
    }
  };

  const appendBanAuditLog = (
    entry: Omit<BanAuditLogEntry, 'id' | 'timestamp'>,
    baseConfig?: BanSupportConfig
  ): BanSupportConfig => {
    const currentCfg = baseConfig || banSupportConfig;
    const newEntry: BanAuditLogEntry = {
      ...entry,
      id: `audit-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
      timestamp: new Date().toISOString(),
    };
    const nextLogs = [newEntry, ...(currentCfg.auditLogs || [])].slice(0, 120);
    return {
      ...currentCfg,
      auditLogs: nextLogs,
      updatedAt: new Date().toISOString(),
    };
  };

  // Verifikasi 6 Digit PIN Kartu di awal untuk Akun Terpilih (Gagal 5x -> Kunci Login 1 Hari / 24 Jam Tanpa Banned & Tanpa Tinjauan)
  const verifyInitialCardPin = (cardPin: string, targetAccountId?: string) => {
    const targetAcc =
      (targetAccountId ? accounts.find((a) => a.id === targetAccountId) : null) ||
      linkedUserAccount ||
      currentAccount;
    if (!targetAcc) {
      playAtmSound('alert');
      return {
        success: false,
        message: 'Kartu akun Anda tidak ditemukan. Silakan buat kartu baru.',
      };
    }

    const nowMs = Date.now();
    const lockUntilMs = targetAcc.loginLockedUntil
      ? new Date(targetAcc.loginLockedUntil).getTime()
      : 0;
    if (lockUntilMs > nowMs) {
      playAtmSound('alert');
      return {
        success: false,
        failedAttempts: 5,
        remainingAttempts: 0,
        bannedNow: false,
        loginLockedUntil: targetAcc.loginLockedUntil,
        message:
          'Tidak bisa login selama 1 Hari (24 Jam) karena salah memasukkan PIN Kartu 5 kali. Penguncian login ini tidak dapat ditinjau/banding, silakan tunggu hingga hitung mundur selesai.',
      };
    }

    const cleanPin = cardPin.trim();
    const isCardPinMatch = targetAcc.pin === cleanPin;
    const isAdminPinMatch = cleanPin === '159357';

    const activeEmailSession =
      googleUser?.email || activeCloudEmail || targetAcc.googleEmail || targetAcc.email || '';
    const targetUid = firebaseUser?.uid || targetAcc.firebaseUid;

    if (isCardPinMatch || isAdminPinMatch) {
      const nextAccounts = accounts.map((acc) =>
        acc.id === targetAcc.id
          ? {
              ...acc,
              failedPinAttempts: 0,
              lastFailedPinAt: undefined,
              loginLockedUntil: undefined,
              loginLockReason: undefined,
              accountUpdatedAtMs: nowMs,
              firebaseUid: acc.firebaseUid || targetUid,
              googleEmail: acc.googleEmail || activeEmailSession || acc.email,
              email: acc.email || activeEmailSession,
            }
          : acc
      );
      setAccounts(nextAccounts);
      accountsRef.current = nextAccounts;
      latestServerAccountsRef.current = nextAccounts;
      setCurrentAccountIdState(targetAcc.id);
      setCloudAccountVerificationState('confirmed_has_accounts');
      setGoogleUser((prev) =>
        prev
          ? {
              ...prev,
              name: targetAcc.fullName,
              hasCompletedOnboarding: true,
              isPinVerified: true,
            }
          : prev
      );
      // Simpan sesi terverifikasi ke IndexedDB agar refresh langsung kembali ke Dashboard rekening ini
      persistActiveSessionToIdb({
        authMode:
          googleUser?.authMode === 'oa_account'
            ? 'oa_account'
            : googleUser?.authMode === 'standard_account'
            ? 'standard_account'
            : googleUser?.authMode === 'guest'
            ? 'guest'
            : 'google',
        firebaseUid: targetUid,
        email: activeEmailSession,
        name: targetAcc.fullName,
        picture: googleUser?.picture,
        activeAccountId: targetAcc.id,
        isPinVerified: true,
        hasCompletedOnboarding: true,
        accountsPool: nextAccounts,
      });
      flushMasterStateToCloud({ accounts: nextAccounts });
      void syncCloudUserProfile(
        { uid: targetUid, email: activeEmailSession, fallbackEmail: targetAcc.email },
        {
          failedPinAttempts: 0,
          loginLockedUntil: '',
          loginLockReason: '',
          lastAccountId: targetAcc.id,
          hasCompletedOnboarding: true,
        }
      );
      playAtmSound('success');
      return {
        success: true,
        failedAttempts: 0,
        remainingAttempts: 5,
        bannedNow: false,
        message: `PIN Kartu benar! Selamat datang kembali, ${targetAcc.fullName}.`,
      };
    }

    // Jika salah PIN Kartu (jika kunci 1 hari sebelumnya sudah kedaluwarsa, mulai ulang hitungan dari 0):
    const rawAttempts =
      typeof targetAcc.failedPinAttempts === 'number'
        ? targetAcc.failedPinAttempts
        : cloudUserStatus?.failedPinAttempts || 0;
    const currentAttempts =
      (targetAcc.loginLockedUntil && lockUntilMs <= nowMs) || rawAttempts >= 5 ? 0 : rawAttempts;
    const nextAttempts = currentAttempts + 1;
    const nowIso = new Date().toISOString();

    if (nextAttempts >= 5) {
      // Gagal 5x berturut-turut -> Kunci Login 1 Hari (24 jam) TANPA Banned Kartu & TANPA Banding/Tinjauan
      const oneDayExpiresAt = new Date(nowMs + 1440 * 60 * 1000).toISOString();
      const pinLockReason =
        'Salah memasukkan PIN Kartu 5 kali berturut-turut saat Login (Tidak Bisa Login Selama 1 Hari / 24 Jam & Tidak Dapat Ditinjau).';
      const caseId = generateBanCaseId();

      const nextAccounts: BankAccount[] = accounts.map((acc) =>
        acc.id === targetAcc.id
          ? {
              ...acc,
              failedPinAttempts: 5,
              lastFailedPinAt: nowIso,
              loginLockedUntil: oneDayExpiresAt,
              loginLockReason: pinLockReason,
              accountUpdatedAtMs: nowMs,
            }
          : acc
      );

      const nextBanSupport = appendBanAuditLog({
        action: 'pin_5x_ban',
        accountId: targetAcc.id,
        accountName: targetAcc.fullName,
        accountNumber: targetAcc.accountNumber,
        durationLabel: 'Kunci Login 1 Hari (24 Jam)',
        reason: pinLockReason,
        caseId,
        summary: `Gagal memasukkan PIN Kartu 5x berturut-turut — otomatis Kunci Login 1 Hari tanpa banned kartu (${targetAcc.fullName})`,
      });

      setAccounts(nextAccounts);
      accountsRef.current = nextAccounts;
      latestServerAccountsRef.current = nextAccounts;
      setBanSupportConfig(nextBanSupport);
      setCloudUserStatus((prev) =>
        prev
          ? {
              ...prev,
              failedPinAttempts: 5,
              lastFailedPinAt: nowIso,
              loginLockedUntil: oneDayExpiresAt,
              loginLockReason: pinLockReason,
            }
          : prev
      );
      flushMasterStateToCloud({ accounts: nextAccounts, banSupportConfig: nextBanSupport });

      void syncCloudUserProfile(
        { uid: targetUid, email: activeEmailSession, fallbackEmail: targetAcc.email },
        {
          failedPinAttempts: 5,
          lastFailedPinAt: nowIso,
          loginLockedUntil: oneDayExpiresAt,
          loginLockReason: pinLockReason,
        }
      );

      emitAdminTierNotification({
        eventType: 'pin_lock_1day',
        title: `🔒 Akun Terkunci Login 1 Hari (Salah PIN 5x)`,
        message: `Akun "${targetAcc.fullName}" (${targetAcc.accountNumber}) salah memasukkan PIN Kartu 5 kali saat Login dan tidak bisa login selama 24 jam.`,
        adminTargetTab: 'keamanan',
        accountId: targetAcc.id,
        quickAction: {
          actionType: 'reset_pin_lock',
          label: 'Reset Salah PIN & Buka Kunci (0/5)',
          targetId: targetAcc.id,
        },
      });

      playAtmSound('alert');
      return {
        success: false,
        failedAttempts: 5,
        remainingAttempts: 0,
        bannedNow: false,
        loginLockedUntil: oneDayExpiresAt,
        message:
          'Anda telah salah memasukkan PIN Kartu sebanyak 5 kali! Tidak bisa login selama 1 Hari (24 Jam) dan tidak dapat ditinjau.',
      };
    }

    // Jika belum 5x (1/5 s.d. 4/5): simpan jumlah gagal ke Cloud
    const remaining = 5 - nextAttempts;
    const nextAccounts = accounts.map((acc) =>
      acc.id === targetAcc.id
        ? {
            ...acc,
            failedPinAttempts: nextAttempts,
            lastFailedPinAt: nowIso,
            accountUpdatedAtMs: nowMs,
          }
        : acc
    );
    setAccounts(nextAccounts);
    accountsRef.current = nextAccounts;
    latestServerAccountsRef.current = nextAccounts;
    setCloudUserStatus((prev) =>
      prev ? { ...prev, failedPinAttempts: nextAttempts, lastFailedPinAt: nowIso } : prev
    );
    flushMasterStateToCloud({ accounts: nextAccounts });
    void syncCloudUserProfile(
      { uid: targetUid, email: activeEmailSession, fallbackEmail: targetAcc.email },
      {
        failedPinAttempts: nextAttempts,
        lastFailedPinAt: nowIso,
      }
    );

    emitPinSecurityAlert(targetAcc.fullName, `Gagal PIN Login (${nextAttempts}/5)`);
    playAtmSound('alert');
    return {
      success: false,
      failedAttempts: nextAttempts,
      remainingAttempts: remaining,
      bannedNow: false,
      message: `PIN Kartu salah! Percobaan gagal ${nextAttempts}/5 — tersisa ${remaining} kesempatan sebelum tidak bisa login selama 1 hari.`,
    };
  };

  const adminResetPinAttempts = (accountId: string) => {
    const target = accounts.find((a) => a.id === accountId);
    if (!target) return { success: false, message: 'Akun tidak ditemukan.' };

    const nowMs = Date.now();
    const nextAccounts = accounts.map((acc) =>
      acc.id === accountId
        ? {
            ...acc,
            failedPinAttempts: 0,
            lastFailedPinAt: undefined,
            loginLockedUntil: undefined,
            loginLockReason: undefined,
            accountUpdatedAtMs: nowMs,
          }
        : acc
    );
    const nextBanSupport = appendBanAuditLog({
      action: 'reset_pin_attempts',
      accountId: target.id,
      accountName: target.fullName,
      accountNumber: target.accountNumber,
      summary: `Admin me-reset penghitung gagal PIN & membuka Kunci Login 1 Hari (${target.failedPinAttempts || 0}/5 -> 0/5) untuk ${target.fullName}`,
    });

    setAccounts(nextAccounts);
    accountsRef.current = nextAccounts;
    latestServerAccountsRef.current = nextAccounts;
    setBanSupportConfig(nextBanSupport);
    flushMasterStateToCloud({ accounts: nextAccounts, banSupportConfig: nextBanSupport });
    void syncCloudUserProfile(
      {
        uid: target.firebaseUid,
        email: target.googleEmail || target.email,
        fallbackEmail: target.email,
      },
      {
        failedPinAttempts: 0,
        loginLockedUntil: '',
        loginLockReason: '',
      }
    );
    playAtmSound('success');
    return {
      success: true,
      message: `Jumlah percobaan gagal PIN & Kunci Login 1 Hari untuk ${target.fullName} berhasil di-reset ke 0/5!`,
    };
  };

  // ================= REAL-TIME BAN LOCK STATE & UNIFIED APPEALS (WA / EMAIL / IN-APP) =================
  const computeActiveBanLockState = () => {
    const targetAcc = linkedUserAccount || currentAccount;
    const nowMs = Date.now();
    const cloudUpdatedMs =
      Number(cloudUserStatus?.updatedAtMs) ||
      (cloudUserStatus?.updatedAt ? Date.parse(String(cloudUserStatus.updatedAt)) || 0 : 0);

    // Jika rekening lokal sudah resmi dibuka blokirnya lebih baru dari cache cloudUserStatus, jangan biarkan cache lama mengunci layar!
    const targetUnbannedNewer = Boolean(
      targetAcc &&
        targetAcc.status === 'active' &&
        targetAcc.cardStatus === 'active' &&
        !targetAcc.banInfo?.isBanned &&
        Number(targetAcc.unbannedAtMs || 0) > 0 &&
        Number(targetAcc.unbannedAtMs || 0) >= cloudUpdatedMs
    );

    const rawCloudBanned = cloudUserStatus?.status === 'banned' && !targetUnbannedNewer;
    const accountBanned =
      Boolean(targetAcc) &&
      (targetAcc?.status === 'banned' ||
        targetAcc?.cardStatus === 'banned' ||
        Boolean(targetAcc?.banInfo?.isBanned));

    const baseTemplate: BanScreenCustomizationConfig = {
      ...DEFAULT_BAN_SCREEN_CONFIG,
      ...(banSupportConfig.defaultTemplateConfig || {}),
    };

    const rawExpiresAt =
      targetAcc?.banInfo?.expiresAt ||
      targetAcc?.banInfo?.bannedUntil ||
      targetAcc?.banInfo?.customConfig?.expiresAt ||
      (rawCloudBanned ? cloudUserStatus?.banExpiresAt : undefined);

    const parsedExpiresMs = rawExpiresAt ? Date.parse(String(rawExpiresAt)) : NaN;
    const isTrialAlreadyExpired =
      Boolean(rawExpiresAt) && Number.isFinite(parsedExpiresMs) && nowMs >= parsedExpiresMs;

    const isBanned = Boolean((rawCloudBanned || accountBanned) && !isTrialAlreadyExpired);
    if (!isBanned) {
      return {
        isBanned: false,
        reason: '',
        appealStatus: 'none' as const,
        appealCount: 0,
        customConfig: baseTemplate,
      };
    }

    const customCfg: BanScreenCustomizationConfig = {
      ...baseTemplate,
      ...(cloudUserStatus?.banCustomConfig || {}),
      ...(targetAcc?.banInfo?.customConfig || {}),
      ...(rawExpiresAt ? { durationType: 'custom' as const, expiresAt: rawExpiresAt } : {}),
    };

    const rawReason =
      targetAcc?.banInfo?.reason !== undefined
        ? targetAcc.banInfo.reason
        : cloudUserStatus?.banReason !== undefined
        ? cloudUserStatus.banReason
        : targetAcc?.banReason !== undefined
        ? targetAcc.banReason
        : customCfg.reasonText || '';

    const cleanReason =
      customCfg.reasonMode === 'none' || customCfg.showReasonBox === false
        ? ''
        : (rawReason || '').trim();

    const appealStatus =
      targetAcc?.banInfo?.appealStatus ||
      cloudUserStatus?.appealStatus ||
      ('none' as const);

    const appealCount =
      targetAcc?.banInfo?.appealCount ??
      cloudUserStatus?.appealCount ??
      (appealStatus !== 'none' ? 1 : 0);

    return {
      isBanned: true,
      reason: cleanReason,
      bannedAt:
        targetAcc?.banInfo?.bannedAt ||
        cloudUserStatus?.bannedAt ||
        cloudUserStatus?.updatedAt,
      durationLabel:
        targetAcc?.banInfo?.durationLabel ||
        cloudUserStatus?.banDurationLabel ||
        customCfg.durationLabel ||
        'Diblokir Real-Time',
      expiresAt: rawExpiresAt,
      appealStatus,
      appealNote: targetAcc?.banInfo?.appealNote || cloudUserStatus?.appealNote,
      appealCategory:
        targetAcc?.banInfo?.appealCategory || cloudUserStatus?.appealCategory,
      appealCount,
      appealAdminNote:
        targetAcc?.banInfo?.appealAdminNote || cloudUserStatus?.appealAdminNote,
      customConfig: customCfg,
    };
  };

  const activeBanLockState = computeActiveBanLockState();

  // Pastikan jika tiba-tiba dibanned secara real-time, seluruh modal terbuka langsung ditutup & bunyikan efek suara sesuai pengaturan Admin
  const prevBannedStateRef = useRef<boolean>(false);
  useEffect(() => {
    if (activeBanLockState.isBanned) {
      setActiveGiftModal(null);
      setIsMintolModalOpen(false);
      setIsBugReportModalOpen(false);
      setIsGlobalChatModalOpen(false);
      if (!prevBannedStateRef.current) {
        const sound = activeBanLockState.customConfig.soundEffect;
        if (sound === 'siren' || sound === 'alert') {
          playAtmSound('alert');
        }
      }
    }
    prevBannedStateRef.current = activeBanLockState.isBanned;
  }, [activeBanLockState.isBanned, activeBanLockState.customConfig.soundEffect]);

  const adminUpdateBanSupportConfig = async (
    config: BanSupportConfig
  ): Promise<{ success: boolean; message: string }> => {
    const nowMs = Date.now();
    const nowIso = new Date(nowMs).toISOString();
    const cleanWa = config.whatsappNumber.replace(/[^\d+]/g, '').trim();
    const cleanEmail = config.emailAddress.trim();
    const nextConfig: BanSupportConfig = {
      ...banSupportConfig,
      ...config,
      whatsappNumber: cleanWa,
      emailAddress: cleanEmail,
      updatedAt: nowIso,
    };
    banSupportUpdatedAtMsRef.current = nowMs;
    configUpdatedAtMsMapRef.current.banSupportConfig = nowMs;
    setLastAdminSavedAtIso(nowIso);
    setBanSupportConfig(nextConfig);
    void saveAdminPersistentDataIdb({
      banSupportConfig: nextConfig,
      banSupportUpdatedAtMs: nowMs,
      lastAdminSavedAtIso: nowIso,
    });
    persistAdminConfigChange('banSupportConfig', nextConfig, {
      cloudOverride: { banSupportConfig: nextConfig },
      label: 'Kontak & Studio Banned',
    });
    playAtmSound('success');
    return {
      success: true,
      message: 'Konfigurasi Kontak & Studio Banned berhasil disimpan permanen ke Cloud & Perangkat!',
    };
  };

  const submitUnifiedBanAppeal = async (
    message: string,
    source: 'in_app' | 'whatsapp' | 'email' = 'in_app',
    appealCategory?: string,
    promiseAccepted?: boolean
  ): Promise<{ success: boolean; message: string }> => {
    const targetAcc = linkedUserAccount || currentAccount;
    const cfg = activeBanLockState.customConfig;
    const currentAppealCount = activeBanLockState.appealCount || 0;

    if (source === 'in_app') {
      if (
        activeBanLockState.appealStatus === 'rejected' &&
        cfg.allowResubmitAfterReject === false
      ) {
        return {
          success: false,
          message: 'Pengajuan tinjauan Anda sebelumnya telah ditolak dan form pengiriman ulang dikunci oleh Admin.',
        };
      }
      if (cfg.maxAppeals > 0 && currentAppealCount >= cfg.maxAppeals) {
        return {
          success: false,
          message: `Batas maksimal pengajuan tinjauan (${cfg.maxAppeals}x) telah tercapai.`,
        };
      }
      if (cfg.requireAppealCategoryAndPromise && (!appealCategory || !promiseAccepted)) {
        return {
          success: false,
          message: 'Wajib memilih kategori alasan banding dan mencentang pernyataan janji terlebih dahulu.',
        };
      }
    }

    const cleanNote = message.trim();
    if (source === 'in_app' && cleanNote.length < 5) {
      return {
        success: false,
        message: 'Mohon tulis alasan atau penjelasan tinjauan Anda minimal 5 karakter.',
      };
    }

    const nowIso = new Date().toISOString();
    const finalNote =
      cleanNote ||
      (source === 'whatsapp'
        ? 'Pengguna menghubungi Admin melalui tombol Tinjau dengan WhatsApp.'
        : 'Pengguna menghubungi Admin melalui tombol Tinjau dengan Email.');
    const nextAppealCount = currentAppealCount + 1;

    const updatedAccounts = targetAcc
      ? accounts.map((acc) =>
          acc.id === targetAcc.id
            ? {
                ...acc,
                status: 'banned' as const,
                cardStatus: 'banned' as const,
                banInfo: {
                  ...(acc.banInfo || {
                    isBanned: true,
                    durationType: cfg.durationType,
                    durationLabel: activeBanLockState.durationLabel || 'PERMANEN',
                    bannedAt: nowIso,
                    reason: activeBanLockState.reason,
                  }),
                  appealStatus: 'pending' as const,
                  appealNote: finalNote,
                  appealCategory: appealCategory || acc.banInfo?.appealCategory,
                  appealPromiseAccepted: promiseAccepted ?? acc.banInfo?.appealPromiseAccepted,
                  appealCount: nextAppealCount,
                  appealSource: source,
                  appealRequestedAt: nowIso,
                },
              }
            : acc
        )
      : accounts;

    const nextBanSupport = appendBanAuditLog({
      action: 'appeal_submitted',
      accountId: targetAcc?.id,
      accountName: targetAcc?.fullName || googleUser?.name,
      accountNumber: targetAcc?.accountNumber,
      reason: finalNote,
      caseId: cfg.caseId,
      summary: `Pengajuan tinjauan ban (${source.toUpperCase()}) dikirim — Percobaan #${nextAppealCount}`,
    });

    if (targetAcc) {
      setAccounts(updatedAccounts);
    }
    setBanSupportConfig(nextBanSupport);
    flushMasterStateToCloud({ accounts: updatedAccounts, banSupportConfig: nextBanSupport });

    const targetUid = firebaseUser?.uid || targetAcc?.firebaseUid;
    const targetEmail =
      googleUser?.email || activeCloudEmail || targetAcc?.googleEmail || targetAcc?.email;
    await syncCloudUserProfile(
      { uid: targetUid, email: targetEmail || undefined },
      {
        appealStatus: 'pending',
        appealNote: finalNote,
        appealCategory: appealCategory || '',
        appealCount: nextAppealCount,
        appealSource: source,
        appealRequestedAt: nowIso,
      }
    );

    playAtmSound('success');
    return {
      success: true,
      message: 'Permohonan tinjauan Anda telah terkirim ke Panel Admin secara real-time!',
    };
  };

  const adminReviewUnifiedBanAppeal = async (
    accountId: string,
    action: 'approve' | 'reject',
    adminNote?: string
  ): Promise<{ success: boolean; message: string }> => {
    const target = accounts.find((a) => a.id === accountId);
    if (!target) {
      return { success: false, message: 'Rekening nasabah tidak ditemukan.' };
    }
    const cleanAdminNote = adminNote?.trim() || '';

    const targetUid =
      target.firebaseUid ||
      (firebaseUser &&
      ((target.googleEmail && normalizeEmailKey(target.googleEmail) === normalizeEmailKey(googleUser?.email || '')) ||
        target.id === currentAccountId)
        ? firebaseUser.uid
        : undefined);

    if (action === 'approve') {
      const nextAccounts: BankAccount[] = accounts.map((acc) =>
        acc.id === accountId
          ? {
              ...acc,
              status: 'active' as const,
              banReason: '',
              cardStatus: 'active' as const,
              banInfo: undefined,
            }
          : acc
      );
      setAccounts(nextAccounts);
      flushMasterStateToCloud({ accounts: nextAccounts });

      await syncCloudUserProfile(
        {
          uid: targetUid,
          email: target.googleEmail || target.email,
          fallbackEmail: target.email,
        },
        {
          status: 'active',
          banReason: '',
          appealStatus: 'approved',
          appealAdminNote: cleanAdminNote || 'Banding disetujui Admin, akun dibuka kembali.',
        }
      );

      addNotification(
        '🔓 Banding Diterima — Akun Dibuka Kembali!',
        `Tinjauan akun ${target.fullName} (${target.accountNumber}) disetujui Admin. Akun kini aktif normal.`,
        'success',
        { category: 'keamanan', targetView: 'dashboard', accountId: target.id }
      );
      playAtmSound('success');
      return {
        success: true,
        message: `Tinjauan disetujui! Akun ${target.fullName} telah dibuka dari status Banned.`,
      };
    } else {
      const nextAccounts: BankAccount[] = accounts.map((acc) =>
        acc.id === accountId
          ? {
              ...acc,
              banInfo: acc.banInfo
                ? {
                    ...acc.banInfo,
                    appealStatus: 'rejected' as const,
                    appealAdminNote:
                      cleanAdminNote || 'Permohonan tinjauan ditolak oleh Admin.',
                  }
                : undefined,
            }
          : acc
      );
      setAccounts(nextAccounts);
      flushMasterStateToCloud({ accounts: nextAccounts });

      await syncCloudUserProfile(
        {
          uid: targetUid,
          email: target.googleEmail || target.email,
          fallbackEmail: target.email,
        },
        {
          appealStatus: 'rejected',
          appealAdminNote: cleanAdminNote || 'Permohonan tinjauan ditolak oleh Admin.',
        }
      );

      playAtmSound('beep');
      return {
        success: true,
        message: `Permohonan tinjauan ${target.fullName} ditolak.`,
      };
    }
  };

  // ================= WEBSITE SYSTEM POPUP NOTIFICATIONS =================
  const lastSyncEpochRef = useRef<number>(0);
  const isApplyingExternalSnapshotRef = useRef<boolean>(false);
  const hasBootHydratedRef = useRef<boolean>(false);

