    const nowMs = Date.now();
    const nowIso = new Date(nowMs).toISOString();
    const nextTombstones = recordDeletedAdminItemIds('supportFaqs', [id]);
    const nextRev = (adminConfigRevisionMapRef.current.supportFaqs || 0) + 1;
